import { useCallback, useEffect, useRef, useState } from 'react';
import { IMG_LOAD_TIMEOUT_MS, imgRetryDelayMs } from './imgRetry';

/**
 * ★★DEV-383：图片「失败 ⇒ 退避重试 ⇒ 用尽后给一个可点的重载入口」的<b>状态机</b>。
 *
 * <h2>为什么是一个 hook，而不是给 SmartImg 与 antd 各写一份</h2>
 *
 * <p>本批有两类图片渲染面，它们<b>拿到失败信号的机制完全不同</b>：
 *
 * <ul>
 *   <li><b>原生 {@code <img>}</b>（{@code SmartImg}）：{@code onError} 直接可用，
 *       {@code onLoad} 也是自己的；</li>
 *   <li><b>antd {@code <Image>}</b>（消息气泡图 / 附件缩略图 / 正文内联图 /
 *       文件面板 / 合并转发）：{@code rc-image} 的 {@code useStatus} 会
 *       <b>先自己预加载探测</b>，失败就把 DOM 里那张 {@code <img>} 的
 *       {@code src} 换成 {@code fallback}（{@code useStatus.js} 的
 *       {@code srcAndOnload}）—— 所以<b>调用点不能再传 {@code fallback}</b>，
 *       否则原图根本不进 DOM、外部 {@code onError} 永远不会触发
 *       （这正是改造前那三处"一次失败即终态"的成因）。</li>
 * </ul>
 *
 * <p>但"失败了怎么办"是<b>同一件事</b>：等 1 秒、等 3 秒、然后用尽。
 * 两份实现就意味着两份会各自漂移的退避计划，而它们的口径是用户同一次拍板的。
 * 所以状态机只有这一份，两侧只负责各自的"怎么把失败喂进来 / 怎么把图重新挂上去"。
 *
 * <h2>★★重试为什么必须换 {@code key}（否则"重试"是个空动作）</h2>
 *
 * <p>{@link ImageRetryState#attempt} 是<b>给调用点当 {@code key} 用的</b>：
 * {@code src} 没变的时候，React 会复用同一个 {@code <img>} 元素、只做属性比对，
 * 浏览器<b>不会重新发起请求</b> —— 也就是说"把 failed 置回 false 再渲染一次"
 * 看着像重试、实际上一张图都不会再要。只有 {@code key} 变了才会卸载重挂，
 * 那才是真正意义上的"再试一次"。
 *
 * <h2>★超时为什么不能只靠 {@code onError}（这是本批最容易漏的一半）</h2>
 *
 * <p>有一整类失败不产生任何事件：请求发出去了，对端既不响应也不拒绝。
 * 浏览器的 {@code <img>} 会一直挂着——不 load、不 error。只加重试不配超时的话，
 * 这一类恰恰是重试<b>永远轮不到</b>的那一类（用户看到的就是永久空白）。
 * 所以这里另有一层 {@link IMG_LOAD_TIMEOUT_MS} 的表：到点仍没有结论就当作失败。
 *
 * <h2>★★"到点了"与"是不是真的失败"是两件事</h2>
 *
 * <p>超时表到点时<b>不能直接判失败</b>：图可能正在慢慢加载（大图 / 弱网），
 * 直接重试会把一张<b>马上就好</b>的图中断重来，反而更慢。
 * 所以到点先做一次<b>探测</b>（另起一个 {@code new Image()} 问同一个地址）：
 *
 * <ul>
 *   <li>探测<b>拿到</b> ⇒ 说明这个地址现在能取到 ⇒ 判为"其实已经好了"，
 *       <b>停表不再打扰</b>（此后若真的又失败，{@code onError} 会再来一次）；</li>
 *   <li>探测<b>拿不到</b> ⇒ 才走失败流程（重试 / 用尽）。</li>
 * </ul>
 *
 * <p>★探测只在"超时"这条<b>异常路径</b>上发生 —— 正常加载成功的图一次额外请求都没有。
 */

/** 探测自身的兜底：连探测都挂住时，就当它失败（否则这一层兜底自己会挂住）。 */
function probeImage(url: string, timeoutMs: number): Promise<boolean> {
  return new Promise<boolean>((resolve) => {
    // ★非浏览器环境（node 单测 / 预渲染）没有 Image 构造器。
    //   这时**不能**返回 false —— 那会把"环境不支持探测"当成"图坏了"，
    //   而这条路径只在超时后走到，误判的后果是给一张其实正常的图挂上重试。
    if (typeof Image === 'undefined') {
      resolve(true);
      return;
    }
    let done = false;
    const finish = (ok: boolean) => {
      if (done) return;
      done = true;
      resolve(ok);
    };
    const probe = new Image();
    probe.onload = () => finish(true);
    probe.onerror = () => finish(false);
    setTimeout(() => finish(false), timeoutMs);
    probe.src = url;
  });
}

export interface UseImageRetryOptions {
  /**
   * ★是否启用重试与超时。{@code false} ⇒ 退回改造前的"一次失败即终态"。
   *
   * <p>存在的理由是<b>头像类坑位要能保持不变</b>：会话列表 / 成员面板 / 联系人
   * 一屏可能有几十上百颗头像，给它们统统挂上重试会让一次断网产生成百上千次
   * 重试请求（用户拍板的口径是"按钮只给内容型图片"，重试同理）。
   */
  enabled?: boolean;
  /** 超时阈值，默认 {@link IMG_LOAD_TIMEOUT_MS}。 */
  timeoutMs?: number;
}

export interface ImageRetryState {
  /** ★当前是第几次尝试（0 = 首次）。**必须挂到元素的 {@code key} 上**，见文件头。 */
  attempt: number;
  /** ★重试已用尽 ⇒ 调用点应渲染「重新加载」按钮（或兜底节点），而不是继续等。 */
  exhausted: boolean;
  /** 交给图片元素的 {@code onError}。 */
  onError: () => void;
  /** 交给图片元素的 {@code onLoad}（原生 {@code <img>} 有效；antd 侧可能被其内部吞掉，见文件头）。 */
  onLoad: () => void;
  /** 「重新加载」按钮的点击处理：**从第 0 次重新开始**（不是接着第 3 次往后）。 */
  reload: () => void;
}

export function useImageRetry(
  src: string | null | undefined,
  options: UseImageRetryOptions = {},
): ImageRetryState {
  const { enabled = true, timeoutMs = IMG_LOAD_TIMEOUT_MS } = options;

  const [attempt, setAttempt] = useState(0);
  const [exhausted, setExhausted] = useState(false);

  /**
   * ★渲染期校正（与 {@code SmartImg} 里那段同款）：{@code src} 一变就立刻从头再来，
   * 并让 React 丢弃当前这一帧。
   *
   * <p>用 {@code useEffect} 的话，换过 src 的那一帧仍带着**上一张图**的
   * {@code exhausted=true} ⇒ 会先闪一下"重新加载"按钮再变回图。
   * 列表按位置复用组件时（会话切换、消息列表重排）这个闪烁尤其明显。
   */
  const [lastSrc, setLastSrc] = useState(src);
  if (lastSrc !== src) {
    setLastSrc(src);
    setAttempt(0);
    setExhausted(false);
  }

  // ★失败流程里要读"现在是第几次""是不是已经用尽"，而 setTimeout / Promise 的
  //   回调闭包拿到的是**登记那一刻**的值 ⇒ 一律走 ref 读最新值，不用 state。
  const attemptRef = useRef(attempt);
  attemptRef.current = attempt;
  const exhaustedRef = useRef(exhausted);
  exhaustedRef.current = exhausted;
  /** 本轮是否已经确认加载成功（收到过 {@code onLoad}）。 */
  const loadedRef = useRef(false);

  const retryTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const clearRetryTimer = useCallback(() => {
    if (retryTimerRef.current != null) {
      clearTimeout(retryTimerRef.current);
      retryTimerRef.current = null;
    }
  }, []);

  /** ★失败（明确报错，或超时探测确认拿不到）⇒ 按退避计划排下一次，没得排就用尽。 */
  const fail = useCallback(() => {
    if (!enabled || exhaustedRef.current) return;
    const delay = imgRetryDelayMs(attemptRef.current);
    if (delay == null) {
      // ★用尽：停在"给用户一个可点的按钮"这个状态，而不是继续无限重试。
      setExhausted(true);
      return;
    }
    clearRetryTimer();
    retryTimerRef.current = setTimeout(() => {
      retryTimerRef.current = null;
      // ★attempt 一变，调用点的 key 跟着变 ⇒ 元素卸载重挂 ⇒ 这才真的重新发请求。
      setAttempt((a) => a + 1);
    }, delay);
  }, [enabled, clearRetryTimer]);

  const onError = useCallback(() => {
    fail();
  }, [fail]);

  const onLoad = useCallback(() => {
    loadedRef.current = true;
    clearRetryTimer();
  }, [clearRetryTimer]);

  const reload = useCallback(() => {
    clearRetryTimer();
    loadedRef.current = false;
    setExhausted(false);
    setAttempt(0);
  }, [clearRetryTimer]);

  /** 每一次尝试（attempt 变）都重新起一张超时表；src 变了同样从头起。 */
  useEffect(() => {
    if (!enabled || exhausted || !src) return;
    // ★新一轮尝试：上一轮的"成功"结论不适用于这一次。
    loadedRef.current = false;
    let alive = true;
    const timer = setTimeout(() => {
      if (!alive) return;
      // ★已经 onLoad 过就别探测（原生 img 这条路能走到，省一次请求）。
      if (loadedRef.current) return;
      void probeImage(src, timeoutMs).then((ok) => {
        if (!alive) return;
        if (ok) {
          // ★探测拿得到 ⇒ 图其实已经好了，停表（此后真的再坏，onError 会回来）。
          loadedRef.current = true;
          return;
        }
        fail();
      });
    }, timeoutMs);
    return () => {
      alive = false;
      clearTimeout(timer);
    };
  }, [src, attempt, exhausted, enabled, timeoutMs, fail]);

  /** 卸载时把待触发的重试表清掉（列表滚动时会有大量实例反复挂卸）。 */
  useEffect(() => clearRetryTimer, [clearRetryTimer]);

  return { attempt, exhausted, onError, onLoad, reload };
}
