function digestOf(c: ConversationSummaryDto, selfId: number | string): string {
  return stripMdMark(digestWithPrefix(c, selfId));
}

/**
 * 先按服务端规则拼出摘要（含「我: 」/「张三: 」前缀），再交给
 * {@link stripMdMark} 做展示层加工。
 *
 * <p>★两步必须分开：前缀判定（{@code raw.startsWith(senderPrefix)}）与「撤回」判定
 * 都是拿**服务端原文**做的，先剥标记会让这两处判定失效 ——
 * 例如发送者昵称恰好叫「**张三**」时前缀就再也匹配不上了。
 */
function digestWithPrefix(c: ConversationSummaryDto, selfId: number | string): string {
  const raw = c.lastMsgDigest ?? '';
  if (!raw) return '';
  // ★服务端 ImDigests 规则：群聊摘要自带「发送者名: 」前缀，单聊不带（飞书行为）。
  //   前端再拼 lastSenderName 会输出「张三: 张三: xxx」（S8 E2E 观感 bug，DEV-117）。
  const senderPrefix = c.lastSenderName ? `${c.lastSenderName}: ` : '';
  const hasServerPrefix = !!senderPrefix && raw.startsWith(senderPrefix);
  if (!sameId(c.lastSenderId, selfId)) return raw; // 他人消息：直接用服务端摘要
  // 自己发的：系统式摘要（「张三 撤回了一条消息」，本身已含人名）原样显示，避免「我: 张三 撤回了…」；
  // 常规消息剥掉服务端前缀后统一冠「我: 」
  if (raw.includes('撤回了一条消息')) return raw;
  return hasServerPrefix ? `我: ${raw.slice(senderPrefix.length)}` : `我: ${raw}`;
}

function timeStr(ms?: number): string {
  if (!ms) return '';
  const d = new Date(ms);
  const now = new Date();
  if (d.toDateString() === now.toDateString()) {
    return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
  }
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

/**
 * 飞书式会话列表项：圆头像（未读红点叠右上角）+ 名称/时间 + 摘要一行。
 * 置顶/免打扰仍走右键菜单（与飞书一致），并在名称旁以小图标常驻提示。
 */
/**
 * ★DEV-172：把 {@link gateStep} 接到 React 上。
 *
 * <p>★这个 hook **只负责驱动定时器**，一个判据都不在这里 —— 阈值逻辑全部在
 * {@code lib/skeletonGate.ts}（纯函数、有单测）。放在这里是因为它需要 React，
 * 而 {@code lib/} 下都是能被 {@code pnpm test} 直接编译的纯模块。
 *
 * <p>★依赖数组只有 {@code pending}：{@code nextCheckAt} 驱动的定时器在内部自我
 * 延续，直到门控给出终态（{@code nextCheckAt === null}）为止。
 * 把 {@code visible} 或状态对象也放进依赖会立刻变成"设置状态 → 重跑 effect →
 * 再设置状态"的死循环。
 */
function useSkeletonGate(pending: boolean): boolean {
  const stateRef = useRef<GateState>(INITIAL_GATE_STATE);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    const tick = () => {
      const r = gateStep(stateRef.current, pending, Date.now());
      stateRef.current = r.state;
      setVisible(r.visible);
      if (r.nextCheckAt != null) {
        timer = setTimeout(tick, Math.max(0, r.nextCheckAt - Date.now()));
      }
    };
    tick();
    return () => clearTimeout(timer);
  }, [pending]);
  return visible;
}

/**
 * ★DEV-172：会话列表骨架 —— 与真实行**同构**（36px 圆头像 + 两行短线、同样的
 * 12px/8px 内边距），所以数据到达时是"文字填进去"而不是"换了一张皮"。
 */
function ConvSkeleton() {
  return (
    <div className="conv-skeleton" aria-busy="true" aria-label="会话列表加载中">
      {[0, 1, 2, 3, 4].map((i) => (
        <div className="sk-row" key={i}>
          <div className="sk-avatar" />
          <div className="sk-lines">
            <div className="sk-line sk-line-1" />
            <div className="sk-line sk-line-2" />
          </div>
        </div>
      ))}
    </div>
  );
}

export default function ConvList() {
  const convs = useChatStore((s) => s.convs);
  /**
   * ★★DEV-401：各会话的草稿正文（**读侧**；写它的是 {@code ChatWindow} —— 用户在那儿打字）。
   *
   * <p>★这是本批唯一新增的跨组件通道：草稿原本只活在 {@code ChatWindow} 的局部 ref 里，
   * 而会话列表在另一个组件，除了 store 没有别的路（见 {@code ChatState.draftTextByConv}）。
   * <p>★它变化得很频繁（打字期间每 300ms 左右一次），但**值相同就不写**（见 store 里
   * {@code setDraftText} 的短路）⇒ 这里不会因为"用户点了一下"就白重渲染一轮。
   */
  const draftTextByConv = useChatStore((s) => s.draftTextByConv);
  const contacts = useChatStore((s) => s.contacts);
  /**
   * ★★DEV-172：{@code convs.length === 0} 说明不了任何事 —— 它既可能是"还没拉到"，
   * 也可能是"拉到了，就是没有"。下面这个 phase 才是那个区分。
   */
  const phase = useChatStore((s) => s.convListPhase);
  /** ★DEV-173：正展示缓存、而后台刷新失败了（★与 phase==='failed' 互斥，见 store 里的注释）。 */
  const convListRefreshFailed = useChatStore((s) => s.convListRefreshFailed);
  const convsCachedAt = useChatStore((s) => s.convsCachedAt);
  const loadConversations = useChatStore((s) => s.loadConversations);
  /**
   * ★★DEV-374：会话列表的<b>游标分页</b>四件套（本批新增）。
   *
   * <p>★<b>组件这里一个判据都不持有</b>：能不能续拉、在不在飞、失败没有，
   * 全部由 store 回答（见 {@code ChatState.loadMoreConversations} 上的三道闸门）。
   * 这是与母版 {@code ChatFilesPanel} 的<b>有意差异</b> —— 那边是单组件的局部状态，
   * 用 {@code useRef} 自己防重入就够了；会话列表是全局状态、有<b>两个</b>触发入口
   * （用户滚动 + 首屏未填满时的自动补），各存一份守卫等于两套判据。
   */
  const convsHasMore = useChatStore((s) => s.convsHasMore);
  const loadingMoreConvs = useChatStore((s) => s.loadingMoreConvs);
  const convsLoadMoreFailed = useChatStore((s) => s.convsLoadMoreFailed);
  const loadMoreConversations = useChatStore((s) => s.loadMoreConversations);
  const activeConvId = useChatStore((s) => s.activeConvId);
  const userId = useChatStore((s) => s.userId) ?? 0;
  // ★★DEV-322 ②：自环会话（我与自己）标题显示"我自己的真实姓名"，没加载出来回落兜底
  //   （裁决收在 lib/convTitle 的 selfDisplayTitle 一处）。作为 convTitle 第四参传下去。
  const userName = useChatStore((s) => s.userName);
  const selectConv = useChatStore((s) => s.selectConv);
  const toggleTop = useChatStore((s) => s.toggleTop);
  const toggleDnd = useChatStore((s) => s.toggleDnd);
  const deleteConversation = useChatStore((s) => s.deleteConversation);
  const { message: toast, modal } = AntApp.useApp();

  /**
   * ★★DEV-374：滚动容器的 ref。
   *
   * <p>★注意容器就是根节点自己（{@code .conv-list} 在 CSS 里是
   * {@code flex:1; overflow-y:auto}）。{@code onScroll} 用 {@code e.currentTarget}
   * 就够了，这个 ref <b>只</b>给下面那条"首屏没填满就自动续拉"的 effect 用
   * —— 它需要在<b>没有滚动事件</b>的情况下读一次几何。
   */
  const listRef = useRef<HTMLDivElement | null>(null);

  /**
   * ★★DEV-401（用户原话：「如果用户对话框有输入，像微信这样，也要放到前面去，显示 [草稿]」）：
   * **这一帧里哪些会话有草稿、那一行摘要是什么**。
   *
   * <h3>★这张表回答什么</h3>
   * <p><b>"这一帧里哪些会话有草稿、那一行摘要是什么"</b> —— 顺序（{@link liftDraftConvs}）
   * 与那一行画什么，两处读<b>同一张表</b>，不会出现"排到最前面了、摘要行却还是最后一条消息"
   * 这种两边各自看起来都对的分叉。
   *
   * <h3>★★DEV-423：上浮集合与显示集合**故意不同**</h3>
   * <p>用户原话：「有草稿的会话会顶到上面去，但是选中有草稿的会话后他又回到了原来的位置，
   * 这里需要保持不动」。
   * <ul>
   *   <li><b>上浮</b>：只要会话有草稿就参与分区，<b>包括当前正打开的那条</b>。否则用户
   *       一点进去，它就"跳回原位" —— 正是这次要修的抖动。</li>
   *   <li><b>显示 {@code [草稿]} 标签</b>：当前会话仍然<b>不显示</b>（用户已拍板的
   *       DEV-401 口径②保留：正文就在用户眼前，没必要再贴一个标签）。排除动作放在
   *       渲染那一行，本表<b>不</b>排除。</li>
   * </ul>
   * <p>⇒ 本 {@code useMemo} <b>不依赖</b> {@code activeConvId}：切会话不会让整张表重算，
   * 上浮次序也就不会被"当前会话"这个易变维度带着抖。
   *
   * <h3>★摘要为什么在这里算，而不是渲染时再算</h3>
   * <p>{@link draftSummaryOf} 是 O(草稿长度)：线上真实负载里有 6.5 万字节的提示词
   * （DEV-361 的现场），而列表每次重渲染（收到任何一条消息都会）都要把整表画一遍 ——
   * 算一次存下来，比"每次渲染逐条重新折叠"便宜得多。
   *
   * <p>★判定用 {@link hasDraftText}（trim 非空）：DEV-423 起"只有图片"的草稿在写侧
   * 已经折算成 {@code [图片]} 文本，所以这里不需要知道图的存在 —— 写侧是唯一真源。
   */
  const draftByConv = useMemo(() => {
    const map = new Map<string, string>();
    for (const c of convs) {
      const raw = draftTextByConv[String(c.convId)];
      if (!hasDraftText(raw)) continue;
      map.set(String(c.convId), draftSummaryOf(raw));
    }
    return map;
  }, [convs, draftTextByConv]);

  /**
   * ★★DEV-401：列表最终顺序 =（store 里已按服务端 {@code ListOrder} 排好的）{@code convs}
   * ＋「有草稿的提到非置顶区最前」这一次<b>稳定分区</b>。
   *
   * <p>★为什么不去改排序本身：排序键是与后端逐级对齐的<b>服务端字段</b>（那套对齐还有一条
   * 文本守卫用例钉着），而草稿是<b>纯本地态</b> —— 塞进去会同时污染排序键表、那条守卫用例、
   * 以及"本地顺序与后端同序"这个<b>分页前提</b>（DEV-374）。详见 {@code lib/convDraft.ts} 头注释。
   * <p>★置顶区不受影响：用户手动置顶的意图比"临时打了个字"强（分区口径写死在那里）。
   * <p>★★DEV-423：这里<b>不再排除当前会话</b> —— 用户点开有草稿的会话后，它必须留在
   * 上浮区不动（`[草稿]` 标签由渲染那一行单独隐藏，见 {@code draftByConv} 的说明）。
   */
  const orderedConvs = useMemo(
    () => liftDraftConvs(convs, (c) => draftByConv.has(String(c.convId))),
    [convs, draftByConv],
  );

  /**
   * ★★DEV-374：滚到底自动续拉。
   *
   * <p>★阈值 {@code 48}px 与母版 {@code ChatFilesPanel} 一致（提前一点触发，
   * 用户滚到底时下一页往往已经到了）。★判据用 {@code e.currentTarget} 而不是
   * 去查 DOM：事件里的那个元素<b>就是</b>滚动容器，另查一次反而会在
   * "同时开了多个面板"这类场景取错元素。
   *
   * <p>★这里<b>不</b>判 {@code convsHasMore} / 防重入 —— 全部由 store 回答
   * （见上面四件套的注释）。组件多做一次判断就等于多一处会与 store 分叉的判据。
   */
  const onListScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const el = e.currentTarget;
    if (el.scrollHeight - el.scrollTop - el.clientHeight >= SCROLL_TRIGGER_PX) return;
    void loadMoreConversations();
  };

  /**
   * ★★DEV-374：<b>首屏没填满一屏时自动再拉一页</b>。
   *
   * <h3>★不加这条会死锁</h3>
   * <p>续拉的唯一入口是 {@code onScroll}，而滚动事件<b>只有内容超过容器高度才会产生</b>。
   * 第一页只有几条（或去重后剩下的很少）时，列表撑不满一屏 ⇒ <b>永远滚不动</b>
   * ⇒ {@code onScroll} 永远不触发 ⇒ 后面几页永远拿不到。用户看到的是
   * "就这么几条，没有更多了"，而服务端其实还有。
   *
   * <h3>★为什么会自己停（不会变成请求泵）</h3>
   * <ol>
   *   <li>内容一旦超过容器高度 ⇒ 直接返回，把控制权交给用户的滚动；</li>
   *   <li>{@code convsHasMore} 为假（翻完了）⇒ 返回；</li>
   *   <li>★{@code convsLoadMoreFailed} 为真 ⇒ <b>返回</b>。这一条是必需的：
   *       续拉失败时"拉了一页但没内容"与"网络坏了"在几何上<b>完全同形</b>
   *       （容器还是没填满），不排除的话就是这个 effect 自己触发的无限重试。
   *       ★失败后的重试只能由用户点底部那个「点击重试」发起 —— 那是显式意图。</li>
   * </ol>
   * <p>★依赖里放 {@code convs.length} 是刻意的：它是"又拉到了一页"的信号，
   * 没有它就只能在 {@code hasMore}/{@code loading} 变化时重查，而这两者在
   * "成功追加了一页但还没填满"时<b>都不变</b>（hasMore 仍是 true、loading 又回到 false）
   * ⇒ 补拉会停在半途。
   */
  useEffect(() => {
    if (phase !== 'ready' || !convsHasMore || loadingMoreConvs || convsLoadMoreFailed) return;
    const el = listRef.current;
    // ★读不到元素（还没挂载 / 已被卸载）时不做任何事：这是正常的中间态，不是错误。
    if (!el) return;
    // ★已经能滚了 ⇒ 交给用户。用 `>` 而不是 `>=`：恰好相等时（内容与容器一样高）
    //   也滚不动，那种情况应该继续补。
    if (el.scrollHeight > el.clientHeight) return;
    void loadMoreConversations();
  }, [phase, convsHasMore, loadingMoreConvs, convsLoadMoreFailed, convs.length, loadMoreConversations]);

  /**
   * ★★DEV-278：<b>用户主动点出来的动作，失败必须说出来。</b>
   *
   * <p>本组件里原来三处是 {@code .catch(() => undefined)} ——「打开会话」「置顶」
   * 「消息免打扰」，点了既没成功也没报错，界面<strong>静默地什么都不做</strong>。
   *
   * <p>用户报的现象 2（「有些会话的历史消息没有展示出来」，刷新后又好了）就是它盖住的：
   * {@link selectConv} 会<b>同步先</b>把 {@code activeConvId} 切过去，随后的
   * {@code GET /conversations/{id}/messages} 一旦失败，右栏就停在空白，
   * 而这次失败<strong>连一条日志都没留下</strong> ⇒ 间歇、无痕、无从复现、只能靠猜。
   * 把失败说出来之后，同样的故障至少能被用户看见、被我们接手。
   *
   * <p>★★范围是刻意的：<b>只改这三处</b>，不做全仓清扫。
   * {@code .catch(() => undefined)} 在本仓是 <b>98 处 / 17 个文件</b>的在用写法，
   * 其中大多数是<b>调用方主动选择吞掉</b>（典型如 {@code loadConversations} 的重试：
   * 失败已经写进 {@code convListPhase}/{@code convListRefreshFailed} 两个状态，
   * 界面照常给出「会话列表加载失败 + 点击重试」，再弹一个 toast 才是重复）。
   * 本题只处理这一类：<b>点了之后界面上既没有结果、也没有说法</b>。
   *
   * @param what 失败时兜底的动名词（服务端给了 message 就用服务端的，
   *   那句通常更具体，例如 {@code IM_40003 你不是该会话成员}）。
   */
  const reportFail = (e: unknown, what: string) => {
    toast.error(e instanceof Error && e.message ? e.message : `${what}失败`);
  };

  /**
   * ★★DEV-172：「还没问」与「问过是没有」是两件事，这里把它们分开。
   *
   * <p>{@code idle} 也算未就绪 —— 它是 {@code enterSession} 里 {@code set(userId)}
   * 之后、{@code loadConversations} 置 {@code loading} 之前的那一瞬。
   * 那一瞬同样"没有任何结论"，把它当成"空"就是本次要修的那个 bug。
   */
  const pending = phase === 'idle' || phase === 'loading';
  /**
   * ★{@code && convs.length === 0} 是必需的：列表非空时的后台刷新
   * （重连 / 建群 / 退群触发的那几次 loadConversations）不该把一份好端端的列表
   * 打回灰条 —— 用户会以为消息丢了。
   */
  const showSkeleton = useSkeletonGate(pending && convs.length === 0);

  /**
   * ★删除会话（DEV-165）= 只从我的「消息」列表里去掉（服务端 {@code visible = false}）。
   *
   * <p>★★确认文案必须写明"它还找得回来"。这个操作<b>看起来</b>像"删除"，
   * 用户最怕的是"点下去这个群就没了" —— 而事实正相反：群还在、消息还在、
   * 我还收得到消息，而且有一条明确的找回路径。不写清楚的话，
   * 用户要么不敢点，要么点完以为永久丢失了。
   *
   * <p>★单聊与群的找回路径不同，所以要分开写：
   * 群在「智联录 → 我的群组」，人在「智联录」的联系人里。
   * ★DEV-201：「我的群聊」→「我的群组」（用户对这一层的叫法），见 ContactList 的入口行。
   *
   * <p>★★DEV-242：<b>团队群（convType=4）的文案要单独写一句</b>，不能并进"群"那一支 ——
   * 它<b>不在</b>「我的群组」里（那是 IM 自建群），而在「我的团队」里，
   * 按旧文案提示用户去「我的群组」找是找不到的（下文标签页也印证：群组列表只查自建群）。
   * ⇒ 三支：自建群 / 团队群 / 单聊。
   */
  const onDelete = (c: ConversationSummaryDto) => {
    modal.confirm({
      title: `删除会话「${convTitle(c, userId, remarkOf(contacts, c.peerUserId), userName)}」？`,
      content:
        c.convType === CONV_TYPE_TEAM
          ? '只从你的消息列表里去掉，不影响团队和聊天记录；之后可以在「智联录 → 我的团队」里重新打开。'
          : c.convType === CONV_TYPE_GROUP
            ? '只从你的消息列表里去掉，不影响群和聊天记录；之后可以在「智联录 → 我的群组」里重新打开。'
            : '只从你的消息列表里去掉，聊天记录不会被删除；之后可以在「智联录」的联系人里重新打开。',
      okText: '删除',
      cancelText: '取消',
      okButtonProps: { danger: true },
      onOk: async () => {
        try {
          // ★成功不弹提示：那一行从列表里消失本身就是最好的反馈，
          //   再加一个"已删除"是噪音（与「置顶」这类静默操作一致）。
          await deleteConversation(c.convId);
        } catch (e) {
          // ★★DEV-278：文案与判据收进 reportFail —— 本组件里"失败怎么说话"只有一处实现。
          reportFail(e, '删除');
        }
      },
    });
  };

  return (
    <div className="conv-list" ref={listRef} onScroll={onListScroll}>
      {/* ★★DEV-316 ①（用户纠正 DEV-315 ④ 的落点）：这里**曾经**有一个列表内搜索框
          （DEV-315 ④），用户拍板撤掉 —— 搜索只保留在顶栏放大镜弹出的「搜索」弹框里，
          包含匹配由后端治本（弹框「会话」Tab 私聊按对方昵称/备注名可搜、显示正确名字）。
          ★本段注释是那次撤销的**墓碑**：防止下一个批次再把它加回来。 */}
      {/* ★★DEV-173：缓存细条。★它<b>不覆盖</b>列表 —— 只在列表上方加一行说明。
          ★只在"有内容 + 正展示缓存 + 后台刷新失败"三条同时成立时出现：
            刷新成功时内容会被原地替换，标不标都已经是最新的；
            刷新还在飞时更不该标 —— 那会让每次正常打开都闪一行字，
            而"会自己消失的提示"本身就是一次闪（DEV-168 起一路在消灭的东西）。
          ★措辞是"未连上服务器"而不是"加载失败"：列表能用、能点、能读，
            说"失败"会让人以为刚才看到的都是废的。 */}
      {convListRefreshFailed && convs.length > 0 && (
        <div className="conv-stale-bar">
          <span>
            显示的是本地缓存
            {convsCachedAt != null ? `（${cacheAgeText(convsCachedAt, Date.now())}）` : ''}
          </span>
          <span className="conv-stale-sep">·</span>
          <span>未连上服务器</span>
          <button
            className="conv-retry"
            onClick={() => {
              loadConversations().catch(() => undefined);
            }}
          >
            重试
          </button>
        </div>
      )}
      {/* ★★DEV-401：遍历的是**分区后**的列表（草稿会话已提到前面），不是 store 里那份
          —— 排序仍然由 store 的 sortConvs 决定，分区只在它之上多一个维度。 */}
      {orderedConvs.map((c) => {
        // ★★DEV-242：团队群（4）也算群 —— 下面用它决定"未读是否按群口径显示"等。
        //   写成 `=== 2` 会让团队群被当成单聊渲染（见 lib/convType.ts 的说明）。
        const isGroup = isGroupConv(c.convType);
        const title = convTitle(c, userId, remarkOf(contacts, c.peerUserId), userName);
        const unread = c.unreadCount ?? 0;
        /**
         * ★★DEV-401：这一行要显示的草稿摘要（`undefined` = 这条会话没草稿）。
         * ★★DEV-423：当前会话**参与上浮、但不在摘要行显示 [草稿]** —— 正文就在
         * 用户眼前的输入框里，再贴一个标签是噪音（口径②保留）。判据用 {@link sameId}
         * （String 归一）：{@code convId} 是 string，而 {@code activeConvId} 是
         * store 的 {@code Id}（可能是 number），直接 {@code !==} 会在同一个会话
         * 两种类型时判成"不是当前会话"，于是当前会话也顶上 [草稿]。
         */
        const draft = sameId(c.convId, activeConvId)
          ? undefined
          : draftByConv.get(String(c.convId));
        /**
         * ★★DEV-278（用户报的现象 2 的现场）：下面 conv-item 的 onClick 原来是
         * `.catch(() => undefined)`。
         *
         * <p>{@code selectConv} 会<b>同步先</b>把 {@code activeConvId} 切过去，
         * 所以它抛出来的必然是「消息没拉到」—— 吞掉的后果是右栏停在空白，
         * 用户以为这段聊天记录没了（他报的原话：「有些会话的历史消息没有展示出来」，
         * 而刷新后又好了 ⇒ 间歇、无痕）。
         *
         * <p>★为什么<b>不</b>用"回滚 activeConvId"收场：用户点的就是这条会话，
         * 把他弹回上一条比停在一条没拉到消息的会话上更莫名其妙；
         * 而且连点两条会话时，先失败那次的回滚还会把后一次的选择一起冲掉。
         *
         * <p>★留在原地是可恢复的：store 里 {@code msgStaleByConv[key]} 只有成功那一支
         * 才会置 false（见 selectConv 的 DEV-173 注释），所以失败后<b>再点一次就会重拉</b>。
         * 把失败说出来之后，用户看得见"刚才为什么是空的"，也就知道可以再点一次。
         */
        return (
          <Dropdown
            key={c.convId}
            trigger={['contextMenu']}
            menu={{
              items: [
                // ★★DEV-231 需求⑦（用户原话「会话列表里面的"Pin"还是改为置顶」）：
                //   本行文案**改回「置顶」**。这是对 DEV-229 ③（"所有置顶文案改 Pin"）
                //   的一次**局部回退**，不是全仓推翻 —— 两件事本来就不是一回事：
                //   这一项是 `top_flag`（**每个成员各自**把某个会话顶到列表最前），
                //   而 Pin 是 `im_message_pin`（**全群共享**地把一条消息顶到会话顶部，
                //   见 MessageBubble 的提示条与 Pin 标签页）。
                //   ★所以"消息域的 Pin 文案"（气泡提示条 / Pin 标签页 / IM_20107 错误码）
                //   一个字都不动，只有这里回退。
                { key: 'top', label: c.topFlag ? '取消置顶' : '置顶' },
                { key: 'dnd', label: c.dnd ? '取消免打扰' : '消息免打扰' },
                // ★分隔线：删除是破坏性操作，与上面两个开关不是一类 ——
                //   紧挨着排容易被误点（那两个点了还能再点回来，这个点完列表里就没有了）。
                { type: 'divider' as const },
                { key: 'delete', label: '删除会话', danger: true },
              ],
              onClick: ({ key }) => {
                // ★★DEV-278：这两个原来是 `.catch(() => undefined)`，而它们都带
                //   **乐观更新**（store 里先 `patchConv` 再 await）——
                //   静默失败的后果是界面显示「已置顶」，服务端其实没记下来，
                //   刷新之后又变回去，用户只会觉得"这个开关有毛病"。
                //   ★这里只让它说话，不做乐观回滚（回滚是另一个决定，见 docs/05 DEV-278 的残留）。
                if (key === 'top') toggleTop(c.convId, !c.topFlag).catch((e: unknown) => reportFail(e, c.topFlag ? '取消置顶' : '置顶'));
                if (key === 'dnd') toggleDnd(c.convId, !c.dnd).catch((e: unknown) => reportFail(e, c.dnd ? '取消免打扰' : '设置免打扰'));
                if (key === 'delete') onDelete(c);
              },
            }}
          >
            <div
              className={`conv-item${c.convId === activeConvId ? ' active' : ''}`}
              onClick={() => selectConv(c.convId).catch((e: unknown) => reportFail(e, '打开会话'))}
            >
              <div className="conv-avatar">
                {/* ★★DEV-201（用户原话「默认头像包括群头像和个人头像，根据首字随机使用
                    不同的颜色，不然千篇一律」）：底色改为**按 `title` 的首字取**。
                    ★传 `title` 而不是 `c.name` / `c.peerUserId`：与头像里画的字同源 ——
                      单聊画的就是 `title.slice(0,1)`，群画的是 `title` 的前四个字，
                      两个都由 `convTitle` 兜底过一次。用 userId 取色的话，
                      改名不会换色、而同一个人在两处（这里 vs 智联录）还要各算一次。
                    ★`title` 是超集判据：单聊是对方展示名、群是群展示名 ⇒ 一条规则覆盖两类。
                    ★`p2p` / `group` 两个类名**保留** —— 它们仍是形状/定位的锚，
                      也是 `verify-avatar-shape.mjs` 的定位器；只是不再承担**颜色**。 */}
                <div className={`avatar-circle ${isGroup ? 'group' : 'p2p'}`} style={avatarTone(title)}>
                  {(isGroup ? c.avatar : c.peerAvatar) ? (
                    /* ★★DEV-249 需求①：加载失败**必须回落成默认头像**（首字 + 底色），
                       不能留那个浏览器的破图图标。用户原话：「图片无法展示的不要展示
                       图裂的样子，展示默认头像」。
                       ★兜底用的 `title.slice(0, 1)` 与下面"没有头像"那一支**逐字同款**，
                         颜色也同源（外层 `.avatar-circle` 的 `avatarTone(title)`）。
                         ★不这样的话，"平台把头像删了"和"网断了"两种情况的观感会是两回事 ——
                         前者是漂亮的彩色首字，后者是一个灰方框加斜线，看起来像页面坏了。
                       ★为什么要有专门的组件：失败标记是 state，而这里是 `map` 里渲染的，
                         hook 不能写在循环里（详见 `components/SmartImg`）。
                       ★★DEV-290（用户原话「团队群组头像没有展示团队的头像」）：
                         群聊分支并入这一支 —— 旧写法条件是 `!isGroup && c.peerAvatar`，
                         群聊**永远**落到下面的 GroupAvatarText（库里有图也不显示）。
                         图源判据与顶栏（ChatWindow）逐字同款：群聊 = c.avatar、
                         单聊 = c.peerAvatar；群的兜底是 GroupAvatarText（不是首字）。 */
                    <SmartImg
                      src={isGroup ? c.avatar : c.peerAvatar}
                      alt=""
                      style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                      fallback={isGroup ? <GroupAvatarText name={title} /> : title.slice(0, 1)}
                    />
                  ) : isGroup ? (
                    /* ★DEV-190：群头像显示**群名前四个字**（DEV-188 时这里是实心人形图标）。
                       ★传的是 `title`（`convTitle` 的结果），**不是** `c.name` ——
                       头像必须与紧挨着它那行标题同源。不同源的话，同一个群会拿到两份
                       **各自兜底**的名字（convTitle 兜「群聊1001」、groupTitle 兜
                       「未命名群聊」），改任何一处的兜底口径都会冒出"头像和标题对不上"。
                       ★DEV-201 起配色由上面那行内联 `style={avatarTone(title)}` 给，
                       规则与顶栏、智联录共用同一个函数（不再是 CSS 里的一份固定值）。 */
                    <GroupAvatarText name={title} />
                  ) : (
                    title.slice(0, 1)
                  )}
                </div>
                {unread > 0 && (
                  <span className={`unread-dot${c.dnd ? ' dnd' : ''}`}>{unread > 99 ? '99+' : unread}</span>
                )}
              </div>
              <div className="conv-main">
                <div className="conv-name-row">
                  <span className="conv-name">
                    {/* ★DEV-231 需求⑦：与右键菜单同一处回退（理由见上面 `key: 'top'` 那段）。
                        ★这个 `title` 是**悬停提示**，读到它的用户比右键菜单少，
                        但两处必须一起改 —— 只改菜单会出现"图标提示写 Pin、
                        菜单写置顶"的分叉。
                        ★★注释写在 children 位置**必须**用 JSX 的花括号注释形式
                        （左花括号包住一个块注释），不能写裸的块注释 ——
                        裸的会被当成 JsxText **原样渲染到页面上**（tsc/test/build 全看不出来）。
                        ★★这段说明本身也在注释里，所以**不能**把那个形式原样写出来：
                        它的结尾是"星号 + 斜杠"，写在块注释内部会**提前把注释闭合掉**
                        ⇒ tsc 直接 TS1381 语法错（本行就是这么发现的）。 */}
                    {c.topFlag && (
                      <span className="flag-icon" title="置顶">
                        <IconPin size={12} />
                      </span>
                    )}
                    {c.dnd && (
                      <span className="flag-icon" title="免打扰">
                        <IconBellOff size={12} />
                      </span>
                    )}
                    {title}
                  </span>
                  <span className="conv-time">{timeStr(c.lastMsgAt)}</span>
                </div>
                {/**
                  * ★★DEV-401：有草稿 ⇒ 这一行显示**草稿**（顶掉"最后一条消息"的摘要），
                  * 与微信一致（他给的截图里那两条就是 `[草稿] sd` / `[草稿] s`）。
                  *
                  * ★只有这一行能承载它：卡片高度是硬约束（`.conv-item` 60px = 名称 20 +
                  * 摘要 16 + 上下内边距），加第二行会把整个列表的行高撑开 ——
                  * 而那一行本来是 `nowrap + ellipsis`，长草稿由浏览器截断。
                  * ★`[草稿]` 与正文之间的那个间距交给 CSS（`.draft-tag` 的 margin），
                  * 不在 JSX 里写空格 —— 写在这里的空格会被 JSX 的空白折叠规则吃掉。
                  */}
                <div className="conv-digest">
                  {draft != null ? (
                    <>
                      <span className="draft-tag">{DRAFT_TAG}</span>
                      {draft}
                    </>
                  ) : (
                    digestOf(c, userId) || '暂无消息'
                  )}
                </div>
              </div>
            </div>
          </Dropdown>
        );
      })}
      {/* ★★DEV-374：底部状态行 —— <b>续拉</b>的回执（只有它自己在飞/失败时才出现）。

          ★三态里"翻完了"那一态<b>刻意什么都不显示</b>：会话列表不像文件面板有明确的
            页码概念，底下常驻一句「没有更多了」在大多数用户那里是纯噪音
            （他们根本没滚到底），而且会把"暂无会话"那条空态的视觉权重抢走。
          ★★文案是「正在加载更早的会话」而不是「正在加载更多」：分页的语义是
            越往后越早（排序最后一级是 lastMsgAt 降序）—— 用「更多」会让用户
            以为底下会出现比当前更新的会话。
          ★失败那一支复用 `.conv-retry` —— 本组件里另外两处「重试」用的就是它
            （缓存细条那条在列表<b>上方</b>、整表失败那条在列表<b>下方</b>）：
            三个"重试"长得不一样会让人以为是三种不同的东西。 */}
      {loadingMoreConvs && <div className="conv-more-status">正在加载更早的会话…</div>}
      {!loadingMoreConvs && convsLoadMoreFailed && (
        <div className="conv-more-status">
          加载更早的会话失败
          <button
            className="conv-retry"
            onClick={() => {
              // ★只有用户点这里才会重试（上面那条 effect 在失败态下是直接返回的，
              //   否则几何判据会让它自己无限重试 —— 见 effect 注释第 3 条）。
              void loadMoreConversations();
            }}
          >
            点击重试
          </button>
        </div>
      )}

      {/* ★★DEV-172：三种"列表是空的"必须分开表达 —— 顺序即优先级。
          ★每个分支都要自己排除 showSkeleton：门控有 200ms 的最短显示期，
          在保持期内 phase 已经变成 ready/failed 了，不排除的话会出现
          "骨架和空态同时渲染"。 */}
      {!convs.length && showSkeleton && <ConvSkeleton />}

      {!convs.length && !showSkeleton && phase === 'failed' && (
        <div className="conv-empty conv-error">
          会话列表加载失败
          <br />
          {/* ★必须给重试入口：自动重连不会重拉这一份列表，
              没有按钮的话用户只能刷新整个页面。 */}
          <button
            className="conv-retry"
            onClick={() => {
              loadConversations().catch(() => undefined);
            }}
          >
            点击重试
          </button>
        </div>
      )}

      {/* ★只有 ready 才能说"暂无会话"。这是本次修复的**唯一**判据变更：
          在此之前条件是 `!convs.length`，于是"还没拉到"也被说成了"没有"。 */}
      {!convs.length && !showSkeleton && phase === 'ready' && (
        <div className="conv-empty">
          暂无会话
          <br />
          {/* ★DEV-160：原来这里写「发起单聊 / 创建群聊」两个按钮的名字，
              它们现在收进了右上角的「+」下拉里 —— 文案不改就会指向两个看不见的按钮。 */}
          点右上角「+」→「添加伙伴」开始聊天
        </div>
      )}
    </div>
  );
}

export { convTitle };
