/**
 * ★★会中「邀请参会人」面板 —— 从<b>我的联系人</b>里多选，逐个发入会通知。
 *
 * <h2>★★为什么是自绘面板，而不是 antd 的 Modal + Select</h2>
 *
 * <p>会中界面有两份宿主：本页，以及会议开始后默认落进去的<b>独立窗口</b>
 * （{@code MeetingPopout}，见 {@code CallOverlay} 的 standalone 注释）。独立窗口是
 * 另一个 document —— antd v5 的 cssinjs 只把样式注入<b>主文档</b>，那边弹出的
 * {@code Modal}/{@code Select} 会是一堆没有边框、没有间距的原生控件，位置还会跑出窗口。
 *
 * <p>本组件<b>只用项目自己的 CSS 类</b>（{@code styles.css}，独立窗口会整份克隆过去，
 * 见 {@code lib/meetingWindow}），因此两边长得完全一样；也正因为不依赖 antd，
 * 它在独立窗口里能正常滚动、置顶在会议画面之上。
 *
 * <h2>★候选来自 {@code store.contacts}（不是远程搜索）</h2>
 *
 * <p>用户原话就是「都是从自己的联系人里面拉」。那份名单登录时就整份拉过，
 * 关掉面板再打开不该再打网络；规则（只要 ACCEPTED、排除已在会的人、按名字排序）
 * 全部走 {@code lib/contactPicker} 的纯函数 —— 与建群/加人的选人器同一把尺子。
 *
 * <h2>★发送结果就地显示</h2>
 *
 * <p>独立窗口里 {@code AntApp.useApp()} 的 message 挂在主文档上（用户根本看不见），
 * 所以这里<b>不弹 toast</b>，把"已邀请 N 人 / 谁没发出去"写在面板里。
 */
import { useMemo, useState } from 'react';

import { avatarTone } from '../lib/avatarTone';
import { contactTitle } from '../lib/contact';
import { PICK_CONTACT_LIMIT, pickHintText, pickMyContacts } from '../lib/contactPicker';
import { formatMeetingId } from '../lib/meetingLink';
import type { VoipMediaType } from '../lib/voip';
import { useChatStore } from '../store/chat';
import { inviteContactsToMeeting } from '../store/meetingInvite';
import { IconSearch, IconUsersPlus } from './icons';
import SmartImg from './SmartImg';

export interface MeetingInvitePanelProps {
  roomName: string;
  title: string;
  mediaType: VoipMediaType;
  /** ★已经在会里的人（按 userId 归一）—— 再邀请一次只会让对方收到一条无意义的响铃。 */
  excludeUserIds: string[];
  onClose: () => void;
}

export default function MeetingInvitePanel({
  roomName,
  title,
  mediaType,
  excludeUserIds,
  onClose,
}: MeetingInvitePanelProps) {
  const contacts = useChatStore((s) => s.contacts);
  const myUserId = useChatStore((s) => s.userId);
  const [keyword, setKeyword] = useState('');
  const [selected, setSelected] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState<string | null>(null);

  const excluded = useMemo(
    () => [myUserId == null ? '' : String(myUserId), ...excludeUserIds.map(String)],
    [myUserId, excludeUserIds],
  );

  const result = useMemo(
    () => pickMyContacts(contacts, { excludeIds: excluded, keyword, limit: PICK_CONTACT_LIMIT }),
    [contacts, excluded, keyword],
  );

  /** ★已选但被关键字筛掉的人仍要能提交：他们不在当前列表里，但用户确实选过。 */
  const selectedRows = useMemo(() => {
    const byId = new Map((contacts ?? []).map((c) => [String(c.userId), c]));
    return selected
      .map((id) => byId.get(id))
      .filter((c): c is NonNullable<typeof c> => !!c)
      .map((c) => ({ userId: String(c.userId), name: contactTitle(c) }));
  }, [contacts, selected]);

  const toggle = (id: string) => {
    setStatus(null);
    setSelected((cur) => (cur.includes(id) ? cur.filter((x) => x !== id) : [...cur, id]));
  };

  const submit = async () => {
    if (busy || selectedRows.length === 0) return;
    setBusy(true);
    setStatus(null);
    try {
      const { ok, failed } = await inviteContactsToMeeting({
        roomName,
        title,
        mediaType,
        contacts: selectedRows,
      });
      setSelected([]);
      setStatus(
        failed.length === 0
          ? `已邀请 ${ok} 人，等待他们加入`
          : ok > 0
            ? `已邀请 ${ok} 人，${failed.length} 人没发出去（${failed.slice(0, 3).join('、')}）`
            : `没发出去：${failed.slice(0, 3).join('、')}`,
      );
    } catch {
      setStatus('邀请没发出去，请稍后重试');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="meet-invite-panel-layer" role="dialog" aria-label="邀请参会人">
      <div className="meet-invite-panel">
        <div className="meet-invite-panel-head">
          <div className="meet-invite-panel-title">
            <IconUsersPlus size={16} />
            邀请参会人
          </div>
          <button type="button" className="meet-invite-panel-x" title="关闭" onClick={onClose}>
            ×
          </button>
        </div>

        <div className="meet-invite-panel-hint">
          从我的联系人中选择，被邀请人会收到和来电一样的入会通知。
        </div>

        {/* ★搜索框与「分享至会话」同款（图标 + 输入 + 清空），见 MeetingSharePanel 的说明。 */}
        <div className="meet-invite-panel-search">
          <IconSearch size={15} className="meet-invite-panel-search-ico" />
          <input
            className="meet-invite-panel-search-input"
            value={keyword}
            placeholder="搜索联系人（备注 / 昵称 / 账号）"
            aria-label="搜索联系人"
            onChange={(e) => setKeyword(e.target.value)}
          />
          {keyword && (
            <button
              type="button"
              className="meet-invite-panel-search-clear"
              title="清空搜索"
              aria-label="清空搜索"
              onClick={() => setKeyword('')}
            >
              ×
            </button>
          )}
        </div>

        <div className="meet-invite-panel-list">
          {result.items.length === 0 && (
            <div className="meet-invite-panel-empty">
              {keyword.trim() ? '没有匹配的联系人' : '还没有可选的联系人（已在会里的人不会出现在这里）'}
            </div>
          )}
          {result.items.map((c) => {
            const id = String(c.userId);
            const on = selected.includes(id);
            const name = contactTitle(c);
            return (
              <button
                key={id}
                type="button"
                className={`meet-invite-row${on ? ' is-on' : ''}`}
                onClick={() => toggle(id)}
                aria-pressed={on}
              >
                <span className="meet-invite-row-check" aria-hidden>
                  {on ? '✓' : ''}
                </span>
                {/* ★联系人真实头像（用户 2026-11-07：「邀请参会人的弹窗也一样」）。 */}
                <span className="meet-invite-row-avatar" style={avatarTone(name)}>
                  {c.avatar ? (
                    <SmartImg
                      src={c.avatar}
                      alt=""
                      style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                      fallback={name.trim().slice(0, 1) || '?'}
                    />
                  ) : (
                    name.trim().slice(0, 1) || '?'
                  )}
                </span>
                <span className="meet-invite-row-name">{name}</span>
              </button>
            );
          })}
          {result.remaining > 0 && (
            <div className="meet-invite-panel-more">{pickHintText(result.remaining)}</div>
          )}
        </div>

        {status && <div className="meet-invite-panel-status">{status}</div>}

        <div className="meet-invite-panel-foot">
          <span className="meet-invite-panel-count">
            {selectedRows.length > 0 ? `已选 ${selectedRows.length} 人` : `会议号 ${formatMeetingId(roomName)}`}
          </span>
          <button type="button" className="meet-invite-panel-btn" onClick={onClose} disabled={busy}>
            取消
          </button>
          <button
            type="button"
            className="meet-invite-panel-btn is-primary"
            disabled={busy || selectedRows.length === 0}
            onClick={() => void submit()}
          >
            {busy ? '发送中…' : '发送邀请'}
          </button>
        </div>
      </div>
    </div>
  );
}
