import { useEffect } from 'react';

/**
 * ★★会中「屏幕常亮」——基于 Screen Wake Lock API。
 *
 * <h2>为什么需要它</h2>
 *
 * <p>手机浏览器在没有任何触摸、也没有正在播放的音视频时，会按系统设定的超时（常见 30s~2min）
 * 自动熄屏。语音会议/群语音通话在"别人说话、我静音听着"的场景下<b>很容易长时间没有任何触摸</b>，
 * 屏幕一黑用户就以为掉线了，得反复点亮确认。视频会议因为摄像头在采集，部分浏览器会顺带保持屏幕，
 * 但这件事<b>不保证</b>，纯语音会议则几乎必熄屏 —— 所以不能依赖浏览器的隐式行为。
 *
 * <h2>为什么用 Wake Lock 而不是「偷偷循环播放一段静音视频」的土办法</h2>
 *
 * <p>后者是 iOS 16.4 之前的老招：靠媒体播放让系统认为页面"正在使用中"。它有两个副作用 ——
 * 会占用一个音频会话（可能影响通话音量/路由）、还要对抗自动播放策略。现在 Safari 16.4+、
 * Chrome Android 84+ 都支持标准 API，走标准路径即可；不支持的浏览器就<b>安静地退化成"会熄屏"</b>，
 * 不要为了少数老设备引入会干扰通话的 hack。
 *
 * <h2>★★两个必须遵守的约束（否则写了也不生效）</h2>
 *
 * <ul>
 *   <li><b>安全上下文</b>：{@code https://} 或 localhost 才有 {@code navigator.wakeLock}。
 *       所以内网 {@code http://192.168.31.101:18080} 上验证不到，属于预期现象（和
 *       {@code getDisplayMedia} 在非安全上下文里不存在是同一类限制）。</li>
 *   <li><b>页面可见时才能持锁</b>：浏览器在页面切到后台/锁屏时会<b>自动</b>释放 sentinel，
 *       并且不会替你重新申请。所以必须监听 {@code visibilitychange}，回到前台再申请一次 ——
 *       这一步漏掉，用户"切出去回个消息再回来"之后就再也不常亮了。</li>
 * </ul>
 */

/** 只声明用到的那一小块，避免为了一个 API 拉全 {@code DOM} 类型。 */
export type ScreenWakeLockSentinel = {
  released: boolean;
  release: () => Promise<void>;
  addEventListener?: (type: 'release', listener: () => void) => void;
};

export type ScreenWakeLockNavigator = {
  wakeLock?: { request: (kind: 'screen') => Promise<ScreenWakeLockSentinel> };
};

/**
 * 当前环境能不能申请屏幕常亮。
 *
 * <p>抽成纯函数是为了可单测：node 环境没有 {@code navigator}，这里不能直接摸全局。
 */
export function wakeLockSupported(nav?: ScreenWakeLockNavigator | null): boolean {
  return typeof nav?.wakeLock?.request === 'function';
}

function currentNavigator(): ScreenWakeLockNavigator | undefined {
  return typeof navigator === 'undefined' ? undefined : (navigator as unknown as ScreenWakeLockNavigator);
}

/**
 * {@code active} 为 true 期间持有屏幕常亮，变回 false / 组件卸载时释放。
 *
 * @param active 是否处于"正在通话/会议中"。不要在来电响铃阶段就持锁 —— 手机可能还在口袋里，
 *               为了一个还没接的通话把屏幕点亮只会徒增耗电。
 */
export function useScreenWakeLock(active: boolean): void {
  useEffect(() => {
    if (!active) return;
    if (typeof document === 'undefined') return;
    const wakeLock = currentNavigator()?.wakeLock;
    if (!wakeLock) return;

    let sentinel: ScreenWakeLockSentinel | null = null;
    let disposed = false;
    let pending = false;

    const drop = () => {
      const held = sentinel;
      sentinel = null;
      if (held && !held.released) void held.release().catch(() => {});
    };

    const acquire = async () => {
      // ★不可见时申请必败（规范要求文档是 active 的），等 visibilitychange 再试，
      //   不要在这里吞掉后就不管了。
      if (disposed || pending || sentinel || document.visibilityState !== 'visible') return;
      pending = true;
      try {
        const held = await wakeLock.request('screen');
        if (disposed) {
          // 申请是异步的：拿到锁时可能已经离会了，必须立刻还回去。
          void held.release().catch(() => {});
          return;
        }
        sentinel = held;
        // 系统可能主动回收（切后台、锁屏、省电模式）；只清本地引用，
        // 回到前台由 visibilitychange 重新申请。
        held.addEventListener?.('release', () => {
          if (sentinel === held) sentinel = null;
        });
      } catch {
        // 省电模式 / 系统策略拒绝 / 老浏览器：静默降级，会议本身不受影响。
      } finally {
        pending = false;
      }
    };

    const onVisibilityChange = () => {
      if (document.visibilityState === 'visible') void acquire();
    };

    void acquire();
    document.addEventListener('visibilitychange', onVisibilityChange);
    return () => {
      disposed = true;
      document.removeEventListener('visibilitychange', onVisibilityChange);
      drop();
    };
  }, [active]);
}
