import { useEffect, useRef, useState } from 'react';
import { App as AntApp, Button, Input, Modal, Spin, Typography } from 'antd';
import { QRCodeCanvas } from 'qrcode.react';
import { copyText } from '../lib/clipboard';
import {
  INVITE_COPIED_TEXT,
  INVITE_COPY_FAILED_TEXT,
  INVITE_QR_DESC,
  INVITE_QR_TITLE,
  INVITE_QR_UNAVAILABLE_TEXT,
  INVITE_URL_UNAVAILABLE_TEXT,
  inviteFileName,
  resolveInviteUrl,
} from '../lib/groupInvite';
import { logoGeometry, qrBrandOverlayDataUrl } from '../lib/qrBrand';
import { useTenantBrand } from '../lib/useTenantBrand';

/** ★二维码画布的像素尺寸：画 640、用 CSS 显示 220（理由见类注释"画布按 640 画"）。 */
const QR_CANVAS_SIZE = 640;
/** ★底板在 640 画布上的边长（122px）——overlay 的合成尺寸与 imageSettings 都按它。 */
const QR_PLATE_SIZE = logoGeometry(QR_CANVAS_SIZE).plateSize;

/**
 * ★★DEV-437：群二维码 + 邀请链接弹窗（入口在群设置面板的「群号」那一行下面）。
 *
 * <h2>★★码里放的是一条约能直接点开的 URL</h2>
 *
 * <p>用户原话：「{@code ${siteUrl}/instant-message?invite=群号}
 * 参考附件截图中的二维码样式，siteLogo 放中间」。
 *
 * <p>★2026-11-05 追加口径：码里还要带 {@code &g=群号&c=会话id}
 * （完整形态 {@code ${siteUrl}/instant-message?invite=群号&g=群号&c=会话id}）。
 * {@code g}/{@code c} 都不在直达参数里，不会触发"一打开就写申请单"。
 *
 * <p>★这修正了 DEV-375 的 {@code group#<群号>#<convId>} 载荷：那是一段只有扫码端
 * 认得的自定义串，普通手机相机扫出来只是一行文本，<b>不会打开申请页</b>。
 * 现在的格式任何人扫都能落到 {@code /instant-message?invite=…}，弹「申请加入」确认框。
 * （{@code buildGroupQrPayload} 的旧定义仍留在 lib 里，见那边的说明。）
 *
 * <p>★★域名用平台配置的 {@code siteUrl}（{@code /api/tenant/config}），<b>不是</b>
 * {@code window.location.origin}：101 页面是 http，origin 拼出来就是 http 链接，
 * 发给别人的应用/浏览器会标不安全甚至直接拦掉；{@code siteUrl} 是 https 权威域名。
 * 拿不到配置才回退当前地址（{@link resolveInviteUrl} / {@link currentInviteUrl}）。
 *
 * <h2>★★加载中不要先渲染 origin 版本</h2>
 *
 * <p>{@link useTenantBrand} 的 {@code undefined} 与 {@code null} 是两件事：
 * 前者 = 还在请求，后者 = 请求失败。★加载中就显示"正在获取"，绝不先出一张
 * 用 http origin 拼的码 —— 那一瞬间点「下载二维码」，存下来的图就指向明文地址，
 * 而用户从图上完全看不出来。
 *
 * <h2>★★logo 走 {@code imageSettings}，不是"事后往画布上补"</h2>
 *
 * <p>要下载（{@code toDataURL}）就得画进 canvas。先把「白色圆角底板 + 圆角 logo」
 * 合成成一张 data URL（{@code lib/qrBrand.ts} 的 {@code qrBrandOverlayDataUrl}），
 * 再交给 {@code QRCodeCanvas} 的 {@code imageSettings}。
 *
 * <p>★★旧做法是父组件 effect 在库画完后往 canvas 上补 logo —— 线上实测会丢：
 * {@code qrcode.react@4.2} 的绘制 effect 没有依赖数组，某些渲染时序下它在我们
 * 补画<b>之后</b>又重画一次，logo 就被擦掉了（用户反馈"第一次打开有 logo，
 * 第二次没有"）。交给库自己画之后，每次重画都会带上它，不存在抢顺序的问题。
 *
 * <p>★图片先以 {@code crossOrigin='anonymous'} 预加载：平台图床带 {@code ACAO: *}，
 * 合成 overlay 时不会污染画布；万一某个环境没有 CORS，合成失败就让码保持无 logo ——
 * 宁可少一个标，也不要一张 {@code toDataURL} 会抛 {@code SecurityError} 的图。
 * ★覆盖中心会吃掉码点，所以有 logo 时纠错级别提到 {@code H}（约 30%，覆盖面积约 3.6%）。
 *
 * <h2>★★三条与"扫得出来"直接相关的取舍（沿用 DEV-375）</h2>
 *
 * <ul>
 *   <li><b>{@code marginSize={4}}</b>：库默认 0（贴边）。多数扫码器要求静默区，
 *       贴边的图在屏幕上能扫，<b>截图/打印后就扫不出来</b>。</li>
 *   <li><b>画布按 640px 画、按 220px 显示</b>：{@code size} 决定像素量，CSS 只决定看起来多大。
 *       按 220 画的话，转发/打印出来就是一张糊图。</li>
 *   <li><b>颜色写死黑白</b>：跟随暗色主题的反色码会让一部分扫码器直接失败，
 *       而失败发生在<b>别人的手机</b>上。</li>
 * </ul>
 *
 * <h2>★复制走 lib/clipboard 而不是 antd 的 copyable</h2>
 *
 * <p>101 是明文 http 域名，{@code navigator.clipboard} 不存在；{@code copyText}
 * 自带 {@code execCommand('copy')} 回落。antd 的 copyable 在这个环境里点了会静默无效。
 */
export default function GroupInviteModal({
  open,
  groupNo,
  convId,
  onClose,
}: {
  open: boolean;
  /** ★群号（字符串，雪花值 —— 见 lib/joinGroup 的 normalizeGroupNo）。null ⇒ 本弹窗不该被打开。 */
  groupNo: string | null;
  /**
   * ★会话 id（新口径里的 {@code &c=}）。
   *
   * <p>★缺失/形状不合法时只是<b>不带</b>这个参数，二维码照常生成 ——
   * 不让一个附加的定位参数把整张码拖成"生成不了"。
   */
  convId?: string | number | null;
  onClose: () => void;
}) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  /**
   * ★★「白底板 + 圆角 logo」的合成图（data URL）；没合成好就是 null。
   *
   * <p>★必须是 state 而不是 ref：它直接作为 {@code imageSettings.src} 参与渲染，
   * 变了就要让 {@code QRCodeCanvas} 重新加载并在下一次重画时带上。
   */
  const [overlaySrc, setOverlaySrc] = useState<string | null>(null);
  const { message: toast } = AntApp.useApp();

  /**
   * ★★三态（见 useTenantBrand）：undefined = 加载中；null = 拿不到（回退 origin）。
   * ★弹窗没开时 enabled=false，不白打一次配置接口。
   */
  const brand = useTenantBrand(open);
  const brandLoading = brand === undefined;
  const url = brandLoading ? null : resolveInviteUrl(groupNo, brand?.siteUrl, convId);
  const logoSrc = brand?.siteLogo ?? null;
  const fileName = inviteFileName(groupNo);

  /**
   * ★预加载 logo，并合成为 overlay data URL（只有 {@code logoSrc} 变时才重来）。
   *
   * <p>★必须带 {@code crossOrigin='anonymous'}：不带的话跨域图会把离屏 canvas
   * 标记为 tainted，合成时 {@code toDataURL} 抛 SecurityError。
   * ★加载/合成失败 ⇒ {@code overlaySrc} 保持 null：二维码照常可扫、可下载，
   * 只是没有中间那个标（宁可少一个标，也不要一张不能下载的图）。
   */
  useEffect(() => {
    setOverlaySrc(null);
    if (!logoSrc) return undefined;
    let alive = true;
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      if (!alive) return;
      // ★底板尺寸直接用二维码画布的几何（640px 画布 → 122px 底板），
      //   overlay 源图按 3 倍画，缩到 122px 才不糊。
      setOverlaySrc(qrBrandOverlayDataUrl(img, QR_PLATE_SIZE));
    };
    img.onerror = () => undefined;
    img.src = logoSrc;
    return () => {
      alive = false;
    };
  }, [logoSrc]);

  const onCopy = async () => {
    if (!url) return;
    const ok = await copyText(url);
    // ★按返回值提示（不是"点了就说成功"）：失败时用户粘出旧内容会以为点错了。
    if (ok) toast.success(INVITE_COPIED_TEXT);
    else toast.error(INVITE_COPY_FAILED_TEXT);
  };

  /**
   * ★下载二维码：直接取画布的 {@code toDataURL}（同步、离屏、不依赖网络），
   * 走临时 {@code <a download>} 落盘（与附件下载同一套做法，不预开新窗口）。
   */
  const onDownload = () => {
    const canvas = canvasRef.current;
    if (!canvas) {
      // ★不静默：点一下没反应会被当成按钮坏了。
      toast.error('二维码还没准备好，请稍后再试');
      return;
    }
    const a = document.createElement('a');
    a.href = canvas.toDataURL('image/png');
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  return (
    <Modal
      title={INVITE_QR_TITLE}
      open={open}
      onCancel={onClose}
      footer={(
        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
          <Button onClick={onClose}>关闭</Button>
          <Button disabled={!url} onClick={() => onCopy().catch(() => undefined)}>
            复制链接
          </Button>
          <Button type="primary" disabled={!url} onClick={onDownload}>
            下载二维码
          </Button>
        </div>
      )}
      width={360}
    >
      {/* ---- 二维码（URL）：★闸门只看 url ---- */}
      {brandLoading ? (
        <div style={{ display: 'flex', justifyContent: 'center', padding: '28px 0' }}>
          <Spin />
        </div>
      ) : url ? (
        <>
          <div style={{ display: 'flex', justifyContent: 'center', padding: '4px 0 12px' }}>
            <QRCodeCanvas
              ref={canvasRef}
              // ★★码里放的是 ${siteUrl}/instant-message?invite=<群号>（可直接点开）。
              value={url}
              size={QR_CANVAS_SIZE}
              // ★显示小、像素大（理由见类注释第 3 条）。
              style={{ width: 220, height: 220 }}
              // ★有 logo 时用 H（中心被盖掉约 3.6%），没有则沿用 M。
              level={overlaySrc ? 'H' : 'M'}
              // ★静默区：不写默认 0（贴边），打印/截图后扫不出来。
              marginSize={4}
              /**
               * ★★白底板 + 圆角 logo 交给库自己画（理由见类注释）。
               * ★宽高就是底板在 640 画布上的像素边长；不开 excavate ——
               *   底板圆角外是透明的，底层码点会自然透出来。
               */
              imageSettings={overlaySrc ? {
                src: overlaySrc,
                width: QR_PLATE_SIZE,
                height: QR_PLATE_SIZE,
                // ★不开 excavation：底板圆角外是透明的，底层码点自然透出。
                excavate: false,
              } : undefined}
              // ★写死的黑白（理由见类注释"颜色不跟随主题"）。
              bgColor="#FFFFFF"
              fgColor="#000000"
              title={INVITE_QR_TITLE}
            />
          </div>
          <Typography.Paragraph type="secondary" style={{ fontSize: 12 }}>
            {INVITE_QR_DESC}
          </Typography.Paragraph>
        </>
      ) : (
        // ★★"生成不了"必须说出来：默默显示空框会让用户以为加载慢。
        <Typography.Paragraph type="secondary" style={{ fontSize: 12 }}>
          {INVITE_QR_UNAVAILABLE_TEXT}
        </Typography.Paragraph>
      )}

      {/* ---- 链接（URL）：与二维码同一份内容，闸门也同一条 ---- */}
      {url ? (
        <Input value={url} readOnly onFocus={(e) => e.target.select()} />
      ) : brandLoading ? null : (
        <Typography.Paragraph type="secondary" style={{ fontSize: 12 }}>
          {INVITE_URL_UNAVAILABLE_TEXT}
        </Typography.Paragraph>
      )}
    </Modal>
  );
}
