/**
 * ★★会议回放页 —— 一条 {@code ?replay=<token>} 链接打开，<b>要求登录</b>后观看。
 *
 * <h2>它解决什么</h2>
 *
 * <p>会议结束后，录制文件与转写时间轴都还在库里，但原来的入口
 * （{@code /meetings/{id}} 与 {@code /files/{id}/url}）都强制<b>参会人</b>身份 ——
 * 想把开会记录发给参会的同事，不用他自己去翻会议列表。
 *
 * <h2>★★四条纪律（2026-11-09 调整）</h2>
 *
 * <ul>
 *   <li><b>必须登录</b>：{@code App.tsx} 只在拿到 {@code userId} 之后才渲染本页；
 *       未登录会被送去平台登录页，并带 {@code ?replay=} 回来。服务端白名单也已收紧，
 *       绕过前端直接打接口同样是 401。</li>
 *   <li><b>不挂 IM 主体</b>：本页不挂 {@code ChatPage} / call store —— 它只需要
 *       "我登录了"这一个事实，不需要会话列表、长连接与通话浮层。</li>
 *   <li><b>接口仍 {@code silentAuthFailure}</b>：页面打开后登录态过期时，这里自己给
 *       「去登录」按钮，而不是让全局的自动跳转把 {@code ?replay=} 冲掉。</li>
 *   <li><b>可以下载</b>：能看就能带走（服务端同一个令牌端点，
 *       {@code download=1} 改签 attachment）。</li>
 * </ul>
 *
 * <h2>★失效与过期的文案合并</h2>
 *
 * <p>服务端对"令牌不存在 / 已撤销 / 已过期 / 不是回放"一律回
 * {@code MEETING_NOT_FOUND}（{@code IM_50001}），<b>刻意不区分</b>——
 * 区分开等于告诉探测者"这个令牌存在但过期了"。所以这里也只说一句话：
 * 「回放链接无效或已过期」。
 */
import { useCallback, useEffect, useMemo, useState } from 'react';

import { meetingPublicReplayApi } from '../api';
import { ApiError } from '../api/client';
import type { MeetingPublicReplayView } from '../api/types';
import { PLATFORM_LOGIN_URL, isPlatformMode } from '../authMode';
import MeetingReplayView from '../components/MeetingReplayView';
import { buildLoginUrl } from '../lib/meetingLink';
import { durationText, meetingTimeText } from '../lib/meetingRecord';
import type { ReplayFile, ReplayTranscript } from '../lib/meetingReplay';

interface Props {
  /** 回放令牌（{@code lib/meetingLink.ts:readReplayToken} 已校验过形态）。 */
  token: string;
}

/**
 * {@code loading} 读元信息中 / {@code ready} 可播 / {@code invalid} 链接无效或过期 /
 * {@code denied} 链接有效但不在分享范围内 / {@code auth} 登录态失效 /
 * {@code failed} 网络或服务异常。
 */
type Phase = 'loading' | 'ready' | 'invalid' | 'denied' | 'auth' | 'failed';

/**
 * ★这个错误码表示"链接不能用了"。
 *
 * <p>{@code IM_50001} 是服务端统一复用的 {@code MEETING_NOT_FOUND}；
 * {@code PARAM_ERROR} 只在令牌形态不对时出现（正常情况下前端已拦掉）。
 * 网络类错误（{@code NETWORK}）<b>不算</b>——那是"现在打不开"，重新加载可能就好了。
 */
function isInvalidLink(e: unknown): boolean {
  return e instanceof ApiError && (e.code === 'IM_50001' || e.code === 'PARAM_ERROR');
}

/**
 * ★链接<b>有效</b>，但持链接的人不在主持人设定的分享范围内。
 *
 * <p>服务端用 {@code NO_PERMISSION}（{@code IM_30001}）与"链接不存在"区分开 ——
 * 持链接者已经知道这条链接存在，把两者合并成"链接无效"会让他一直去要新链接。
 */
function isDenied(e: unknown): boolean {
  return e instanceof ApiError && e.code === 'IM_30001';
}

/** ★4010 / 裸 401：页面打开之后登录态过期了。★与"链接失效"是两件事，不能合并文案。 */
function isAuthFailure(e: unknown): boolean {
  return (
    e instanceof ApiError &&
    (e.code === 'IM_10401' || e.code === 'IM_10402' || e.httpStatus === 401)
  );
}

export default function ReplayPage({ token }: Props) {
  const [phase, setPhase] = useState<Phase>('loading');
  const [data, setData] = useState<MeetingPublicReplayView | null>(null);
  const [error, setError] = useState<string | null>(null);
  /** 重试计数：让"再请求一次"成为一次显式的 effect 重跑。 */
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setPhase('loading');
    setError(null);
    meetingPublicReplayApi
      .get(token)
      .then((view) => {
        if (cancelled) return;
        setData(view);
        setPhase('ready');
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        if (isAuthFailure(e)) {
          setPhase('auth');
          return;
        }
        if (isDenied(e)) {
          setPhase('denied');
          return;
        }
        if (isInvalidLink(e)) {
          setPhase('invalid');
          return;
        }
        setPhase('failed');
        setError(e instanceof Error ? e.message : '暂时无法打开这段回放');
      });
    return () => {
      cancelled = true;
    };
  }, [token, attempt]);

  // ★转成播放器认识的结构（公开接口与详情页的字段名刻意保持一致，这里只是挑字段）。
  const files = useMemo<ReplayFile[]>(
    () => (data?.files ?? []).map((f) => ({
      id: String(f.id),
      filename: f.filename ?? null,
      contentType: f.contentType ?? null,
      durationSec: f.durationSec ?? null,
      sizeBytes: f.sizeBytes ?? null,
      // ★公开接口只下发可用文件；显式写 2，让播放器按"可播"判定而不是"未知"。
      status: 2,
    })),
    [data],
  );

  const transcripts = useMemo<ReplayTranscript[]>(
    () => (data?.transcripts ?? []).map((t) => ({
      sourceFileId: t.sourceFileId ?? null,
      segments: t.segments ?? [],
      speakerNames: t.speakerNames ?? null,
    })),
    [data],
  );

  const resolveUrl = useCallback(
    async (fileId: string) => {
      const view = await meetingPublicReplayApi.fileUrl(token, fileId);
      return view.playUrl ?? '';
    },
    [token],
  );

  /** ★下载：同一个令牌端点，{@code download=1} 改签 attachment。 */
  const resolveDownloadUrl = useCallback(
    async (fileId: string) => {
      const view = await meetingPublicReplayApi.downloadUrl(token, fileId);
      return { url: view.downloadUrl ?? '', filename: null };
    },
    [token],
  );

  /**
   * ★登录态失效后去登录，并把 {@code ?replay=} 原样带上。
   *
   * <p>★不能用 App 的全局自动跳转：那里只跳平台站根（不带 {@code redirect}），
   * 用户登完回来会落在 IM 首页，回放链接就丢了。
   */
  const goLogin = useCallback(() => {
    if (!isPlatformMode) {
      window.location.reload();
      return;
    }
    const target = `${window.location.pathname}${window.location.search}${window.location.hash}`;
    window.location.replace(buildLoginUrl(PLATFORM_LOGIN_URL, window.location.origin, target));
  }, []);

  const meta = useMemo(() => {
    if (!data) return '';
    const parts: string[] = [];
    const kind = (data.originText ?? '').trim();
    if (kind) parts.push(kind);
    const started = meetingTimeText(data.startedAt);
    if (started) parts.push(started);
    const dur = durationText(data.durationSec);
    if (dur) parts.push(dur);
    return parts.join(' · ');
  }, [data]);

  return (
    <div className="gm-page rp-page">
      <header className="gm-head">
        <div className="gm-brand">
          <span className="gm-brand-dot" />
          <span>女娲会议</span>
        </div>
        <div className="gm-room">回放</div>
      </header>

      {phase !== 'ready' && (
        <main className="gm-main">
          <section className="gm-card">
            {phase === 'loading' && (
              <>
                <div className="gm-spinner" />
                <h1>正在打开回放…</h1>
                <p className="gm-hint">链接有效时即可观看。</p>
              </>
            )}
            {phase === 'auth' && (
              <>
                <div className="gm-badge gm-badge-muted">需要登录</div>
                <h1>登录状态已失效</h1>
                <p className="gm-hint">
                  回放链接需要登录后观看。重新登录会自动回到这条链接。
                </p>
                <button type="button" className="gm-primary" onClick={goLogin}>
                  去登录
                </button>
              </>
            )}
            {phase === 'invalid' && (
              <>
                <div className="gm-badge gm-badge-muted">无法播放</div>
                <h1>回放链接无效或已过期</h1>
                <p className="gm-hint">
                  这条链接可能已经被撤销、超过了有效期，或者复制时少了几个字符。
                  请联系分享给你的人重新生成一条。
                </p>
              </>
            )}
            {phase === 'denied' && (
              <>
                <div className="gm-badge gm-badge-muted">暂不可见</div>
                <h1>主持人未向你分享本场回放</h1>
                <p className="gm-hint">
                  这条链接本身有效，但可见范围由主持人设定。需要观看的话，
                  请联系主持人把你加入分享范围。
                </p>
              </>
            )}
            {phase === 'failed' && (
              <>
                <div className="gm-badge gm-badge-muted">加载失败</div>
                <h1>暂时打不开这段回放</h1>
                <p className="gm-hint">{error || '网络或服务暂时不可用，请稍后再试。'}</p>
                <button
                  type="button"
                  className="gm-primary"
                  onClick={() => {
                    setAttempt((n) => n + 1);
                  }}
                >
                  重试
                </button>
              </>
            )}
          </section>
        </main>
      )}

      {phase === 'ready' && data && (
        <main className="rp-main">
          <section className="rp-shell">
            <div className="rp-head">
              <h1 className="rp-title">{(data.title ?? '').trim() || '会议回放'}</h1>
              {meta && <p className="rp-meta">{meta}</p>}
            </div>
            <MeetingReplayView
              files={files}
              transcripts={transcripts}
              resolveUrl={resolveUrl}
              resolveDownloadUrl={resolveDownloadUrl}
              emptyText="这场会议没有可回放的录制"
            />
          </section>
        </main>
      )}
    </div>
  );
}
