import { useEffect, useState } from 'react';
import { App as AntApp, Button, Empty, Popconfirm, Spin, Tooltip, Typography } from 'antd';
import { UNKNOWN_NAME, firstNameOf } from '../lib/displayName';
import { MESSAGE_PIN_MAX } from '../lib/pin';
import type { Id, MessagePinDto } from '../api/types';
import { useChatStore } from '../store/chat';
import { IconPin } from './icons';
import PanelCloseButton from './PanelCloseButton';

/** ★ID 比较统一 String 归一（雪花 ID > 2^53，见 api/json.ts）。 */
const sameId = (a: unknown, b: unknown): boolean => a != null && b != null && String(a) === String(b);

/** 两位补零。 */
const pad2 = (n: number): string => String(n).padStart(2, '0');

/**
 * 置顶时间：今天「HH:mm」、昨天「昨天 HH:mm」、今年「M月D日 HH:mm」、更早「YYYY年M月D日」。
 *
 * <p>★口径与聊天里那条时间分割线（{@code lib/timeDivider}）<b>刻意不同</b>：
 * 那边是"接着上一段对话"，读者知道大概是什么时候；这里是<b>一串彼此无关的消息</b>
 * （可能是三个月前置顶的），只给 {@code 14:32} 完全无法定位。
 * 所以这里必须带日期 —— 与文件面板同一个理由。
 *
 * <p>★{@code pinTime} 是 <b>epoch 毫秒</b>（后端 int64），不是 ISO 字符串：
 * 直接 {@code new Date(<string>)} 在 Safari 上会得到 Invalid Date（它对非 ISO 格式极严）。
 */
function pinTimeText(ms?: number): string {
  if (!ms) return '';
  const d = new Date(ms);
  if (Number.isNaN(d.getTime())) return '';
  const hm = `${pad2(d.getHours())}:${pad2(d.getMinutes())}`;
  const today = new Date();
  if (d.toDateString() === today.toDateString()) return `今天 ${hm}`;
  if (d.toDateString() === new Date(today.getTime() - 86_400_000).toDateString()) return `昨天 ${hm}`;
  if (d.getFullYear() === today.getFullYear()) return `${d.getMonth() + 1}月${d.getDate()}日 ${hm}`;
  return `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;
}

/** 消息类型的短标签（列表里一行文字读不出是图还是文件时，这个标签就是全部信息）。 */
const TYPE_LABEL: Record<string, string> = {
  image: '[图片]',
  file: '[文件]',
  audio: '[语音]',
  video: '[视频]',
  card: '[卡片]',
  meeting: '[会议]',
  system: '[系统消息]',
};

/**
 * 一条置顶项显示什么。
 *
 * <p>★优先级：{@code digest} → 类型标签 → 「（无内容）」。
 * 后端在置顶那一刻把 {@code digest} 抄了一份<b>快照</b>，绝大多数情况它就有内容；
 * 但 {@code digest} 是<b>可空</b>的（老数据、或 body 被清理过），
 * 这时光显示一个空行会让用户以为面板坏了。
 */
function pinText(p: MessagePinDto): string {
  const d = (p.digest ?? '').trim();
  if (d) return d;
  return TYPE_LABEL[String(p.msgType ?? '')] ?? '（无内容）';
}

/**
 * 会话窗口顶部「Pin（置顶消息）」标签页（DEV-195）。
 *
 * <h2>能力边界（后端 DEV-195 已全部就绪，这里没有占位）</h2>
 *
 * <p>读 {@code GET /conversations/{convId}/pins}、置顶/取消置顶走同一组端点，
 * 上限 {@link MESSAGE_PIN_MAX} 条。列表由服务端按 {@code pinTime} 倒序返回，本组件<b>不重排</b>。
 *
 * <h2>★三条必须由界面体现的服务端语义（写错了界面会骗人）</h2>
 *
 * <ul>
 *   <li><b>{@code digest} / {@code senderName} / {@code sendTime} 都是"置顶那一刻的快照"。</b>
 *       消息后来被编辑了，这里显示的还是旧文本 —— 这是<b>设计如此</b>（与移动端一致），
 *       不是 bug。★所以「定位原文」跳过去看到的内容可能与这里不一样，
 *       那是权威数据，不要试图把两边改成一致（那需要在读路径上再回源每条消息，
 *       而 {@code listPins} 恰恰是为"便宜"设计的）。</li>
 *   <li><b>任何人都能取消任何一条</b>（飞书形态，服务端不校验 {@code pinBy}）。
 *       ⇒ 取消按钮<b>不</b>按 {@code pinBy} 做可见性判断 —— 藏起来反而制造
 *       "置顶了却取消不掉"的死角（置顶的人退群了怎么办）。</li>
 *   <li><b>列表里不会出现已撤回的置顶项</b>（服务端读路径批量复核并过滤）。
 *       ⇒ {@code list.length} 可能小于服务端实际置顶数，所以<b>不拿它</b>显示
 *       "还能置几条"，文案只说"已置顶 N 条（上限 100）"。</li>
 * </ul>
 *
 * <h2>★「定位原文」为什么既切页又拉历史</h2>
 *
 * <p>切页交给 {@code onGoMessages}（本组件无权切标签页）；拉历史交给
 * {@code focusPinnedMessage}（它负责把这条消息弄进内存，否则目标节点根本不在 DOM 里）。
 * 两件事都做完，ChatWindow 才会真正滚过去 —— 缺任何一个的表现都是"点了没反应"。
 */
export default function ChatPinPanel({
  convId,
  onGoMessages,
  onClose,
}: {
  convId: Id | null;
  onGoMessages: () => void;
  /** ★DEV-253：关掉这条侧栏（面板不知道"关掉我"是什么意思，见 PanelCloseButton）。 */
  onClose?: () => void;
}) {
  const pins = useChatStore((s) => (convId != null ? s.pinsByConv[String(convId)] : undefined));
  const loadPins = useChatStore((s) => s.loadPins);
  const unpinMessage = useChatStore((s) => s.unpinMessage);
  const focusPinnedMessage = useChatStore((s) => s.focusPinnedMessage);
  const { message: toast } = AntApp.useApp();

  /**
   * ★本组件自己发的那次请求的加载态。
   *
   * <p>{@code pins === undefined} 只回答"store 里有没有"，回答不了"我正在拉" ——
   * 进会话时 {@code selectConv} 也会顺手拉一次，那时本组件的 effect 也在拉，
   * 于是只判 {@code undefined} 的话两件事会撞在一起：先显示"还没有置顶消息"，
   * 拉到之后再弹出一列。所以面板自己维护一个 loading，期间显示 {@code Spin}。
   */
  const [loading, setLoading] = useState(false);
  /** 正在取消的那条（按 msgId）。用来只给那一行转圈，而不是整面板。 */
  const [unpinning, setUnpinning] = useState<string | null>(null);
  /** 正在定位的那条（按 msgId）。定位要发请求（可能拉一次历史），不发反馈会像卡住。 */
  const [jumping, setJumping] = useState<string | null>(null);

  // ★切会话 ⇒ 重新拉一次。★这里【不】用 `pins === undefined` 当闸门：
  //   置顶是多人共享、且没有下行帧通知的状态，本端可能对着一个过期列表
  //   （别人刚取消了，我这里还挂着）。每次打开面板重拉一次是最便宜的正确做法
  //   （返回体 ≤100 条），也是唯一能自我纠正的机会。
  //   ★依赖是 convId：切会话重拉，同一会话内不重复拉（重渲染不触发）。
  useEffect(() => {
    if (convId == null) return undefined;
    let alive = true;
    setLoading(true);
    loadPins(convId)
      .catch((e: unknown) => {
        // ★失败要说话：静默的话面板会显示"还没有置顶消息"，而事实是"没拉到"——
        //   用户会去别的端确认，然后以为这条置顶丢了。
        if (alive) toast.error(`Pin 列表加载失败：${(e as Error).message}`);
      })
      .finally(() => {
        // ★alive 闸门：切会话时旧请求的 finally 会晚于新请求的 setLoading(true) 到达，
        //   不挡的话新会话的转圈会被旧请求的"结束"提前关掉（经典的竞态闪烁）。
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [convId, loadPins, toast]);

  const doUnpin = async (p: MessagePinDto) => {
    setUnpinning(String(p.msgId));
    try {
      await unpinMessage(convId as Id, p.msgId);
      toast.success('已取消 Pin');
    } catch (e) {
      // ★原样展示服务端文案（可能是网络错、也可能是权限）。幂等接口，
      //   重复点不会报错，所以这里不需要"是不是已经取消了"的分支。
      toast.error(`取消 Pin 失败：${(e as Error).message}`);
    } finally {
      setUnpinning(null);
    }
  };

  const doJump = async (p: MessagePinDto) => {
    if (convId == null) return;
    setJumping(String(p.msgId));
    try {
      // ★先拉/确认消息在内存里，再切页。反过来的话切到消息页的那一帧
      //   ChatWindow 找不到目标节点，滚动就丢了（focusRequest 已被消费掉）。
      await focusPinnedMessage(convId, p.msgId, p.seq ?? 0);
      onGoMessages();
    } catch (e) {
      toast.error(`定位原文失败：${(e as Error).message}`);
    } finally {
      setJumping(null);
    }
  };

  const list = pins ?? [];
  const overLimit = list.length >= MESSAGE_PIN_MAX;

  return (
    <div className="chat-panel">
      <div className="chat-panel-head">
        <span className="chat-panel-title">
          Pin{list.length > 0 ? ` · ${list.length} 条` : ''}
          {/* ★上限写在头上（常驻），而不是只在达到上限时才冒出来 —— 后者会让用户
              以为"这个提示是报错"。见类注释：不显示"还能置几条"的推算值。 */}
          <Typography.Text type="secondary" style={{ fontSize: 12, fontWeight: 400, marginLeft: 8 }}>
            上限 {MESSAGE_PIN_MAX} 条
          </Typography.Text>
        </span>
        {/* ★DEV-253：右缘那一组（这里只有关闭）。 */}
        <div className="chat-panel-head-end">{onClose && <PanelCloseButton onClose={onClose} panel="Pin" />}</div>
      </div>

      <div className="chat-panel-scroll">
        {loading && list.length === 0 ? (
          // ★只在"还没有任何内容可显示"时占屏。已经有列表时刷新不该把它换成转圈 ——
          //   那是 DEV-168/172/191 一路在消灭的"闪"。
          <div style={{ textAlign: 'center', marginTop: 64 }}>
            <Spin />
          </div>
        ) : list.length === 0 ? (
          <Empty
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            style={{ marginTop: 64 }}
            description="还没有 Pin 的消息（在任意消息上点右键可以 Pin）"
          />
        ) : (
          <>
            {/* ★达到上限时给一句解释。★必须说清"不会自动挤掉最旧的"——
                否则用户会以为再置一条会把最老的顶掉，点下去却拿到一个报错，
                而那个报错看起来像"系统坏了"。 */}
            {overLimit && (
              <div className="chat-panel-hint">
                已 Pin {MESSAGE_PIN_MAX} 条（上限）。取消一条才能再 Pin —— 服务端不会自动挤掉最旧的一条。
              </div>
            )}
            <ul className="pin-list">
              {list.map((p) => (
                <li className="pin-item" key={String(p.msgId)}>
                  <button
                    type="button"
                    className="pin-item-main"
                    // ★整块可点 = 定位原文；取消置顶是里面一个独立的按钮，
                    //   所以这里用 <button> 而不是给 div 挂 onClick（键盘可达）。
                    onClick={() => doJump(p).catch(() => undefined)}
                    disabled={jumping != null}
                  >
                    <span className="pin-item-text">{pinText(p)}</span>
                    <span className="pin-item-meta">
                      {/* ★DEV-202 #218：兜底由 `用户{senderId}` 改成「未知用户」（id 不上界面）。
                          ★分隔符随之**不再有条件**：名字现在恒非空（最差是「未知用户」），
                            留着 `p.senderName ? ' · ' : ''` 会输出「未知用户9月1日」这种粘连。 */}
                      {firstNameOf(UNKNOWN_NAME, p.senderName)}
                      {' · '}
                      {pinTimeText(p.pinTime)}
                      {p.pinBy != null && !sameId(p.pinBy, p.senderId) ? ' · 他人 Pin' : ''}
                    </span>
                  </button>
                  <Popconfirm
                    title="取消这条 Pin？"
                    // ★任何人都能取消任何一条（服务端语义，见类注释）——
                    //   所以按钮文案里【不】出现"你置顶的"这类限定。
                    okText="取消 Pin"
                    cancelText="算了"
                    // ★★必须指定 placement。antd 的 Popconfirm 默认朝上（top），
                    //   而这个按钮外面套着一个朝上的 Tooltip（「取消置顶」）——
                    //   两个弹层落在同一块位置，确认按钮会被 tooltip 盖住，
                    //   ★用户 hover 之后点下去点不到（Playwright 报的是
                    //   "tooltip intercepts pointer events"）。朝右下弹开就避开了。
                    placement="bottomRight"
                    onConfirm={() => doUnpin(p).catch(() => undefined)}
                  >
                    <Tooltip title="取消 Pin">
                      <Button
                        type="text"
                        size="small"
                        className="pin-item-unpin"
                        loading={unpinning === String(p.msgId)}
                        icon={<IconPin size={14} />}
                      />
                    </Tooltip>
                  </Popconfirm>
                </li>
              ))}
            </ul>
          </>
        )}
      </div>
    </div>
  );
}
