/**
 * 资料库文档卡片的**数据层**（零 React、零 DOM —— 全部可在 node 里跑单测）。
 *
 * <h2>它做什么</h2>
 * <ol>
 *   <li>把消息正文里的 {@code /repo/doc/{slug}} 交给 {@link scanRepoDocLinks} 识别；</li>
 *   <li>调 {@code GET /api/repo/s/{slug}} 取文档元数据（标题 / 创建者 / 我的权限）；</li>
 *   <li>可导出时调 {@code GET /api/repo/pages/{id}/export/markdown}；
 *       不可导出但可查看时调 {@code GET /api/repo/pages/{id}/preview/markdown}，
 *       把 Markdown 压成一段纯文本，作为卡片的正文预览。</li>
 * </ol>
 *
 * <h2>★★为什么预览走导出/摘要接口，而不是 /content</h2>
 * <p>资料库前端打开文档时正文由协作编辑器加载，{@code /api/repo/pages/{id}/content}
 * 这类路径在服务端**不存在**（实测 404）；而 repo 自己的导出逻辑用的就是
 * {@code /pages/{id}/export/markdown}，返回 {@code { markdown, title }}。
 * 复用这条接口，得到的正文与服务端导出的口径完全一致，不必猜协作编辑器的内部协议。
 *
 * <p>★接收方常常只有「可查看 / 可评论」而没有导出位。早期这里直接不发请求，
 * 卡片就只剩「打开文档查看全文」。现在改用只要求 viewable 的
 * {@code /pages/{id}/preview/markdown}（服务端只回截断后的摘要），
 * 并在导出失败时自动兜底到这条接口。
 *
 * <h2>★★缓存与并发</h2>
 * <p>消息列表会频繁重渲染（新消息、输入框每次按键都会走过 store），而一条消息
 * 可能被反复挂载/卸载。这里用**模块级缓存 + in-flight 合并**：
 * 同一个 slug 在同一时刻只发一个请求，成功/失败都缓存，滚动回来看不会重新打接口。
 * 失败也缓存是有意的 —— 文档被删/无权限不是"稍后自动会好"的状态，
 * 反复重试只会把控制台刷满。
 *
 * <p>★鉴权：IM 与资料库同域，用**当前登录态 cookie**。{@code credentials:'include'}
 * 与 repo 前端自身那套 fetch 逐字一致；写成 {@code 'omit'} 会拿到 200 的未登录 JSON
 * （不是 401），症状是"接口都成功、卡片全没有"。
 */

/** 平台 {@code ReqResult} 信封的成功码（全站统一）。 */
const OK_CODE = '0000'

/** `/api/repo/s/{slug}` 里我们关心的权限字段。 */
export interface RepoDocAccess {
  viewable?: boolean
  editable?: boolean
  exportable?: boolean
  copyable?: boolean
  shareable?: boolean
  deletable?: boolean
  manageable?: boolean
  commentable?: boolean
  via?: string
  permBits?: number
}

/** 卡片渲染需要的文档元数据（其余字段一律忽略，别把整个信封塞进组件）。 */
export interface RepoDocMeta {
  id: number
  slugId: string
  spaceId: number | null
  title: string
  pageType: string
  sourceExt: string
  creatorId: number | null
  creatorName: string
  creatorAvatar: string
  editedAt: string
  myAccess: RepoDocAccess | null
}

/** 正文预览最多取多少字符 / 多少行（参考图里卡片正文区大约 5~6 行）。 */
export const REPO_DOC_PREVIEW_MAX_CHARS = 260
export const REPO_DOC_PREVIEW_MAX_LINES = 6

/** 卡片头部图标的类型（按 pageType / 原始扩展名判定）。 */
export type RepoDocIconKind = 'doc' | 'slides' | 'sheet' | 'datatable' | 'pdf' | 'folder'

/**
 * 文档类型 → 卡片图标。
 *
 * <p>★判定顺序不能反：{@code pageType} 先看（sheet/datatable/folder 是独立页面类型），
 * 再看 {@code sourceExt} 区分幻灯片 / PDF。**导入的 pptx 页 pageType 仍是 doc**，
 * 只能靠 {@code sourceExt:"pptx"} 认出来 —— 这是最容易漏的一条。
 */
export function repoDocIconKind(
  pageType?: string | null,
  sourceExt?: string | null,
): RepoDocIconKind {
  const type = (pageType ?? '').trim().toLowerCase()
  const ext = (sourceExt ?? '').trim().toLowerCase().replace(/^\./, '')
  if (type === 'folder') return 'folder'
  if (type === 'datatable') return 'datatable'
  if (type === 'sheet' || type === 'slides' || type === 'ppt') {
    return type === 'sheet' ? 'sheet' : 'slides'
  }
  if (ext === 'xlsx' || ext === 'xls' || ext === 'csv' || ext === 'tsv') return 'sheet'
  if (ext === 'pptx' || ext === 'ppt' || ext === 'key' || ext === 'odp') return 'slides'
  if (ext === 'pdf') return 'pdf'
  return 'doc'
}

/** 两份元数据是否展示为同一张卡片（静默刷新时避免无意义的重渲染）。 */
export function sameRepoDocMeta(a: RepoDocMeta | null, b: RepoDocMeta | null): boolean {
  if (a === b) return true
  if (!a || !b) return false
  return (
    a.id === b.id &&
    a.slugId === b.slugId &&
    a.title === b.title &&
    a.pageType === b.pageType &&
    a.sourceExt === b.sourceExt &&
    a.creatorName === b.creatorName &&
    a.creatorAvatar === b.creatorAvatar &&
    repoDocPermissionLabel(a.myAccess) === repoDocPermissionLabel(b.myAccess) &&
    a.myAccess?.exportable === b.myAccess?.exportable
  )
}

/**
 * 卡片底部那句权限文案。
 *
 * <p>★优先级从高到低：能管 > 能编辑 > 能评论 > 能看。它与权限位是**投影关系**，
 * 不是"最宽松的一个" —— 一个可管理的人当然也可查看，但卡片应该告诉他"你能管理"。
 */
export function repoDocPermissionLabel(access?: RepoDocAccess | null): string {
  if (access?.manageable) return '可管理'
  if (access?.editable) return '可编辑'
  if (access?.commentable) return '可评论'
  return '可查看'
}

/** 文档链接的站内路径（复制按钮与卡片 href 共用）。 */
export function repoDocPath(slug: string): string {
  return `/repo/doc/${encodeURIComponent(slug)}`
}

function asNumber(v: unknown): number | null {
  if (v == null) return null
  const n = Number(v)
  return Number.isFinite(n) ? n : null
}

function asString(v: unknown): string {
  return typeof v === 'string' ? v : ''
}

function parseAccess(v: unknown): RepoDocAccess | null {
  if (!v || typeof v !== 'object') return null
  const a = v as Record<string, unknown>
  const out: RepoDocAccess = {}
  for (const key of [
    'viewable', 'editable', 'exportable', 'copyable',
    'shareable', 'deletable', 'manageable', 'commentable',
  ] as const) {
    if (typeof a[key] === 'boolean') out[key] = a[key] as boolean
  }
  if (typeof a.via === 'string') out.via = a.via
  const bits = asNumber(a.permBits)
  if (bits != null) out.permBits = bits
  return out
}

/** 把服务端 data 归一成卡片用的元数据；缺 id 的响应视为无效。 */
function normalizeMeta(data: unknown, fallbackSlug: string): RepoDocMeta | null {
  if (!data || typeof data !== 'object') return null
  const d = data as Record<string, unknown>
  const id = asNumber(d.id)
  if (id == null) return null
  const slugId = asString(d.slugId) || fallbackSlug
  return {
    id,
    slugId,
    spaceId: asNumber(d.spaceId),
    title: asString(d.title),
    pageType: asString(d.pageType),
    sourceExt: asString(d.sourceExt),
    creatorId: asNumber(d.creatorId),
    creatorName: asString(d.creatorName),
    creatorAvatar: asString(d.creatorAvatar),
    editedAt: asString(d.editedAt),
    myAccess: parseAccess(d.myAccess),
  }
}

const metaCache = new Map<string, RepoDocMeta | null>()
const metaInflight = new Map<string, Promise<RepoDocMeta | null>>()
const previewCache = new Map<number, string | null>()
const previewInflight = new Map<number, Promise<string | null>>()
const metaSavedAt = new Map<string, number>()
const previewSavedAt = new Map<number, number>()

/** localStorage 键与上限：只缓存"已经渲染过"的卡片，首次出现仍走接口。 */
export const REPO_DOC_CACHE_STORAGE_KEY = 'nuwax-im.repo-doc-card.v1'
const REPO_DOC_CACHE_LIMIT = 120
/** 超过这个时间的缓存先展示、再静默刷新（不出现骨架/链接闪回）。 */
export const REPO_DOC_CACHE_MAX_AGE_MS = 5 * 60 * 1000

interface PersistedMetaEntry {
  at: number
  meta: RepoDocMeta
}
interface PersistedPreviewEntry {
  at: number
  text: string
}
interface PersistedRepoDocCache {
  v: 1
  /**
   * ★缓存归属的用户 id。资料库权限是**按人**算的，同一浏览器换账号登录后
   * 绝不能把上一个账号看过的标题/摘要继续挂在新账号的卡片上。
   */
  user?: string
  metas?: Record<string, PersistedMetaEntry>
  previews?: Record<string, PersistedPreviewEntry>
}

/** 当前登录用户 id（IM 把用户信息放在 USER_INFO）；读不到就当匿名。 */
function currentCacheUserId(): string | null {
  try {
    const raw = cardStorage()?.getItem('USER_INFO')
    if (!raw) return null
    const user = JSON.parse(raw) as { id?: unknown; userId?: unknown } | null
    const id = user?.id ?? user?.userId
    return id == null ? null : String(id)
  } catch {
    return null
  }
}

let hydrated = false

/** localStorage 在老浏览器/隐私模式/SSR 下都可能不可用 —— 一律当成"没有缓存"。 */
function cardStorage(): Storage | null {
  try {
    if (typeof localStorage === 'undefined') return null
    return localStorage
  } catch {
    return null
  }
}

/**
 * 把上次会话渲染过的卡片读回内存。
 *
 * <p>只在这里信任自己的数据格式，但字段仍走 {@link normalizeMeta}：
 * 版本升级或半截写入留下的脏数据不应让整张卡片变成空白。
 */
function hydrateRepoDocCardCache(): void {
  if (hydrated) return
  hydrated = true
  const store = cardStorage()
  if (!store) return

  let data: PersistedRepoDocCache | null = null
  try {
    data = JSON.parse(store.getItem(REPO_DOC_CACHE_STORAGE_KEY) ?? 'null') as PersistedRepoDocCache | null
  } catch {
    return
  }
  if (!data || data.v !== 1) return
  // 换了账号（或旧版本缓存没记归属）⇒ 整份缓存作废，不能跨用户复用权限/摘要。
  if ((data.user ?? null) !== currentCacheUserId()) return

  if (data.metas && typeof data.metas === 'object') {
    for (const [slug, entry] of Object.entries(data.metas)) {
      const meta = entry && typeof entry === 'object' ? normalizeMeta(entry.meta, slug) : null
      if (!meta) continue
      metaCache.set(slug, meta)
      metaSavedAt.set(slug, Number(entry.at) || 0)
    }
  }
  if (data.previews && typeof data.previews === 'object') {
    for (const [key, entry] of Object.entries(data.previews)) {
      const id = Number(key)
      if (!Number.isFinite(id) || !entry || typeof entry.text !== 'string') continue
      previewCache.set(id, entry.text)
      previewSavedAt.set(id, Number(entry.at) || 0)
    }
  }
}

/** 写回 localStorage。失败（配额/隐私模式）静默放弃，不影响当前页面的内存缓存。 */
function persistRepoDocCardCache(): void {
  const store = cardStorage()
  if (!store) return
  try {
    const metas = [...metaCache.entries()]
      .filter((entry): entry is [string, RepoDocMeta] => entry[1] != null)
      .sort((a, b) => (metaSavedAt.get(b[0]) ?? 0) - (metaSavedAt.get(a[0]) ?? 0))
      .slice(0, REPO_DOC_CACHE_LIMIT)
    const previews = [...previewCache.entries()]
      .filter((entry): entry is [number, string] => typeof entry[1] === 'string' && entry[1] !== '')
      .sort((a, b) => (previewSavedAt.get(b[0]) ?? 0) - (previewSavedAt.get(a[0]) ?? 0))
      .slice(0, REPO_DOC_CACHE_LIMIT)

    const payload: PersistedRepoDocCache = {
      v: 1,
      user: currentCacheUserId() ?? undefined,
      metas: Object.fromEntries(
        metas.map(([slug, meta]) => [slug, { at: metaSavedAt.get(slug) ?? 0, meta }]),
      ),
      previews: Object.fromEntries(
        previews.map(([id, text]) => [String(id), { at: previewSavedAt.get(id) ?? 0, text }]),
      ),
    }
    store.setItem(REPO_DOC_CACHE_STORAGE_KEY, JSON.stringify(payload))
  } catch {
    /* 配额满 / 隐私模式：内存缓存仍然有效 */
  }
}

/** 已缓存的元数据：{@code undefined} = 还没查过；{@code null} = 查过但失败。 */
export function cachedRepoDocMeta(slug: string): RepoDocMeta | null | undefined {
  hydrateRepoDocCardCache()
  return metaCache.get(slug)
}

/** 已缓存的正文预览：{@code undefined} = 还没查过；{@code null} = 查过但拿不到。 */
export function cachedRepoDocPreview(id: number): string | null | undefined {
  hydrateRepoDocCardCache()
  return previewCache.get(id)
}

/** 缓存是否已经超过静默刷新窗口（没有时间戳的旧数据也刷新一次）。 */
export function shouldRefreshRepoDocMeta(
  slug: string,
  maxAgeMs = REPO_DOC_CACHE_MAX_AGE_MS,
): boolean {
  hydrateRepoDocCardCache()
  if (!metaCache.get(slug)) return false
  const at = metaSavedAt.get(slug) ?? 0
  return !at || Date.now() - at > maxAgeMs
}

/** 预览是否已经超过静默刷新窗口。 */
export function shouldRefreshRepoDocPreview(
  id: number,
  maxAgeMs = REPO_DOC_CACHE_MAX_AGE_MS,
): boolean {
  hydrateRepoDocCardCache()
  const text = previewCache.get(id)
  if (typeof text !== 'string' || !text) return false
  const at = previewSavedAt.get(id) ?? 0
  return !at || Date.now() - at > maxAgeMs
}

/** 单测用：清空模块级缓存（生产代码不要调）。 */
export function resetRepoDocCardCache(): void {
  metaCache.clear()
  metaInflight.clear()
  previewCache.clear()
  previewInflight.clear()
  metaSavedAt.clear()
  previewSavedAt.clear()
  hydrated = false
}

/** 单测用：清掉持久化缓存（生产代码不要调）。 */
export function clearRepoDocCardStorage(): void {
  try {
    cardStorage()?.removeItem(REPO_DOC_CACHE_STORAGE_KEY)
  } catch {
    /* 不可用即无需清理 */
  }
}

export interface RepoDocLoadOptions {
  /** true = 即使有缓存也重新请求；失败时保留旧缓存（静默刷新专用）。 */
  force?: boolean
}

/**
 * 查一份文档的元数据。**永不抛错**：任何网络/格式问题都归一成 {@code null}。
 *
 * @param slug     正文里的 slug
 * @param doFetch  仅单测注入；生产不传
 * @param opts     {@code force:true} 用于静默刷新
 */
export function loadRepoDocMeta(
  slug: string,
  doFetch: typeof fetch = fetch,
  opts: RepoDocLoadOptions = {},
): Promise<RepoDocMeta | null> {
  hydrateRepoDocCardCache()
  const cached = metaCache.get(slug)
  if (!opts.force && cached !== undefined) return Promise.resolve(cached)
  const flying = metaInflight.get(slug)
  if (flying) return flying

  const task = (async (): Promise<RepoDocMeta | null> => {
    let next: RepoDocMeta | null = null
    try {
      const res = await doFetch(`/api/repo/s/${encodeURIComponent(slug)}`, {
        method: 'GET',
        credentials: 'include',
      })
      if (res.ok) {
        const json = (await res.json()) as { code?: string; data?: unknown } | null
        if (json?.code === OK_CODE) next = normalizeMeta(json.data, slug)
      }
    } catch {
      next = null
    } finally {
      metaInflight.delete(slug)
    }

    if (next) {
      metaCache.set(slug, next)
      metaSavedAt.set(slug, Date.now())
      persistRepoDocCardCache()
      return next
    }
    // 静默刷新失败：保留上次已渲染的卡片，别把内容换成一条裸链接。
    if (cached === undefined) metaCache.set(slug, null)
    return cached ?? null
  })()

  metaInflight.set(slug, task)
  return task
}

/**
 * 取文档正文预览（纯文本）。**永不抛错**。
 *
 * <p>★★预览接口按「能否导出」分流：
 * <ul>
 *   <li>可导出 → {@code /pages/{id}/export/markdown}（现有导出口径）；</li>
 *   <li>不可导出但可查看（例如只给了「可评论」）→ {@code /pages/{id}/preview/markdown}。
 *       后者只要求 viewable，且服务端只回截断后的摘要，不会把整篇允许被导出。</li>
 * </ul>
 * 早期版本在 exportable=false 时直接返回 null，表现就是接收方卡片只有
 * 「打开文档查看全文」——正文链接明明看得到，摘要却一片空白。
 */
export function loadRepoDocPreview(
  meta: RepoDocMeta,
  doFetch: typeof fetch = fetch,
  opts: RepoDocLoadOptions = {},
): Promise<string | null> {
  hydrateRepoDocCardCache()
  const cached = previewCache.get(meta.id)
  if (!opts.force && cached !== undefined) return Promise.resolve(cached)
  const flying = previewInflight.get(meta.id)
  if (flying) return flying

  // 不可导出 ≠ 不可查看：用只读摘要接口，注释类用户也能看到正文前几行。
  // 权限字段缺失/判断失准时，导出失败后再兜底试一次只读接口。
  const preferred = meta.myAccess?.exportable === false ? 'preview/markdown' : 'export/markdown'

  const fetchMarkdown = async (kind: 'export/markdown' | 'preview/markdown'): Promise<string | null> => {
    try {
      const res = await doFetch(`/api/repo/pages/${meta.id}/${kind}`, {
        method: 'GET',
        credentials: 'include',
      })
      if (!res.ok) return null
      const json = (await res.json()) as { code?: string; data?: { markdown?: unknown } } | null
      if (json?.code !== OK_CODE) return null
      const markdown = typeof json.data?.markdown === 'string' ? json.data.markdown : ''
      return previewTextOfMarkdown(stripMarkdownTitle(markdown, meta.title)) || null
    } catch {
      return null
    }
  }

  const task = (async (): Promise<string | null> => {
    let next = await fetchMarkdown(preferred)
    if (next == null && preferred !== 'preview/markdown') {
      next = await fetchMarkdown('preview/markdown')
    }
    previewInflight.delete(meta.id)

    if (next) {
      previewCache.set(meta.id, next)
      previewSavedAt.set(meta.id, Date.now())
      persistRepoDocCardCache()
      return next
    }
    // 静默刷新失败：保留旧预览，避免内容区忽然变成"打开文档查看全文"。
    if (cached === undefined) previewCache.set(meta.id, null)
    return cached ?? null
  })()

  previewInflight.set(meta.id, task)
  return task
}

/** 去掉行内 Markdown 标记，只留用户能读的文字。 */
function stripInlineMarkdown(line: string): string {
  return line
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/<[^>]+>/g, '')
    .replace(/`{1,3}([^`]*)`{1,3}/g, '$1')
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    .replace(/~~([^~]+)~~/g, '$1')
    .replace(/(^|[^*])\*([^*\n]+)\*/g, '$1$2')
    .replace(/(^|[^_])_([^_\n]+)_/g, '$1$2')
    .replace(/\\([\\`*_{}[\]()#+\-.!])/g, '$1')
    .replace(/\s+/g, ' ')
    .trim()
}

/**
 * 去掉 Markdown 开头那个与文档标题重复的 H1。
 *
 * <p>导出接口通常把标题写成 {@code # 标题} 放在正文最前面；卡片头部已经显示了
 * 同一个标题，预览区再重复一遍会白占一行。只处理**真正的 H1 行**（不是任意首行），
 * 且标题可以带后缀（例如元数据是「标题-20260924」、正文 H1 是「标题」）。
 */
export function stripMarkdownTitle(markdown: string, title: string): string {
  const src = (markdown ?? '').replace(/\r\n?/g, '\n')
  const want = (title ?? '').trim()
  if (!src || !want) return src

  const lines = src.split('\n')
  let i = 0
  while (i < lines.length && !lines[i].trim()) i += 1
  const m = i < lines.length ? /^#\s+(.+?)\s*#*\s*$/.exec(lines[i].trim()) : null
  if (!m) return src

  const heading = stripInlineMarkdown(m[1])
  if (!heading) return src
  const same = heading === want || want.startsWith(heading) || heading.startsWith(want)
  if (!same) return src

  lines.splice(0, i + 1)
  return lines.join('\n')
}

/**
 * Markdown → 卡片正文预览。
 *
 * <p>不做完整 Markdown 渲染（预览区只有几行，渲染出来的标题/表格反而喧宾夺主），
 * 只做"能读"这一件事：去掉标记行与标记符、把表格行压成以 {@code ·} 分隔的一行、
 * 跳过空行，最后按字符数与行数双重截断。
 *
 * <p>★纯函数、有单测：截断方式一旦改坏，最典型的症状是卡片里出现半截表格
 * （{@code |---}）或一大片空白 —— 用户不会报"预览错了"，只会觉得卡片很脏。
 */
export function previewTextOfMarkdown(
  markdown: string,
  maxChars = REPO_DOC_PREVIEW_MAX_CHARS,
  maxLines = REPO_DOC_PREVIEW_MAX_LINES,
): string {
  const src = (markdown ?? '').replace(/\r\n?/g, '\n')
  if (!src.trim()) return ''

  const lines: string[] = []
  for (const original of src.split('\n')) {
    let line = original.trim()
    if (!line) continue

    // 围栏：标记行本身丢掉，代码内容保留。
    if (/^```/.test(line)) continue
    // 表格分隔行（|---|:---:|）与水平线。
    if (/^\|?[\s:|-]*-[\s:|-]*\|?$/.test(line)) continue
    if (/^([-*_]\s*){3,}$/.test(line)) continue

    // 标题 / 引用 / 列表 / 任务列表的前缀。
    line = line
      .replace(/^#{1,6}\s+/, '')
      .replace(/^>\s?/, '')
      .replace(/^[-*+]\s+/, '')
      .replace(/^\d+[.)]\s+/, '')
      .replace(/^\[[ xX]\]\s+/, '')

    // 表格行：把单元格压成一行。
    if (/^\|.*\|$/.test(line)) {
      line = line
        .replace(/^\|/, '')
        .replace(/\|$/, '')
        .split('|')
        .map(stripInlineMarkdown)
        .filter(Boolean)
        .join(' · ')
    } else {
      line = stripInlineMarkdown(line)
    }

    if (!line) continue
    // ★HTML 注释/纯符号行（例如原文档里的 `*** ** * ** ***`）不该占一行。
    if (!/[\p{L}\p{N}]/u.test(line)) continue
    lines.push(line)
  }

  let out = ''
  let usedLines = 0
  for (const line of lines) {
    if (usedLines >= maxLines) break
    const next = out ? `${out}\n${line}` : line
    if (next.length > maxChars) {
      const room = Math.max(0, maxChars - out.length - (out ? 1 : 0))
      if (room > 1) {
        out = out ? `${out}\n${line.slice(0, room - 1)}…` : `${line.slice(0, room - 1)}…`
      } else if (out) {
        out = `${out.slice(0, Math.max(0, maxChars - 1))}…`
      }
      return out
    }
    out = next
    usedLines += 1
  }

  if (lines.length > usedLines) {
    // 行数截断时也给省略号，用户才知道下面还有内容。
    const withEllipsis = `${out}…`
    return withEllipsis.length > maxChars
      ? `${out.slice(0, Math.max(0, maxChars - 1))}…`
      : withEllipsis
  }
  return out
}
