/**
 * ★★会中「分享至会话」面板 —— 把会议信息作为一条消息发到选中的会话里。
 *
 * <h2>与「邀请参会人」的区别</h2>
 *
 * <p>两个入口长得很像，语义完全不同，不要合并：
 * <ul>
 *   <li>{@code MeetingInvitePanel}：从<b>联系人</b>里选人，走 {@code meeting_invite}
 *       消息，对方收到的是<b>来电式入会通知</b>（响铃 + 接听按钮）；</li>
 *   <li>本面板：从<b>会话</b>里选目标，走普通 {@code sendText}，把会议主题 / 会议号 /
 *       链接作为一条<b>可回看的聊天消息</b>发过去。群聊、团队群都能发 ——
 *       这正是用户说的"分享至会话"，与飞书截图里「会议信息」旁边那个图标一致。</li>
 * </ul>
 *
 * <h2>★为什么自绘</h2>
 *
 * <p>会中界面会渲染进独立窗口（另一个 document），antd 的 cssinjs 只注入主文档
 * —— 所以这里<b>只用项目自己的 CSS 类</b>，并复用邀请面板那套 {@code meet-invite-panel-*}
 * 样式（同一块视觉语言，独立窗口里也完整可见）。
 *
 * <h2>★逐条发送、失败只计数</h2>
 *
 * <p>某个会话发不出去（被禁言、会话已删、网络抖）不该让后面的全部落空；
 * 也不该把已经发成功的说成失败。结果就地写在面板里（独立窗口里没有 antd toast）。
 */
import { useMemo, useState } from 'react';

import { avatarTone } from '../lib/avatarTone';
import { convTitleOf } from '../lib/convTitle';
import { buildMeetingInviteText, formatMeetingId } from '../lib/meetingLink';
import { useChatStore } from '../store/chat';
import { GroupAvatarText } from './GroupAvatarText';
import { IconExternal, IconSearch } from './icons';
import SmartImg from './SmartImg';

export interface MeetingSharePanelProps {
  /** 会议主题（消息正文第一段）。 */
  title: string;
  /** 会议号（正文与标题都用它）。 */
  roomName: string;
  /** 入会链接（可能为空 —— 拿不到链接时正文里就不写这一行）。 */
  inviteUrl: string;
  /** 发起人昵称（"xxx 邀请你加入…"）。 */
  inviter: string;
  onClose: () => void;
}

/** 会话列表在面板里的展示上限：再多就该用搜索，滚 200 行找一条会话没有意义。 */
const SHARE_LIST_LIMIT = 60;

export default function MeetingSharePanel({
  title,
  roomName,
  inviteUrl,
  inviter,
  onClose,
}: MeetingSharePanelProps) {
  const convs = useChatStore((s) => s.convs);
  const myUserId = useChatStore((s) => s.userId);
  const [keyword, setKeyword] = useState('');
  const [selected, setSelected] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState<string | null>(null);

  const items = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    const rows = (convs ?? []).map((c) => {
      const isGroup = c.convType !== 1;
      return {
        convId: String(c.convId),
        name: convTitleOf(c, myUserId),
        /** 单聊 / 群聊：只用来在名字后面给个小标签，不参与任何逻辑判断。 */
        kind: isGroup ? '群聊' : '单聊',
        /** ★图源判据与左栏会话列表（{@code ConvList}）逐字同款：群 = c.avatar、单聊 = c.peerAvatar。 */
        avatar: (isGroup ? c.avatar : c.peerAvatar) || '',
        isGroup,
      };
    });
    const hit = kw
      ? rows.filter((r) => r.name.toLowerCase().includes(kw) || r.convId.includes(kw))
      : rows;
    return hit.slice(0, SHARE_LIST_LIMIT);
  }, [convs, keyword, myUserId]);

  /** ★已选但被关键字筛掉的会话仍要能提交：用户选过就是选过。 */
  const selectedRows = useMemo(() => {
    const byId = new Map((convs ?? []).map((c) => [String(c.convId), c]));
    return selected
      .filter((id) => byId.has(id))
      .map((id) => ({
        convId: id,
        name: convTitleOf(byId.get(id)!, myUserId),
      }));
  }, [convs, selected, myUserId]);

  const toggle = (convId: string) => {
    setStatus(null);
    setSelected((cur) => (cur.includes(convId) ? cur.filter((x) => x !== convId) : [...cur, convId]));
  };

  const submit = async () => {
    if (busy || selectedRows.length === 0) return;
    setBusy(true);
    setStatus(null);
    // ★正文与会中「复制邀请信息」同一个构造函数：同一个会议不能在聊天里出现两种说法
    const text = buildMeetingInviteText({ inviter, title, roomName, url: inviteUrl });
    let ok = 0;
    const failed: string[] = [];
    for (const row of selectedRows) {
      try {
        await useChatStore.getState().sendText(row.convId, text);
        ok += 1;
      } catch {
        failed.push(row.name);
      }
    }
    setBusy(false);
    setSelected([]);
    setStatus(
      failed.length === 0
        ? `已分享到 ${ok} 个会话`
        : ok > 0
          ? `已分享到 ${ok} 个会话，${failed.length} 个没发出去（${failed.slice(0, 3).join('、')}）`
          : `没发出去：${failed.slice(0, 3).join('、')}`,
    );
  };

  return (
    <div className="meet-invite-panel-layer" role="dialog" aria-label="分享至会话">
      <div className="meet-invite-panel">
        <div className="meet-invite-panel-head">
          <div className="meet-invite-panel-title">
            <IconExternal size={16} />
            分享至会话
          </div>
          <button type="button" className="meet-invite-panel-x" title="关闭" onClick={onClose}>
            ×
          </button>
        </div>

        <div className="meet-invite-panel-hint">
          把会议主题、会议号与入会链接作为一条消息发到选中的会话。
        </div>

        {/*
          ★搜索框重做（用户 2026-11-07 截图）：原来是一个裸 input，看起来和列表行
          不是一套东西，输入的字还会被行高挤到边缘。现在 图标 + 输入 + 清空 三段式，
          高度与圆角跟列表行对齐。★独立窗口里 antd 不可用，所以是自绘。
        */}
        <div className="meet-invite-panel-search">
          <IconSearch size={15} className="meet-invite-panel-search-ico" />
          <input
            className="meet-invite-panel-search-input"
            value={keyword}
            placeholder="搜索会话（群名 / 对方昵称）"
            aria-label="搜索会话"
            onChange={(e) => setKeyword(e.target.value)}
          />
          {keyword && (
            <button
              type="button"
              className="meet-invite-panel-search-clear"
              title="清空搜索"
              aria-label="清空搜索"
              onClick={() => setKeyword('')}
            >
              ×
            </button>
          )}
        </div>

        <div className="meet-invite-panel-list">
          {items.length === 0 && (
            <div className="meet-invite-panel-empty">
              {keyword.trim() ? '没有匹配的会话' : '还没有会话可以分享'}
            </div>
          )}
          {items.map((c) => {
            const on = selected.includes(c.convId);
            return (
              <button
                key={c.convId}
                type="button"
                className={`meet-invite-row${on ? ' is-on' : ''}`}
                onClick={() => toggle(c.convId)}
                aria-pressed={on}
              >
                <span className="meet-invite-row-check" aria-hidden>
                  {on ? '✓' : ''}
                </span>
                {/*
                  ★头像走真实图源（用户 2026-11-07：「会话的头像没有展示正确」）。
                  以前这里恒画首字，等于把所有会话头像都丢了。判据与左栏会话列表同款：
                  群 = c.avatar、单聊 = c.peerAvatar；加载失败回落 群名前四字 / 首字，
                  底色按名字取（与列表里的彩色首字是同一套规则）。
                */}
                <span className="meet-invite-row-avatar" style={avatarTone(c.name)}>
                  {c.avatar ? (
                    <SmartImg
                      src={c.avatar}
                      alt=""
                      style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                      fallback={c.isGroup ? <GroupAvatarText name={c.name} /> : c.name.trim().slice(0, 1) || '?'}
                    />
                  ) : c.isGroup ? (
                    <GroupAvatarText name={c.name} />
                  ) : (
                    c.name.trim().slice(0, 1) || '?'
                  )}
                </span>
                <span className="meet-invite-row-name">{c.name}</span>
                <span className="meet-share-kind">{c.kind}</span>
              </button>
            );
          })}
        </div>

        {status && <div className="meet-invite-panel-status">{status}</div>}

        <div className="meet-invite-panel-foot">
          <span className="meet-invite-panel-count">
            {selectedRows.length > 0 ? `已选 ${selectedRows.length} 个会话` : `会议号 ${formatMeetingId(roomName)}`}
          </span>
          <button type="button" className="meet-invite-panel-btn" onClick={onClose} disabled={busy}>
            取消
          </button>
          <button
            type="button"
            className="meet-invite-panel-btn is-primary"
            disabled={busy || selectedRows.length === 0}
            onClick={() => void submit()}
          >
            {busy ? '发送中…' : '发送'}
          </button>
        </div>
      </div>
    </div>
  );
}
