import { IconChat, IconClose, IconDanmaku, IconHand, IconMicOff, IconMicOn, IconPhone, IconPhoneOff, IconRecord, IconScreenShare, IconScreenShareOff, IconSend, IconStop, IconSwitchView, IconUsers, IconUsersPlus, IconVideo, IconVideoOff } from './icons';
import MeetingInfoPanel from './MeetingInfoPanel';
