/** 每秒刷新一次计时；只在通话中启用，其余状态不空转。 */
function useTicker(enabled: boolean): void {
  const [, setTick] = useState(0);
  useEffect(() => {
    if (!enabled) return;
    const t = window.setInterval(() => setTick((n) => n + 1), 1000);
    return () => window.clearInterval(t);
  }, [enabled]);
}

function avatarNode(name: string, url: string | undefined, large: boolean): JSX.Element {
  if (url) {
    return <img className={large ? 'call-avatar call-avatar-lg' : 'call-avatar'} src={url} alt="" />;
  }
  return (
    <span className={large ? 'call-avatar call-avatar-lg call-avatar-text' : 'call-avatar call-avatar-text'}>
      {(name || '?').slice(0, 1)}
    </span>
  );
}

export interface CallOverlayProps {
  /** ★true = 渲染在独立窗口里那份（见 {@code MeetingPopout}）：铺满窗口、无遮罩、无最小化。 */
  standalone?: boolean;
}

export default function CallOverlay({ standalone = false }: CallOverlayProps) {
  const phase = useCallStore((s) => s.phase);
  /**
   * ★★会中让手机别熄屏（用户 2026-11-09：「在手机浏览器打开进行会议时，是否能让手机不黑屏」）。
   *
   * <p>只在真正进了会议（{@code active}）之后持锁：响铃阶段手机可能还在口袋里，
   * 为一个没接的通话点亮屏幕只是白耗电。实现与限制（必须 https、切后台回来要重新申请）
   * 见 {@code lib/screenWakeLock.ts}。
   */
  useScreenWakeLock(phase === 'active');
  const call = useCallStore((s) => s.call);
  const ended = useCallStore((s) => s.ended);
  const micOn = useCallStore((s) => s.micOn);
  const cameraOn = useCallStore((s) => s.cameraOn);
  const screenOn = useCallStore((s) => s.screenOn);
  const remoteScreenOn = useCallStore((s) => s.remoteScreenOn);
  const remoteCameraOn = useCallStore((s) => s.remoteCameraOn);
  const audioBlocked = useCallStore((s) => s.audioBlocked);
  const remoteCount = useCallStore((s) => s.remoteCount);
  const minimized = useCallStore((s) => s.minimized);
  /** ★会中面板是否在独立窗口里（本页那份据此退化成一条胶囊）。 */
  const popout = useCallStore((s) => s.popout);
  const mainView = useCallStore((s) => s.mainView);
  const recording = useCallStore((s) => s.recording);
  const recordingStartedAt = useCallStore((s) => s.recordingStartedAt);
  const recordingBusy = useCallStore((s) => s.recordingBusy);
  /**
   * ★EGRESS_STARTING ≠ 已经在录：egress 要先连 Redis、拉起 Chrome、加入房间，
   * 通常 5~10 秒后才真正开始产出。这期间 UI 必须显示"启动中"，
   * 否则用户以为已经在录，一旦此时散会就会得到一份"录音失败"。
   */
  const recordingStatus = useCallStore((s) => s.recordingStatus);
  const recordingEgressId = useCallStore((s) => s.recordingEgressId);
  const recordingFile = useCallStore((s) => s.recordingFile);
  const notice = useCallStore((s) => s.notice);
  const clearNotice = useCallStore((s) => s.clearNotice);
  const participants = useCallStore((s) => s.participants);
  const refreshParticipants = useCallStore((s) => s.refreshParticipants);
  const kickParticipant = useCallStore((s) => s.kickParticipant);
  const muteParticipant = useCallStore((s) => s.muteParticipant);
  const muteAll = useCallStore((s) => s.muteAll);
  const updateRoomSettings = useCallStore((s) => s.updateRoomSettings);
  const setParticipantMicAllowed = useCallStore((s) => s.setParticipantMicAllowed);
  const myUserId = useChatStore((s) => s.userId);
  /** ★邀请文案第一行的发起人昵称（拿不到时整句退化成"邀请你加入"）。 */
  const myName = useChatStore((s) => s.userName);
  /** ★我自己的头像：本地 attributes 还没落到房内时，用登录态兜底，别让自己的格子闪一下首字。 */
  const myAvatarUrl = useChatStore((s) => s.avatar);

  const accept = useCallStore((s) => s.accept);
  const decline = useCallStore((s) => s.decline);
  const hangup = useCallStore((s) => s.hangup);
  const endRoomMeeting = useCallStore((s) => s.endRoomMeeting);
  const toggleMic = useCallStore((s) => s.toggleMic);
  const toggleCamera = useCallStore((s) => s.toggleCamera);
  const toggleScreenShare = useCallStore((s) => s.toggleScreenShare);
  const toggleRecording = useCallStore((s) => s.toggleRecording);
  const toggleMainView = useCallStore((s) => s.toggleMainView);
  const retryAudio = useCallStore((s) => s.retryAudio);
  const setMinimized = useCallStore((s) => s.setMinimized);
  const setPopout = useCallStore((s) => s.setPopout);
  const clearEnded = useCallStore((s) => s.clearEnded);

  const isVideo = call?.mediaType === 'video';
  /**
   * ★★房间会议（「会议」栏 → 发起/加入）与 1v1 通话共用这套浮层，但三处文案必须分开：
   * 对面没人不是"对方还没接"，退出不是"挂断"（他一走会就散了，会议还在）。
   */
  const isRoom = call?.mode === 'room';
  /**
   * ★★我是不是这场会的主持人 —— 以<b>服务端令牌</b>为准（见 {@code lib/meetingLeave}）：
   * 主持人断线后重新「加入」时 direction 会变成 in，但服务端仍认为他是房主。
   */
  const amHost = call
    ? amIHost({ mode: call.mode, direction: call.direction, isHost: call.isHost })
    : false;
  useTicker(phase === 'active');

  /**
   * 复制结果的临时态：`idle` / `ok` / `fail`。
   *
   * ★★失败必须显示出来：会中面板可能渲染在独立窗口里，那里 `navigator.clipboard`
   * 在 http 下不存在、`execCommand` 又要落在弹窗自己的 document 上 —— 失败是真实存在的。
   * 之前失败直接 return，用户看到的是"点了没反应"，只能靠反复点击（还选中了按钮文字）。
   */
  const [noCopied, setNoCopied] = useState<'idle' | 'ok' | 'fail'>('idle');
  /** 邀请链接的复制结果（与会议号分开，避免两个按钮互相串提示）。 */
  const [linkCopied, setLinkCopied] = useState<'idle' | 'ok' | 'fail'>('idle');
  /**
   * ★确认框状态。<b>自己画</b>而不走 {@code Modal.confirm}：独立窗口那份没有 antd 样式
   * （antd v5 把样式注入主文档 head），用 Modal 会在弹出窗外渲染成一个没有排版的裸框。
   */
  const [confirm, setConfirm] = useState<
    { kind: 'leave' } | { kind: 'kick'; userId: string; name: string } | null
  >(null);
  /** ★放大布局（飞书式大窗口）：仅房间会议用，1v1 通话保持小浮层。 */
  const [large, setLarge] = useState(false);
  /** ★右侧参会人面板是否展开。 */
  const [panelOpen, setPanelOpen] = useState(false);
  /**
   * ★会中「邀请参会人」面板是否展开（见 {@code MeetingInvitePanel}）。
   *
   * <p>只在<b>房间会议</b>里给入口：1v1 通话的语义是"通话"，把联系人拉进来这件事
   * 该走「发起会议」，否则会变成"多人电话"——那是另一个产品决定，不是顺手加的按钮。
   */
  const [inviteOpen, setInviteOpen] = useState(false);
  /**
   * ★「分享至会话」面板是否展开（见 {@code MeetingSharePanel}）。
   *
   * <p>与「邀请参会人」是两个不同的动作：这个把会议信息<b>发成一条聊天消息</b>，
   * 收件人不必立刻入会；那个是来电式入会通知。
   */
  const [shareOpen, setShareOpen] = useState(false);
  /**
   * ★会中「会议信息」面板（飞书左上角那个入口）：主题 / 会议号 / 链接 / 时长。
   *
   * <p>会议号与邀请链接从舞台左上角的两个按钮搬到了这里 —— 它们属于"会议的画面之外
   * 的衣服"，常驻会挡舞台；但也不能删掉入口，用户"进来了才想起来要告诉别人号"是常态。
   * 所以：入口常驻顶栏，详情收进面板。
   */
  const [infoOpen, setInfoOpen] = useState(false);
  /** ★独立窗口里永远是"大窗口 + 面板"的形态：窗口本身就能拉伸，没有"还原成小浮层"的意义。 */
  const largeUi = standalone || large;
  /**
   * ★每场会只在<b>第一次进入 active</b> 时自动展开一次大窗口 + 参会人面板。
   *
   * <p>不这么做的话用户要自己点两下才能看到"谁在会里"，而这是会中最先要确认的事；
   * 但也不能每次重渲染都强制展开 —— 用户收起了面板就必须保持收起。
   */
  /**
   * ★离开 / 结束会议时把会中弹层关掉。
   *
   * <p>这两个标志只控制"弹层是否展开"，它们不会随会议结束自动归零；
   * 下一场会如果原地复用同一个组件实例，用户会一进来就被上场的面板糊一脸。
   */
  useEffect(() => {
    if (phase !== 'active') {
      setInfoOpen(false);
      setInviteOpen(false);
    }
  }, [phase]);

  const autoOpenedCallId = useRef<string | null>(null);
  useEffect(() => {
    if (phase !== 'active' || !call || call.mode !== 'room') return;
    if (autoOpenedCallId.current === call.callId) return;
    autoOpenedCallId.current = call.callId;
    setLarge(true);
    setPanelOpen(true);
  }, [phase, call]);

  /**
   * ★★【不要在这里自动 setPopout(true)】—— 这条路径没有用户手势。
   *
   * <p>这里曾经有一个 {@code autoPopoutCallId} effect：会议一进 active 就自动丢进独立窗口。
   * 但 effect 已经脱离点击任务：{@code documentPictureInPicture.requestWindow} 会被拒，
   * 而 {@code window.open} 又可能因为"点击后几秒内仍算激活"而<b>成功</b>——
   * 成功恰恰是最坏的结果：开出来的是<b>带 {@code about:blank} 地址栏的普通弹窗</b>
   * （Chrome 从不允许隐藏地址栏），也就是用户反复看到的那一行。
   *
   * <p>现在只有两个开窗点，且都在手势里：{@code MeetingPane.openRoomWindow}
   * 与下面「在新窗口中打开」按钮。其余路径一律留在本页大窗口。
   */

  /** ★「在新窗口中打开」被拦时的临时提示（2.6 秒后自动消失）。 */
  const [popoutBlocked, setPopoutBlocked] = useState(false);
  const popoutTipTimer = useRef<number | null>(null);
  const openPopout = useCallback(() => {
    const title = call?.title || call?.convTitle || '会议';
    // ★必须在这里 prime：等到 MeetingPopout 的 effect 里再开，用户手势已经过期，
    //   画中画会被拒，回落出去的就是带 about:blank 的普通弹窗。
    if (!primeMeetingWindow(title)) {
      setPopoutBlocked(true);
      if (popoutTipTimer.current) window.clearTimeout(popoutTipTimer.current);
      popoutTipTimer.current = window.setTimeout(() => setPopoutBlocked(false), 2600);
      return;
    }
    setPopout(true);
  }, [call?.title, call?.convTitle, setPopout]);

  useEffect(
    () => () => {
      if (popoutTipTimer.current) window.clearTimeout(popoutTipTimer.current);
    },
    [],
  );

  /**
   * ★参会人按"人"聚合（服务端是席位：同账号多端会返回多条）。
   * 自引用 userId 优先、identity 兜底 —— 两者都可能一时拿不到。
   */
  const rows = useMemo(
    () =>
      isRoom
        ? aggregateParticipants(participants, {
            userId: myUserId == null ? null : String(myUserId),
            identity: call?.selfIdentity ?? null,
          })
        : [],
    [isRoom, participants, myUserId, call?.selfIdentity],
  );
  /**
   * ★已经在会的人的 userId —— 邀请面板要拿它把候选人剔掉。
   *
   * <p>用 {@code rows}（按人聚合过的）而不是 {@code participants}（按席位）：
   * 同一个人开三端会算作一条，不会在候选人里出现"三个同名的人"。
   * 外部接入的参与者没有 IM userId，剔不掉也无妨 —— 他们本来就不在联系人里。
   */
  const inMeetingUserIds = useMemo(
    () => rows.map((r) => r.userId).filter((v): v is string => v != null && v !== ''),
    [rows],
  );

  /**
   * ★★会中布局的参会人格子 —— LiveKit 的真实轨道 + 服务端的身份信息。
   *
   * <p>只有 LiveKit 快照能画画面（{@code <video>} 要的是轨道对象），
   * 只有服务端视图知道"谁是主持人、这个人开了几端"（见 lib/meetingPeersView 的文件头）。
   * 两者按 identity 对齐。
   *
   * <p>★用 {@link peersEqual} 做浅比较：LiveKit 每 2 秒有一次自愈复算，
   * 每次都 setState 会把整块会中界面重渲染一遍（画面闪烁）。
   */
  const [roomPeers, setRoomPeers] = useState<RoomPeerView[]>([]);
  useEffect(() => {
    if (!isRoom) {
      setRoomPeers([]);
      return;
    }
    const sync = () => {
      const next = buildRoomPeers(getPeers(), rows, myAvatarUrl);
      setRoomPeers((prev) => (peersEqual(prev, next) ? prev : next));
    };
    sync();
    return subscribePeers(sync);
  }, [isRoom, rows, myAvatarUrl]);

  /**
   * ★★会中开关（全员禁言 / 弹幕）与举手状态。
   *
   * <p>数据源是 LiveKit 房间 metadata（见 {@code lib/livekitRoom.RoomSettings}）：
   * 主持人一改，房内所有人<b>立刻</b>收到 {@code RoomMetadataChanged}，
   * 不必等 5 秒一次的成员轮询 —— 禁言晚 5 秒生效，这句话已经喊完了。
   */
  const [settings, setSettings] = useState<RoomSettings>(() => getRoomSettings());
  const [handRaised, setHandRaisedState] = useState(false);
  useEffect(() => {
    if (!isRoom || phase !== 'active') return;
    setSettings(getRoomSettings());
    setHandRaisedState(isHandRaised());
    return subscribeRoomSettings((next) => setSettings(next));
  }, [isRoom, phase]);

  /**
   * ★每条弹幕一个泳道（同屏不重叠）+ 一条算出来的飞行时长。
   *
   * <p>这里修过两个用户看得到的问题：
   * <ol>
   *   <li><b>「发了弹幕没上屏」</b>：回调里原来拿 {@code getRoomSettings().danmaku} 直接
   *       {@code return} —— 那是<b>房间开关的模块快照</b>，和点击"开启弹幕"之间存在时序差，
   *       自己刚发的那条也会被一起丢掉。现在<b>自己的永远上屏</b>，只拦别人的。</li>
   *   <li><b>「飘得非常快」</b>：动画位移写的是 {@code -100vw}，与画面实际宽度无关。
   *       现在用画面宽度做位移基准，并按"距离 ÷ 固定速度"算时长（见
   *       {@link danmakuDuration}），大窗小窗观感一致。</li>
   * </ol>
   */
  const [danmaku, setDanmaku] = useState<(DanmakuItem & { lane: number; duration: number })[]>([]);
  const danmakuLane = useRef(0);
  const danmakuBox = useRef<HTMLDivElement | null>(null);
  const [danmakuWidth, setDanmakuWidth] = useState(0);
  /**
   * ★镜像一份到 ref：订阅回调是在 LiveKit 事件里触发的，闭包里的 state 可能是旧值
   * （订阅 effect 的依赖只有 isRoom/phase，不会因为宽度变化重订阅）。
   */
  const danmakuWidthRef = useRef(0);
  useEffect(() => {
    danmakuWidthRef.current = danmakuWidth;
  }, [danmakuWidth]);

  /** 量画面宽度（弹幕容器的宽度≈主列宽度）。窗口拖动缩放时跟着更新。 */
  useEffect(() => {
    if (!isRoom || phase !== 'active') return;
    const el = danmakuBox.current;
    if (!el) return;
    const measure = () => {
      const w = el.clientWidth || el.parentElement?.clientWidth || 0;
      if (w > 0) setDanmakuWidth(w);
    };
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [isRoom, phase]);

  useEffect(() => {
    if (!isRoom || phase !== 'active') return;
    return subscribeDanmaku((item) => {
      // ★★自己发的那条永远上屏：本地回灌不经过房间 metadata 的同步时序。
      //    主持人关掉弹幕后，<b>别人的</b>不再上屏（发送端也已被按钮挡住，这里兜底）。
      if (!item.self && !getRoomSettings().danmaku) return;
      const duration = danmakuDuration(danmakuWidthRef.current, item);
      const lane = danmakuLane.current % 6;
      danmakuLane.current += 1;
      setDanmaku((prev) => [...prev.slice(-30), { ...item, lane, duration }]);
      // ★按这条自己的时长收尾（不再写死 9 秒，否则长弹幕还在飞就被删了）
      window.setTimeout(() => {
        setDanmaku((prev) => prev.filter((d) => d.id !== item.id));
      }, duration * 1000 + 400);
    });
  }, [isRoom, phase]);

  /**
   * ★会中文字消息列表（底部「聊天」按钮永远展开它）。
   *
   * <p>★订阅是常驻的、跟面板开不开无关：否则"关掉弹幕之后才打开聊天"的人
   * 只能看到打开之后的消息，等于刚才那几句从没存在过。
   * 弹幕消息也进这个列表（见 {@code subscribeMeetingChat} 的投递逻辑）。
   */
  const [chatMsgs, setChatMsgs] = useState<DanmakuItem[]>([]);
  const [chatOpen, setChatOpen] = useState(false);
  const [chatText, setChatText] = useState('');
  const [chatSending, setChatSending] = useState(false);
  const chatListRef = useRef<HTMLDivElement | null>(null);
  useEffect(() => {
    if (!isRoom || phase !== 'active') return;
    return subscribeMeetingChat((item) => {
      // ★只留最近 200 条：会开两小时、弹幕刷屏时，DOM 不该无限长
      setChatMsgs((prev) => [...prev.slice(-199), item]);
    });
  }, [isRoom, phase]);
  /** 有新消息就滚到底（飞书/微信的习惯：先看最新的）。 */
  useEffect(() => {
    const el = chatListRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [chatMsgs, chatOpen]);
  /**
   * ★发送会中消息（唯一的发送入口）。
   *
   * <p>用户 2026-11-07 原话：「不管弹幕开没开，点聊天都要弹出聊天消息列表」。
   * 所以这里只按弹幕开关决定<b>这条消息走哪个 topic</b>：
   * 开着走弹幕 topic（会飘屏，同时也会进列表，见 {@code sendDanmakuOn} 的回灌），
   * 关着走普通聊天 topic（只进列表）。
   */
  const submitChat = useCallback(async () => {
    const text = chatText.trim();
    if (!text || chatSending) return;
    setChatSending(true);
    try {
      const ok = settings.danmaku ? await sendDanmaku(text) : await sendMeetingChat(text);
      if (ok) setChatText('');
    } finally {
      setChatSending(false);
    }
  }, [chatSending, chatText, settings.danmaku]);

  /**
   * ★操作反馈（本地小提示，3.5 秒后自动消失）。
   *
   * <p>★必须给：举手/开麦这类动作<b>失败时界面上没有任何变化</b>，用户看到的就是
   * "点了没反应"，只能反复点。服务端拒绝（权限不足）与网络失败长得一模一样。
   */
  const [hint, setHint] = useState<string | null>(null);
  const hintTimer = useRef<number | null>(null);
  const showHint = useCallback((msg: string) => {
    setHint(msg);
    if (hintTimer.current) window.clearTimeout(hintTimer.current);
    hintTimer.current = window.setTimeout(() => setHint(null), 3_000);
  }, []);
  useEffect(() => () => {
    if (hintTimer.current) window.clearTimeout(hintTimer.current);
  }, []);

  /** 会议界面根节点 —— 独立窗口里它属于另一个 document，取监听目标要靠它。 */
  const rootRef = useRef<HTMLDivElement | null>(null);

  /**
   * ★★自动播放被拦时，用「任意一次用户手势」兜底开声音（用户 2026-11-09：
   * 「我手机上听不到声音」）。
   *
   * <p>只挂一个「点击开启声音」的横幅在手机上是不够的：
   * <ul>
   *   <li>用户可能压根没看见横幅（横幅在画面下方，手机上被底栏挤掉了）；</li>
   *   <li>他滑动屏幕、点参会人、点静音按钮时，浏览器其实已经把 AudioContext 放行了，
   *       我们却还在等那一次「正版」点击。</li>
   * </ul>
   * 所以监听到第一次 pointerdown / touchstart 就悄悄补一次 {@code retryAudio()}：
   * 成功就当无事发生（横幅由 AudioPlaybackStatusChanged 撤掉），失败也无副作用。
   *
   * <p>★监听到 {@code rootRef} 所属的 document 上（capture），不用全局 {@code document}：
   * 会议可能在独立窗口里，「本页」的 document 收不到那边的点击。
   */
  useEffect(() => {
    if (!audioBlocked || phase !== 'active') return;
    const doc = rootRef.current?.ownerDocument ?? document;
    let fired = false;
    const onGesture = () => {
      if (fired) return;
      fired = true;
      void retryAudio();
    };
    doc.addEventListener('pointerdown', onGesture, true);
    doc.addEventListener('touchstart', onGesture, true);
    return () => {
      doc.removeEventListener('pointerdown', onGesture, true);
      doc.removeEventListener('touchstart', onGesture, true);
    };
  }, [audioBlocked, phase, retryAudio]);

  /**
   * ★{@code notice} 是 store 里的一条<b>状态</b>，以前渲染在操作栏上方那整条横幅里、
   * 没有人清它 —— 用户截图里「已解除全员禁言」「云端录制已开始…」就那样一直挂着。
   *
   * <p>现在统一定时清空：界面上只留 3 秒（渲染成浮在操作栏上方的小 toast），
   * 然后回到无提示状态。下一次写入会重新触发这个 effect。
   */
  useEffect(() => {
    if (!notice) return;
    const t = window.setTimeout(() => clearNotice(), 3_000);
    return () => window.clearTimeout(t);
  }, [notice, clearNotice]);

  /** ★当前要显示的一条提示。本地 hint 优先（用户刚点过按钮，反馈比后台状态更相关）。 */
  const toast = hint ?? notice;

  /**
   * ★本机摄像头列表 + 当前设备（需求：「有多个摄像头的时候没法更换摄像头」）。
   *
   * <p>入会后与每次打开摄像头时各扫一次：设备插拔、以及"未授权时 label 是空串"这两个
   * 情况都要求重新枚举，否则用户看到的永远是「摄像头 1 / 摄像头 2」或者只有一个。
   */
  const [cameras, setCameras] = useState<CameraDevice[]>([]);
  const [cameraId, setCameraId] = useState('');
  const refreshCameras = useCallback(async () => {
    const list = await listCameras();
    setCameras(list);
    setCameraId(await activeCameraId());
  }, []);
  useEffect(() => {
    if (!isRoom || phase !== 'active') return;
    void refreshCameras();
  }, [isRoom, phase, cameraOn, refreshCameras]);

  const pickCamera = useCallback(
    async (deviceId: string) => {
      if (await switchCamera(deviceId)) {
        setCameraId(deviceId);
        showHint('已切换摄像头');
      } else {
        showHint('切换摄像头失败，请检查该设备是否被其他程序占用');
      }
    },
    [showHint],
  );

  /**
   * ★本机麦克风列表 + 当前设备（用户 2026-11-09：「要支持手机上的麦克风切换」）。
   *
   * <p>手机上插了蓝牙耳机 / 有线耳机、或平板带阵列麦时会有多个输入设备，
   * 之前只能在系统设置里切。打开麦克风时重扫一次：授权前后 label 不同，
   * 插拔耳机也要能立刻反映出来。
   */
  const [microphones, setMicrophones] = useState<CameraDevice[]>([]);
  const [micDeviceId, setMicDeviceId] = useState('');
  const refreshMicrophones = useCallback(async () => {
    setMicrophones(await listMicrophones());
    setMicDeviceId(await activeMicrophoneId());
  }, []);
  useEffect(() => {
    if (!isRoom || phase !== 'active') return;
    void refreshMicrophones();
  }, [isRoom, phase, micOn, refreshMicrophones]);

  const pickMicrophone = useCallback(
    async (deviceId: string) => {
      if (await switchMicrophone(deviceId)) {
        setMicDeviceId(deviceId);
        showHint('已切换麦克风');
      } else {
        showHint('切换麦克风失败，请检查该设备是否被其他程序占用');
      }
    },
    [showHint],
  );

  const toggleHandRaised = useCallback(async () => {
    // ★以"模块里的真实状态"为准而不是 state：独立窗口与本页两份界面共享同一个房间，
    //   只信本地 state 会在两边来回切时反过来。
    const next = !isHandRaised();
    if (await setHandRaised(next)) {
      setHandRaisedState(next);
      showHint(next ? '已举手，主持人能看到（再点一次放下）' : '已放下手');
    } else {
      showHint('举手失败：与会议的连接可能已断开，请稍后重试');
    }
  }, [showHint]);

  /** ★全员禁言且主持人没单独放行我 ⇒ 麦克风按钮置灰。 */
  const micLocked = isRoom && !amHost && settings.muteAll && !canSelfUnmute();

  /**
   * ★麦克风按钮：被全员禁言时<b>不发请求</b>，只给一句提示。
   *
   * <p>服务端已经把 microphone 从发布权限里摘掉了（见后端 {@code sourcesWithoutMicrophone}），
   * 这里再拦一层是为了"点了没反应"不要发生 —— 按钮本来也置灰了，
   * 但独立窗口/键盘操作仍可能触发。
   */
  const toggleMicChecked = useCallback(() => {
    if (micLocked) {
      showHint('主持人已全员禁言，需要他单独为你开麦');
      return;
    }
    void toggleMic();
  }, [micLocked, showHint, toggleMic]);

  /**
   * ★会中关标签页/刷新 ⇒ 浏览器原生确认；按返回 ⇒ 我们自己的确认框（取消一定生效）。
   *
   * <p>★独立窗口那份不注册：它跑在同一个 JS 世界，{@code window} 仍指向<b>主页面</b>的
   * window —— 两份都注册会在主页面压两条守卫记录、按一次返回弹两次确认。
   * 独立窗口被关掉走的是 {@code MeetingPopout} 的 pagehide 收尾。
   *
   * <p>确认离开后直接 {@code hangup()}：主持人退出本来就不等于散会（要不要结束会议由
   * {@code shouldAutoEndRoom} 按剩余人数判），这里不再叠一层「结束会议」的确认框。
   */
  useLeaveGuard(isRoom && phase === 'active' && !standalone, hangup);

  /** ★还原窗口时一并收起面板：小浮层里塞不下 300px 的侧栏，画面会被挤成一条。 */
  const toggleLarge = useCallback(() => {
    if (large) {
      setLarge(false);
      setPanelOpen(false);
    } else {
      setLarge(true);
    }
  }, [large]);

  /**
   * ★点"离开"的入口：主持人先问一句，其他人直接走。
   *
   * <p>★为什么主持人一定要问：直接退出会让"我以为散会了、其实会还开着"和
   * "我以为只是离开、结果把别人全踢了"两种事故同时发生。
   */
  const requestLeave = useCallback(() => {
    if (isRoom && amHost) {
      setConfirm({ kind: 'leave' });
      return;
    }
    void hangup();
  }, [amHost, hangup, isRoom]);

  /**
   * ★移出成员要二次确认：这是对别人的强制操作，会直接断开他的连接，
   * 误点一次就得重新邀请、重新入会。飞书同样有确认。
   */
  const askKick = useCallback((userId: string, name: string) => {
    setConfirm({ kind: 'kick', userId, name });
  }, []);

  // ★只订阅一次（幂等）：WS 邀请与 3007 事件都从这里进 store
  useEffect(() => {
    useCallStore.getState().init();
  }, []);

  // ★页面关闭/刷新前尽量退会，避免 LiveKit 里留下一个"幽灵参与者"（最多留到 emptyTimeout）
  // ★独立窗口那份不再注册：它跑在同一个 JS 世界，`window` 仍指向<b>主页面</b>的 window，
  //   两份都注册会在关闭主页面时把 hangup 打两遍（第二次是打给一个已经空了的房间）。
  // ★★为什么从 beforeunload 改成 pagehide：会中时 beforeunload 已经被
  //   {@link useLeaveGuard} 用来弹"确定要离开吗"了。如果这里同时挂断，
  //   用户在确认框上点「取消」、选择留在会议里，连接却已经被断开 —— 比不拦更糟。
  //   pagehide 只在页面**真的**要卸载时才触发，点取消不会走到这里。
  useEffect(() => {
    if (standalone) return;
    const onPageHide = () => {
      const st = useCallStore.getState();
      if (st.phase !== 'idle' && st.phase !== 'ended') void hangup();
    };
    window.addEventListener('pagehide', onPageHide);
    return () => window.removeEventListener('pagehide', onPageHide);
  }, [standalone, hangup]);

  const remoteRef = useCallback((el: HTMLVideoElement | null) => attachRemoteVideo(el), []);
  const localRef = useCallback((el: HTMLVideoElement | null) => attachLocalVideo(el), []);

  /**
   * ★★会议计时从<b>会议真实开始时刻</b>算，不是"我连上多久"（用户 2026-11-08）。
   *
   * <p>原来固定用 {@code connectedAt}：中途才进会的人看到的是"我刚坐下多久"，
   * 主持人自己刷新/重进一次也会被清零，而顶栏同时又写着「限时 2 小时」——
   * 两个数字对不上，用户完全无法判断这场会还剩多少时间。
   * 房间会议的 {@code meetingStartedAt} 来自服务端会议记录（{@code im_meeting.start_time}，
   * 与"到点自动结束"同一个基准）；1v1 通话没有会议记录，仍旧按接通的时刻算。
   *
   * <p>★这里**不能**用 useMemo：useTicker 每秒只触发一次重渲染，
   * 锚点与 phase 都不变，memo 会把第一次算出的 "0:00" 一直缓存下去
   * —— 表现是"通话正常、计时不走"。每次渲染直接算，代价只是一次减法与格式化。
   */
  const startedAtMs = call?.mode === 'room' ? call.meetingStartedAt : undefined;
  const durationAnchor =
    startedAtMs != null && startedAtMs > 0 ? startedAtMs : call?.connectedAt;
  const duration = durationAnchor
    ? formatCallDuration(Math.max(0, (Date.now() - durationAnchor) / 1000))
    : '0:00';
  /** ★录音时长沿用同一个 ticker：每秒随重渲染刷新，不需要额外的定时器。 */
  const recDuration = recording && recordingStartedAt
    ? formatCallDuration(Math.max(0, (Date.now() - recordingStartedAt) / 1000))
    : '0:00';

  /**
   * ★会议时长上限（服务端记录的 {@code planned_duration_sec}）。
   *
   * <p>★剩余时长必须从<b>会议记录的开始时刻</b>算，不能用本地 {@code connectedAt}：
   * 中途才进来的主持人会算出一个长得离谱的剩余时间。
   * 到点由服务端 {@code MeetingRecordPollTask} 自动结束（宽限 60 秒），
   * 这里只做展示 + 最后 10 分钟提醒。
   */
  const plannedSec = call?.mode === 'room' ? call.plannedDurationSec : undefined;
  const remainingSec =
    plannedSec != null && plannedSec > 0 && startedAtMs != null && startedAtMs > 0
      ? plannedSec - Math.max(0, Math.floor((Date.now() - startedAtMs) / 1000))
      : null;
  const limitWarn = remainingSec != null && remainingSec <= 600;
  const durationLimitText = plannedSec != null && plannedSec > 0 ? formatDurationLabel(plannedSec) : undefined;
  const remainingText =
    remainingSec == null
      ? undefined
      : remainingSec <= 0
        ? '已到时长上限'
        : formatCallDuration(remainingSec);
  const limitText =
    remainingText == null
      ? undefined
      : remainingSec != null && remainingSec > 0 && limitWarn
        ? `剩余 ${remainingText}`
        : remainingSec != null && remainingSec <= 0
          ? '已到时长上限'
          : `限时 ${durationLimitText}`;

  if (phase === 'idle' || !call) return null;

  // ---------------------------------------------------------------- 已结束
  if (phase === 'ended') {
    return (
      <div className="call-ended" role="status">
        <div className="call-ended-icon">
          <IconPhoneOff size={18} />
        </div>
        <div className="call-ended-body">
          <div className="call-ended-title">{ended?.title ?? call.convTitle}</div>
          <div className="call-ended-detail">{ended?.detail ?? '通话已结束'}</div>
          {recordingEgressId != null && (
            <div className="call-ended-detail">云端录制正在生成，请稍候…</div>
          )}
          {/*
            ★只给「录制已生成 + 打开录制」这个用户能理解的结论（2026-11-07 用户截图）：
            不需要把对象存储路径 {@code im-recordings/...mp4} 当标题糊在脸上 ——
            那是运维信息，不是用户能用的信息。
          */}
          {recordingFile && (
            <div className="call-ended-detail">
              云端录制已生成
              {recordingFile.url && (
                <>
                  {' '}
                  <a href={recordingFile.url} target="_blank" rel="noreferrer">打开录制</a>
                </>
              )}
            </div>
          )}
        </div>
        <button type="button" className="call-ended-close" title="关闭" onClick={clearEnded}>
          <IconClose size={14} />
        </button>
      </div>
    );
  }

  /**
   * ★「结束会议 / 仅退出 / 移出成员」确认框（自绘，不依赖 antd）。
   *
   * <p>★放在这里（而不是某个分支里面）是为了最小化悬浮条也能弹：
   * 用户常在最小化状态点那个红色按钮，那条路径同样是"离开会议"。
   * ★独立窗口那份也用它：见文件头的 antd cssinjs 说明。
   */
  const confirmDialog = confirm ? (
    <div className="call-confirm-mask" role="dialog" aria-modal="true">
      <div className="call-confirm">
        <div className="call-confirm-title">{confirm.kind === 'leave' ? '离开会议' : '移出会议'}</div>
        <div className="call-confirm-text">
          {confirm.kind === 'leave' ? (
            <>
              <p>你是本次会议的主持人（会议号 {formatMeetingId(call.roomName)}）。</p>
              <p>
                <strong>结束会议</strong>：所有人退出，云端录制同步停止。
              </p>
              <p>
                <strong>仅退出</strong>：你离开，会议继续进行，其他人不受影响。
              </p>
            </>
          ) : (
            <p>确定将「{confirm.name}」移出会议吗？对方会被立即断开连接。</p>
          )}
        </div>
        <div className="call-confirm-actions">
          <button type="button" className="call-confirm-btn" onClick={() => setConfirm(null)}>
            {confirm.kind === 'leave' ? '继续开会' : '取消'}
          </button>
          {confirm.kind === 'leave' && (
            <button
              type="button"
              className="call-confirm-btn"
              onClick={() => {
                setConfirm(null);
                // ★keepRoom：会留着，别人还能继续开、我也能再进来
                void hangup({ keepRoom: true });
              }}
            >
              仅退出
            </button>
          )}
          <button
            type="button"
            className="call-confirm-btn is-danger-solid"
            onClick={() => {
              if (confirm.kind === 'leave') {
                setConfirm(null);
                void endRoomMeeting();
                return;
              }
              const target = confirm;
              setConfirm(null);
              void kickParticipant(target.userId);
            }}
          >
            {confirm.kind === 'leave' ? '结束会议' : '移出'}
          </button>
        </div>
      </div>
    </div>
  ) : null;

  /**
   * ★本页那份退化成一条胶囊：面板已经在独立窗口里，这里再画一遍会出现<b>两份</b>控件，
   * 两边都能点、状态却看着不同步（虽然其实是同一个 store）。留一个"收回本页"入口即可。
   */
  if (popout && !standalone) {
    return (
      <>
        {confirmDialog}
        <div className="call-popout-chip" role="status">
          <span className="call-popout-dot" />
          <div className="call-popout-main">
            <div className="call-popout-title">会议在新窗口中</div>
            <div className="call-popout-sub">
              {call.convTitle} · {phase === 'active' ? duration : '正在进入会议…'}
            </div>
          </div>
          <button type="button" className="call-popout-btn" onClick={() => setPopout(false)}>
            收回本页
          </button>
        </div>
      </>
    );
  }

  // ---------------------------------------------------------------- 最小化
  if (minimized) {
    return (
      <>
        {confirmDialog}
        <div className={`call-mini${phase === 'incoming' ? ' call-mini-ringing' : ''}`}>
          <button type="button" className="call-mini-main" onClick={() => setMinimized(false)}>
            {avatarNode(call.convTitle, call.peerAvatar, false)}
            <span className="call-mini-text">
              <span className="call-mini-title">{call.convTitle}</span>
              <span className="call-mini-sub">
                {phase === 'incoming'
                  ? `${voipMediaLabel(call.mediaType)}邀请`
                  : phase === 'active'
                    ? recording
                      ? `${duration} · 录制中`
                      : duration
                    : '等待接听…'}
              </span>
            </span>
          </button>
          {phase === 'incoming' ? (
            <div className="call-mini-actions">
              <button type="button" className="call-round call-round-decline" title="拒绝" onClick={decline}>
                <IconPhoneOff size={16} />
              </button>
              <button type="button" className="call-round call-round-accept" title="接听" onClick={() => void accept()}>
                {isVideo ? <IconVideo size={16} /> : <IconPhone size={16} />}
              </button>
            </div>
          ) : (
            <button
              type="button"
              className="call-round call-round-decline"
              title={isRoom ? '离开会议' : '挂断'}
              onClick={requestLeave}
            >
              <IconPhoneOff size={16} />
            </button>
          )}
        </div>
      </>
    );
  }

  // ---------------------------------------------------------------- 来电
  if (phase === 'incoming') {
    return (
      <div className="call-layer">
        <div className="call-window call-window-incoming">
          <div className={`call-hero${isVideo ? ' call-hero-video' : ''}`}>
            {avatarNode(call.convTitle, call.peerAvatar, true)}
            <div className="call-name">{call.convTitle}</div>
            <div className="call-sub">
              {call.peerName && call.peerName !== call.convTitle ? `${call.peerName} · ` : ''}
              {voipMediaLabel(call.mediaType)}邀请
            </div>
          </div>
          <div className="call-actions">
            <div className="call-action">
              <button type="button" className="call-round call-round-decline" title="拒绝" onClick={decline}>
                <IconPhoneOff size={20} />
              </button>
              <span className="call-action-label">拒绝</span>
            </div>
            <div className="call-action">
              <button type="button" className="call-round call-round-accept" title="接听" onClick={() => void accept()}>
                {isVideo ? <IconVideo size={20} /> : <IconPhone size={20} />}
              </button>
              <span className="call-action-label">接听</span>
            </div>
            <div className="call-action">
              <button type="button" className="call-round call-round-ghost" title="最小化" onClick={() => setMinimized(true)}>
                <IconChevronDownMini />
              </button>
              <span className="call-action-label">稍后</span>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // ---------------------------------------------------------------- 会议（多人）
  /**
   * ★★房间会议走这一套布局（用户明确要求的三个区域）：
   * <ol>
   *   <li>顶部：参会人<b>横向列表</b>（缩略画面 + 麦克风状态 + 说话高亮）；</li>
   *   <li>中间：<b>谁在说话展示谁</b>，开了视频就展示视频；</li>
   *   <li>右侧：<b>参会人管理列表</b>（可移出 / 静音 / 关闭侧栏）。</li>
   * </ol>
   *
   * <p>★与游客页（{@code GuestMeetingPage}）共用 {@link MeetingRoomView} —— 同一个会议里
   * "登录用户看到的"和"游客看到的"必须是同一套界面，否则两个人对着屏幕说的不是一回事。
   *
   * <p>★1v1 通话**不走这里**：它没有"参会人列表"，自己那块小浮层才是对的布局。
   */
  if (isRoom && phase === 'active') {
    /**
     * ★顶栏的补充状态（时长单独走 {@code elapsedText}，这里只说"时长之外的事"）。
     *
     * <p>以前这三段是拼在一起的 `00:11 · 你正在共享屏幕`，顶栏有了独立的计时位之后
     * 再拼一遍就会显示成"00:11 · 00:11"。
     */
    const meetingStatus =
      remoteCount === 0 ? '等待其他人加入…' : screenOn ? '你正在共享屏幕' : '';
    /**
     * ★统一入会链接 / 邀请文案：顶栏分享图标与会议信息面板共用同一份，
     * 不各自拼一遍 —— 两边拼法一旦分叉，同一个人会收到两条不同的链接。
     */
    // ★★链接里带的是分享 slug，不是会议号：9 位会议号只有 10^9 种可能，
    //   当作免登录入场的凭证太弱（允许游客加入的会议尤其）。老房间没有 slug
    //   （metadata 里缺这个键）才回退会议号，服务端两种值都认。
    const inviteUrl =
      buildInviteUrl(window.location.href, shareKeyOf(settings.shareSlug, call.roomName)) || '';
    const inviteText = buildMeetingInviteText({
      inviter: myName,
      title: call.title || call.convTitle,
      roomName: call.roomName,
      url: inviteUrl,
    });
    /**
     * ★identity → 聚合行。
     *
     * <p>不能只映射聚合行自带的 identity：同一账号多端时聚合行只保留<b>第一个席位</b>的
     * identity，其它席位的格子在这里取不到行，管理按钮会整块消失（用户会以为"漏了人"）。
     * 先按 userId 找到聚合行，再把该用户的所有席位 identity 都指过去。
     */
    const rowByKey = new Map(rows.map((r) => [r.key, r]));
    const rowByIdentity = new Map<string, (typeof rows)[number]>();
    for (const p of participants) {
      const uid = userIdOf(p);
      const row = uid == null ? rowByKey.get(`i:${p.identity}`) : rowByKey.get(`u:${uid}`);
      if (row) rowByIdentity.set(p.identity, row);
    }
    return (
      <>
        {confirmDialog}
        <div ref={rootRef} className={`call-layer${standalone ? ' call-layer-popout' : ''}`}>
          <div
            className={`call-window call-window-active call-window-video call-window-large${standalone ? ' call-window-popout' : ''}`}
          >
            {/*
              ★★headExtra 没有内容时必须传 undefined：以前恒传一个 Fragment（truthy），
              MeetingRoomView 就会渲染一层带白色底色的空容器 ——
              截图里「会议信息下面的那个白块」就是它。
            */}
            {/* ★「在新窗口中打开 / 最小化」从舞台右下角挪到顶栏（用户 2026-11-07 截图）。
                原来浮在画面上的一颗白色小胶囊里，既压住画面内容，又和「布局」隔着半个屏，
                看上去像是两个不相干的东西。现在与布局按钮并排。 */}
            <MeetingRoomView
              peers={roomPeers}
              title={call.convTitle}
              statusText={meetingStatus}
              elapsedText={duration}
              limitText={limitText}
              limitWarn={limitWarn}
              roomNo={call.roomName}
              onOpenInfo={() => setInfoOpen(true)}
              onShare={() => {
                // ★顶栏那个图标是「分享至会话」：发一条聊天消息，而不是复制链接。
                //   复制链接仍然在「会议信息」面板里（那里才是"我要自己粘贴到别处"的入口）。
                setInfoOpen(false);
                setInviteOpen(false);
                setShareOpen(true);
              }}
              micOn={micOn}
              cameraOn={cameraOn}
              screenOn={screenOn}
              onToggleMic={toggleMicChecked}
              onToggleCam={() => void toggleCamera()}
              onToggleScreen={() => void toggleScreenShare()}
              cameras={cameras}
              activeCameraId={cameraId}
              onPickCamera={(deviceId) => void pickCamera(deviceId)}
              microphones={microphones}
              activeMicId={micDeviceId}
              onPickMic={(deviceId) => void pickMicrophone(deviceId)}
              onLeave={requestLeave}
              panelOpen={panelOpen}
              onPanelOpenChange={setPanelOpen}
              emptyPanelText="正在获取参会人…"
              micLocked={micLocked}
              micLockedHint="主持人已全员禁言，需要他单独为你开麦"
              overlay={
                <>
                  {/* 弹幕飘屏：一条一条从右往左滚，按 lane 分行。
                      ★--meet-stage-w 是"这条跑道有多宽"：动画末态与飞行时长都以它为基准。 */}
                  <div
                    className="meet-danmaku"
                    ref={danmakuBox}
                    style={
                      danmakuWidth > 0
                        ? ({ '--meet-stage-w': `${danmakuWidth}px` } as CSSProperties)
                        : undefined
                    }
                  >
                    {danmaku.map((d) => (
                      <span
                        key={d.id}
                        className={`meet-danmaku-item${d.self ? ' is-self' : ''}`}
                        style={{ top: `${6 + d.lane * 13}%`, animationDuration: `${d.duration}s` }}
                      >
                        <b>{d.name}</b>
                        {/* ★长弹幕在这里就截断（50 字 + 省略号），不靠 CSS：
                            容器是 inline-flex，text-overflow 对匿名 flex item 不可靠，
                            用户截图里那条就是"戛然而止"。全文仍在聊天面板。 */}
                        <span className="meet-danmaku-text">{truncateDanmakuText(d.text)}</span>
                      </span>
                    ))}
                  </div>
                  {/*
                    ★★会中文字消息列表：**不管弹幕开没开**，点底部「聊天」都展开它
                    （用户 2026-11-07 原话）。弹幕开关只决定"发出去的消息要不要飘屏"，
                    不再决定这个面板出不出现 —— 之前关掉弹幕才给看列表，等于
                    "弹幕开着就看不到别人说过什么"，消息全丢了。
                  */}
                  {chatOpen && (
                    <div className="meet-chat-panel">
                      <div className="meet-chat-head">
                        <span className="meet-chat-title">会中聊天</span>
                        {settings.danmaku && (
                          <span className="meet-chat-mode" title="弹幕开关已开：这里发的消息也会飘屏">
                            弹幕
                          </span>
                        )}
                        <button
                          type="button"
                          className="meet-chat-close"
                          title="收起聊天"
                          onClick={() => setChatOpen(false)}
                        >
                          <IconClose size={14} />
                        </button>
                      </div>
                      <div className="meet-chat-list" ref={chatListRef}>
                        {chatMsgs.length === 0 ? (
                          <div className="meet-chat-empty">还没有消息，说点什么吧</div>
                        ) : (
                          chatMsgs.map((m) => (
                            <div
                              key={m.id}
                              className={`meet-chat-item${m.self ? ' is-self' : ''}`}
                            >
                              <div className="meet-chat-name">{m.self ? '我' : m.name}</div>
                              <div className="meet-chat-text">{m.text}</div>
                            </div>
                          ))
                        )}
                      </div>
                      <div className="meet-chat-input-row">
                        <input
                          className="meet-chat-input"
                          value={chatText}
                          maxLength={120}
                          placeholder={
                            settings.danmaku
                              ? '发弹幕…（回车发送，会飘屏）'
                              : '发消息…（回车发送，仅会中可见）'
                          }
                          onChange={(e) => setChatText(e.target.value)}
                          onKeyDown={(e) => {
                            // ★中文输入法选词时的回车不能当发送
                            if (e.key === 'Enter' && !e.nativeEvent.isComposing) {
                              e.preventDefault();
                              void submitChat();
                            } else if (e.key === 'Escape') {
                              setChatOpen(false);
                            }
                          }}
                        />
                        <button
                          type="button"
                          className="meet-chat-send"
                          title="发送"
                          disabled={!chatText.trim() || chatSending}
                          onClick={() => void submitChat()}
                        >
                          <IconSend size={15} />
                        </button>
                      </div>
                    </div>
                  )}
                </>
              }
              headExtra={
                popoutBlocked || recording ? (
                  <>
                    {popoutBlocked && (
                      <div className="call-popout-tip">浏览器拦下了独立窗口，会议仍在本页</div>
                    )}
                    {recording && (
                      <div className="call-rec" title="云端录制进行中，停止后会自动生成录制文件">
                        <span className="call-rec-dot" />
                        {recordingStatus === 'EGRESS_STARTING' ? 'REC 启动中…' : `REC ${recDuration}`}
                      </div>
                    )}
                  </>
                ) : undefined
              }
              topbarExtra={
                standalone ? (
                  <button
                    type="button"
                    className="call-minimize"
                    title="收回本页（会议继续，窗口会关闭）"
                    onClick={() => setPopout(false)}
                  >
                    <IconDockMini />
                  </button>
                ) : (
                  <>
                    <button
                      type="button"
                      className="call-minimize"
                      title="在新窗口中打开"
                      onClick={openPopout}
                    >
                      <IconPopoutMini />
                    </button>
                    <button
                      type="button"
                      className="call-minimize"
                      title="最小化"
                      onClick={() => setMinimized(true)}
                    >
                      <IconChevronDownMini />
                    </button>
                  </>
                )
              }
              toast={toast}
              panelExtra={
                amHost ? (
                  <div className="call-panel-actions">
                    {/*
                      ★「全员禁言」与旧的「全员静音」不是一个东西：
                      静音只把当前音轨 muted，对方能自己点回来；禁言会把
                      microphone 从发布权限里摘掉，谁都没法自己开麦 ——
                      所以这里是开关，不是一次性按钮。
                    */}
                    <button
                      type="button"
                      className={`call-panel-action${settings.muteAll ? ' is-on' : ''}`}
                      title={
                        settings.muteAll
                          ? '解除全员禁言（所有人可以自己开麦）'
                          : '全员禁言：除主持人外都不能开麦，可在下方单独放行某人'
                      }
                      onClick={() => void updateRoomSettings({ muteAll: !settings.muteAll })}
                    >
                      <IconMicOff size={14} />
                      {settings.muteAll ? '解除全员禁言' : '全员禁言'}
                    </button>
                    <button
                      type="button"
                      className={`call-panel-action${settings.danmaku ? ' is-on' : ''}`}
                      title={settings.danmaku ? '关闭弹幕：会中不再显示，也不能发送' : '开启弹幕'}
                      onClick={() => void updateRoomSettings({ danmaku: !settings.danmaku })}
                    >
                      <IconDanmaku size={14} />
                      {settings.danmaku ? '弹幕：开' : '弹幕：关'}
                    </button>
                    {/*
                      ★★「全员静音」常驻且<b>始终可点</b>（用户 2026-11-07：「无法点击操作」）。
                      旧实现用客户端能算出的 {@code unmutedCount} 做 disabled 判据，而那个数
                      排除了没有 userId 的游客 —— 只有游客在线时恒为 0，按钮永远是灰的。
                      现在由服务端按席位执行（含游客），客户端没有可靠的"还剩几个人没静音"
                      的判断依据，就不该假装知道：点击后服务端返回实际静音数量。
                      注意它和「全员禁言」不是一回事：静音只压当前音轨，对方能自己点回来。
                    */}
                    <button
                      type="button"
                      className="call-panel-action"
                      title="把除自己外所有人的麦克风静音（不改变开麦权限，对方可自行开麦；游客同样生效）"
                      onClick={() => void muteAll()}
                    >
                      <IconMicOn size={14} />
                      全员静音
                    </button>
                  </div>
                ) : null
              }
              renderPeerOps={(p) => {
                const row = rowByIdentity.get(p.key);
                if (!row || !canManageParticipant(amHost, row)) return null;
                /**
                 * ★目标标识：登录成员是 userId（服务端扇出全部平台席位），
                 * 游客没有 userId，用 identity 只作用于这一个席位。
                 */
                const target = row.target;
                return (
                  <>
                    {/*
                      ★全员禁言期间，轨道级"取消静音"是无效的（对方的麦根本发不出来）——
                      这时按钮语义必须是"放行/收回发布权限"，否则主持人点了没反应。
                    */}
                    {settings.muteAll ? (
                      /*
                        ★★按"权限"而不是"音轨静音"判断放行状态。
                        row.micMuted 在"已放行但对方还没开麦"时仍然是 true，
                        用它切换会永远重复放行、收不回来 —— 这就是
                        「全员禁言时主持人无法操作部分开麦」的根因。
                      */
                      <button
                        type="button"
                        className={`call-person-op${row.micAllowed ? ' is-danger' : ''}`}
                        aria-label={row.micAllowed ? '收回发言' : '放行发言'}
                        title={
                          row.micAllowed
                            ? '点击收回发言：收回该成员的发言权限（他会被立刻闭麦）'
                            : '点击放行发言：放行后该成员可以自己开麦'
                        }
                        onClick={() => void setParticipantMicAllowed(target, !row.micAllowed)}
                      >
                        {/* ★图标=当前状态（能说话=开麦图标），文字=点击后的动作（用户 2026-11-09：「图标静音与未静音用反了」）。 */}
                        {row.micAllowed ? <IconMicOn size={14} /> : <IconMicOff size={14} />}
                      </button>
                    ) : (
                      <button
                        type="button"
                        className={`call-person-op${row.micMuted ? '' : ' is-danger'}`}
                        aria-label={row.micMuted ? '取消静音' : '静音'}
                        title={row.micMuted ? '点击取消静音' : '点击静音'}
                        onClick={() => void muteParticipant(target, !row.micMuted)}
                      >
                        {/*
                          ★图标画的是「当前状态」，不是「点击后会发生什么」——两者反过来正是
                          用户 2026-11-09 指出的问题：已静音的人却显示开麦图标。
                          现在：已静音 → 斜杠麦 / 未静音 → 正常麦；动作靠 hover 提示说明。
                        */}
                        {row.micMuted ? <IconMicOff size={14} /> : <IconMicOn size={14} />}
                      </button>
                    )}
                    {/*
                      ★图标按钮 + hover 提示（用户 2026-11-09：「这些直接用操作图标，鼠标放上去展示提示文字」）。
                      上一版为了"找得到移出"给按钮加了文字，把 300px 的面板挤得很窄；
                      现在统一成正方形图标，语义靠 title/aria-label 兜住。
                    */}
                    <button
                      type="button"
                      className="call-person-op is-danger"
                      aria-label="移出会议"
                      title="移出会议"
                      onClick={() => askKick(target, row.name)}
                    >
                      <IconPhoneOff size={14} />
                    </button>
                  </>
                );
              }}
              /* ★主持人不再挂说明文案（用户 2026-11-07 明确要求删掉）。
                 那几句话把"按钮就在眼前"的操作又解释了一遍，面板底部长期被占一行；
                 非主持人的两句仍然保留 —— 它们说的是"你现在为什么不能说话"。 */
              panelFoot={
                amHost
                  ? null
                  : settings.muteAll
                    ? '主持人已全员禁言，点「举手」让他看到你。'
                    : '等待主持人管理会议。'
              }
              controlsExtra={
                <>
                  {/*
                    ★邀请对<b>所有人</b>可见，不限主持人：会中"把同事拉进来"是常态操作，
                    他拉进来的人在参会人列表里一样能看见（不是权限动作）。
                  */}
                  <div className="call-control">
                    <button
                      type="button"
                      className="call-round"
                      title="从我的联系人里邀请人加入这场会议"
                      onClick={() => setInviteOpen(true)}
                    >
                      <IconUsersPlus size={19} />
                    </button>
                    <span className="call-control-label">邀请</span>
                  </div>
                  {/*
                    ★举手：不占服务端接口，走 LiveKit participant attributes（见 setHandRaised）。
                    举手后所有人在缩略图/宫格/参会人面板里都能看到，主持人据此开麦。
                  */}
                  <div className="call-control">
                    <button
                      type="button"
                      className={`call-round${handRaised ? ' is-on' : ''}`}
                      title={handRaised ? '放下手' : '举手发言（主持人和参会人都能看到）'}
                      onClick={() => void toggleHandRaised()}
                    >
                      <IconHand size={19} />
                    </button>
                    <span className="call-control-label">{handRaised ? '已举手' : '举手'}</span>
                  </div>
                  {/*
                    ★★一个入口：**不管弹幕开没开，点「聊天」都展开消息列表**
                    （用户 2026-11-07 原话）。弹幕开关只决定发送后要不要飘屏，
                    不再把入口拆成两种形态 —— 拆了之后弹幕开着就永远看不到消息记录。
                  */}
                  <div className="call-control">
                    <button
                      type="button"
                      className={`call-round${chatOpen ? ' is-on' : ''}`}
                      title={
                        settings.danmaku
                          ? '展开会中聊天（弹幕开关已开，发送的消息会飘屏）'
                          : '展开会中文字消息列表'
                      }
                      onClick={() => setChatOpen((v) => !v)}
                    >
                      <IconChat size={19} />
                    </button>
                    <span className="call-control-label">聊天</span>
                  </div>
                  {amHost ? (
                  <div className="call-control">
                    <button
                      type="button"
                      className={`call-round${recording ? ' is-rec' : ''}`}
                      title={
                        recordingBusy
                          ? '正在处理录制请求…'
                          : recording
                            ? '停止录制'
                            : '开始云端录制'
                      }
                      disabled={recordingBusy}
                      onClick={() => void toggleRecording()}
                    >
                      {recording ? <IconStop size={19} /> : <IconRecord size={19} />}
                    </button>
                    <span className="call-control-label">
                      {recordingBusy ? '处理中' : recording ? '停止录制' : '录制'}
                    </span>
                  </div>
                  ) : null}
                </>
              }
              endControl={
                amHost ? (
                  <div className="call-control">
                    <button
                      type="button"
                      className="call-round call-round-end"
                      title="结束会议（所有人退出，并停止云端录制）"
                      onClick={() => setConfirm({ kind: 'leave' })}
                    >
                      <IconStop size={19} />
                    </button>
                    <span className="call-control-label">结束会议</span>
                  </div>
                ) : null
              }
              banner={
                <>
                  {audioBlocked && (
                    <div className="call-banner">
                      浏览器拦截了自动播放，
                      <button type="button" className="call-banner-btn" onClick={() => void retryAudio()}>
                        点击开启声音
                      </button>
                    </div>
                  )}
                  {/*
                    ★notice / hint 已改成 toast（见 MeetingRoomView 的 toast 属性），
                    这里只留两类<b>需要用户动手</b>的横幅：
                    · audioBlocked —— 有一个"点击开启声音"的按钮；
                    · recordingFile —— 有一个"打开录制"的文件链接。
                    纯提示常驻在操作栏上方只会变成视觉噪音（用户截图）。
                  */}
                  {/* ★只说「录制已生成」，不暴露对象存储路径（用户 2026-11-07 要求）。 */}
                  {recordingFile && (
                    <div className="call-banner call-banner-file">
                      <span className="call-banner-file-name">云端录制已生成</span>
                      {recordingFile.url ? (
                        <a className="call-banner-btn" href={recordingFile.url} target="_blank" rel="noreferrer">
                          打开录制
                        </a>
                      ) : (
                        <span className="call-banner-btn">录制已生成</span>
                      )}
                    </div>
                  )}
                </>
              }
            />
          </div>
        </div>
        {/*
          ★★面板挂在浮层<b>内容层</b>之上（不是 call-window 内部）：它要盖住整个会议画面，
          并且在独立窗口里也能盖住 —— 那一份的 call-window 是铺满窗口的。
        */}
        {infoOpen && (
          <MeetingInfoPanel
            title={call.title || call.convTitle}
            roomNo={call.roomName}
            inviteUrl={inviteUrl}
            inviteText={inviteText}
            startedAt={call.meetingStartedAt ?? call.startedAt}
            elapsedText={duration}
            durationLimitText={durationLimitText}
            remainingText={remainingText}
            remainingWarn={limitWarn}
            people={roomPeers.length}
            onInvite={() => {
              // ★从信息面板点邀请 ⇒ 关掉信息面板再开邀请面板：两个浮层叠着会互相盖住。
              setInfoOpen(false);
              setInviteOpen(true);
            }}
            onClose={() => setInfoOpen(false)}
          />
        )}
        {inviteOpen && (
          <MeetingInvitePanel
            roomName={call.roomName}
            title={call.title || call.convTitle}
            mediaType={call.mediaType}
            excludeUserIds={inMeetingUserIds}
            onClose={() => setInviteOpen(false)}
          />
        )}
        {shareOpen && (
          <MeetingSharePanel
            title={call.title || call.convTitle}
            roomName={call.roomName}
            inviteUrl={inviteUrl}
            inviter={myName}
            onClose={() => setShareOpen(false)}
          />
        )}
      </>
    );
  }

  // ---------------------------------------------------------------- 呼出 / 通话中
  /**
   * ★★远端画面区必须按"有没有轨道"决定**是否挂载**，而不是只决定可不可见。
   *
   * <p>原来的判据 {@code isVideo && phase==='active' && remoteCount>0} 在**语音通话**里
   * 恒为假 —— 于是浮层根本不渲染 {@code <video>}，{@code attachRemoteVideo} 收到 null，
   * 远端共享上来的屏幕轨道<b>没有任何元素可挂</b>。表现就是"我点了共享，对方什么也看不到"。
   * 所以：语音通话里只要远端开始共享，也要把画面容器挂出来。
   */
  const showScreen = remoteScreenOn;
  /** ★远端摄像头不再受"发起时是不是视频通话"限制：语音通话里对方也能中途开视频。 */
  const showRemoteCamera = remoteCameraOn && phase === 'active';
  /** 元素是否存在（挂载）。 */
  const mountRemote = isVideo || remoteScreenOn || remoteCameraOn;
  /** 元素是否可见（有画面可看，屏幕共享优先）。 */
  const showRemote = showScreen || showRemoteCamera;
  /** 本地有没有画面 —— 决定"谁占主屏"能不能切。 */
  const localVideoOn = cameraOn || screenOn;
  const canSwap = phase === 'active' && localVideoOn;
  /** ★语音通话中途开了视频/共享，也要用大画面布局。 */
  const videoLayout = isVideo || cameraOn || remoteCameraOn || remoteScreenOn;
  const swapped = mainView === 'local' && canSwap;
  // ★共享时也要保留计时：用户常在共享过程中确认"这通电话打了多久"
  const statusText = showScreen
    ? `对方正在共享屏幕 · ${duration}`
    : phase === 'active'
      ? remoteCount === 0
        ? isRoom
          ? '等待其他人加入…'
          : '等待对方加入…'
        : screenOn
          ? `${duration} · 你正在共享屏幕`
          : duration
      : phase === 'connecting'
        ? isRoom
          ? '正在进入会议…'
          : '正在接通…'
        : '正在等待对方接听…';

  return (
    <>
      {confirmDialog}
      <div
        ref={rootRef}
        className={`call-layer${phase === 'outgoing' ? ' call-layer-outgoing' : ''}${standalone ? ' call-layer-popout' : ''}`}
      >
      <div
        className={`call-window call-window-active${videoLayout ? ' call-window-video' : ''}${showScreen ? ' call-window-screen' : ''}${isRoom && largeUi ? ' call-window-large' : ''}${standalone ? ' call-window-popout' : ''}`}
      >
        {/* ★大窗口是"画面 + 右侧参会人面板"两栏；小浮层里只有一个画面栏。
            用同一個 call-body 包住，样式能自然退化，不必为大小两套 DOM。 */}
        <div className="call-body">
        <div
          className={`call-stage${showScreen ? ' call-stage-screen' : ''}${swapped ? ' call-stage-swap' : ''}`}
        >
          {mountRemote && (
            <video
              ref={remoteRef}
              className={`call-remote-video${showRemote ? '' : ' is-hidden'}${showScreen ? ' is-screen' : ''}`}
              autoPlay
              playsInline
            />
          )}
          {/* ★主舞台给"自己"时，对方没有画面就在角落留一个头像位，而不是空白 */}
          {!showRemote && (
            <div className={`call-stage-placeholder${swapped ? ' call-stage-placeholder-pip' : ''}`}>
              {avatarNode(call.convTitle, call.peerAvatar, !swapped)}
            </div>
          )}
          {/* ★呼出阶段也显示自己的画面（飞书同款）：视频通话在响铃时就能看到自己的预览，
              否则用户会以为摄像头没开。★必须 muted —— 不然自己的麦克风会回授成啸叫。
              语音通话里自己开摄像头/共享屏幕时才出这块（可作为主屏或角落画中画）。 */}
          {localVideoOn && (
            <video
              ref={localRef}
              className={`call-local-video${swapped && !cameraOn ? ' is-screen' : ''}`}
              autoPlay
              playsInline
              muted
            />
          )}

          <div className="call-stage-head">
            <div className="call-stage-name">{call.convTitle}</div>
            <div className="call-stage-status">{statusText}</div>
            {/* ★会议号必须能在会中看到：用户常常是"进来了才想起来要告诉别人号"。
                复制走 lib/clipboard（101 是明文 http，navigator.clipboard 不存在）。 */}
            {isRoom && (
              <button
                type="button"
                className="call-room-no"
                title="复制会议号"
                onClick={(e) => {
                  // ★doc 必须是"按钮所在的文档"：独立窗口里与本页不是同一个 document
                  void copyText(call.roomName, undefined, e.currentTarget.ownerDocument).then((ok) => {
                    setNoCopied(ok ? 'ok' : 'fail');
                    window.setTimeout(() => setNoCopied('idle'), 2000);
                  });
                }}
              >
                <span className="call-room-no-label">会议号</span>
                <span className="call-room-no-value">{formatMeetingId(call.roomName)}</span>
                <span className={`call-room-no-action${noCopied === 'fail' ? ' is-fail' : ''}`}>
                  {noCopied === 'ok' ? '已复制' : noCopied === 'fail' ? '复制失败' : '复制'}
                </span>
              </button>
            )}
            {/* ★★邀请：一条链接、一段飞书同款的说明（主题 / 会议 ID / 链接）。
                ★链接里带 `?meeting=会议号`，见 lib/meetingLink.ts。
                ★即使这场会没开放游客也照样能复制 —— 对方会被要求登录，登录成功后自动回到这里。 */}
            {isRoom && (
              <button
                type="button"
                className="call-room-no call-room-link"
                title="复制邀请信息（会议主题 / 会议 ID / 会议链接）"
                onClick={(e) => {
                  const link = buildInviteUrl(
                    window.location.href,
                    shareKeyOf(settings.shareSlug, call.roomName),
                  );
                  if (!link) return;
                  const text = buildMeetingInviteText({
                    inviter: myName,
                    title: call.convTitle,
                    roomName: call.roomName,
                    url: link,
                  });
                  // ★doc 同会议号：独立窗口里必须把按钮所在文档传下去
                  void copyText(text, undefined, e.currentTarget.ownerDocument).then((ok) => {
                    setLinkCopied(ok ? 'ok' : 'fail');
                    window.setTimeout(() => setLinkCopied('idle'), 2000);
                  });
                }}
              >
                <span className="call-room-no-label">邀请链接</span>
                <span className={`call-room-no-action${linkCopied === 'fail' ? ' is-fail' : ''}`}>
                  {linkCopied === 'ok' ? '已复制' : linkCopied === 'fail' ? '复制失败' : '复制'}
                </span>
              </button>
            )}
            {popoutBlocked && (
              <div className="call-popout-tip">浏览器拦下了独立窗口，会议仍在本页</div>
            )}
            {recording && (
              <div className="call-rec" title="云端录制进行中，停止后会自动生成录制文件">
                <span className="call-rec-dot" />
                {recordingStatus === 'EGRESS_STARTING' ? 'REC 启动中…' : `REC ${recDuration}`}
              </div>
            )}
          </div>

          <div className="call-stage-tools">
            {canSwap && (
              <button
                type="button"
                className={`call-minimize${swapped ? ' is-active' : ''}`}
                title={swapped ? '切换为对方占主屏' : '切换为我占主屏'}
                onClick={toggleMainView}
              >
                <IconSwitchView size={16} />
              </button>
            )}
            {/* ★独立窗口里只有"收回本页"：最小化/还原在独立窗口语境里没有意义
                （窗口本身就能拖，最小化交给操作系统的标题栏）。 */}
            {standalone ? (
              <button
                type="button"
                className="call-minimize"
                title="收回本页（会议继续，窗口会关闭）"
                onClick={() => setPopout(false)}
              >
                <IconDockMini />
              </button>
            ) : (
              <>
                {/* ★仅会议：丢到独立窗口里，用户可以自由放大缩小（飞书同款）。
                    ★这里是从点击里直接触发的，弹窗拦截器一般不会拦 —— 是自动弹窗被拦后的补救入口。 */}
                {isRoom && (
                  <button
                    type="button"
                    className="call-minimize"
                    title="在新窗口中打开"
                    onClick={openPopout}
                  >
                    <IconPopoutMini />
                  </button>
                )}
                {/* ★仅会议：放大/还原。放大后画面变成飞书式大窗口，右侧能放参会人面板。 */}
                {isRoom && (
                  <button
                    type="button"
                    className="call-minimize"
                    title={large ? '还原窗口' : '放大会议窗口'}
                    onClick={toggleLarge}
                  >
                    {large ? <IconCollapseMini /> : <IconExpandMini />}
                  </button>
                )}
                <button type="button" className="call-minimize" title="最小化" onClick={() => setMinimized(true)}>
                  <IconChevronDownMini />
                </button>
              </>
            )}
          </div>
        </div>

        {/* ---------------------------------------------------------------- 参会人面板 */}
        {isRoom && largeUi && panelOpen && (
          <aside className="call-panel" aria-label="参会人">
            <div className="call-panel-head">
              <div className="call-panel-title">
                参会人 <span className="call-panel-count">{rows.length}</span>
              </div>
              <button
                type="button"
                className="call-panel-icon"
                title="刷新参会人"
                onClick={() => void refreshParticipants()}
              >
                <IconRefreshMini />
              </button>
              <button
                type="button"
                className="call-panel-icon"
                title="收起面板"
                onClick={() => setPanelOpen(false)}
              >
                <IconClose size={14} />
              </button>
            </div>

            {amHost && (
              <div className="call-panel-actions">
                {/* ★始终可点：以前的 disabled 判据是「有几个 userId 已知且未静音的人」，
                    guests（identity 是 guest-xxx、没有 userId）根本不计入，只开游客时
                    按钮会永久灰掉（用户反馈「全员静音无法点击」）。现在由服务端按房间
                    座位真实逐个静音，自己判断"没有可静音的"并在 toast 里说明。 */}
                <button
                  type="button"
                  className="call-panel-action"
                  title="把除自己外所有人的麦克风静音（不改变开麦权限，对方可自行开麦；游客同样生效）"
                  onClick={() => void muteAll()}
                >
                  <IconMicOff size={14} />
                  全员静音
                </button>
              </div>
            )}

            <ul className="call-panel-list">
              {rows.map((row) => {
                const muted = row.self ? !micOn : row.micMuted;
                const manage = canManageParticipant(amHost, row);
                return (
                  <li key={row.key} className={`call-person${row.self ? ' is-self' : ''}`}>
                    <span className="call-person-avatar">{participantInitial(row.name)}</span>
                    <div className="call-person-main">
                      <div className="call-person-name">
                        <span className="call-person-name-text">{row.name}</span>
                        {row.self && <span className="call-person-tag">我</span>}
                        {row.host && <span className="call-person-tag is-host">主持人</span>}
                        {row.handRaised && <span className="call-person-tag is-hand">举手</span>}
                        {row.seatCount > 1 && (
                          <span className="call-person-tag" title={row.platforms.map(platformLabel).join(' / ')}>
                            {row.seatCount} 端
                          </span>
                        )}
                      </div>
                      <div className="call-person-sub">
                        {muted ? '已静音' : '麦克风开'}
                        {row.cameraOn ? ' · 视频开' : ''}
                        {row.screenSharing ? ' · 共享中' : ''}
                      </div>
                    </div>
                    {/* ★有管理按钮时不再画状态图标：它和"静音"按钮的图标一模一样，
                        挤在 300px 面板里只会让人分不清哪个能点。 */}
                    {!manage && (
                      <div className="call-person-state" title={muted ? '已静音' : '麦克风开'}>
                        {muted ? <IconMicOff size={16} /> : <IconMicOn size={16} />}
                      </div>
                    )}
                    {manage && (
                      <div className="call-person-ops">
                        {/*
                          ★全员禁言期间，轨道级"取消静音"是无效的（对方的麦根本发不出来）——
                          这时按钮语义必须是"放行/收回发布权限"，与演讲者布局里的
                          renderPeerOps 保持同一套逻辑（之前这里漏了，用户点了没反应）。
                          判据用 micAllowed（权限）而不是 muted（音轨），
                          否则"已放行但对方还没开麦"时会永远重复放行、收不回来。
                        */}
                        {settings.muteAll ? (
                          <button
                            type="button"
                            className={`call-person-op${row.micAllowed ? ' is-danger' : ''}`}
                            aria-label={row.micAllowed ? '收回发言' : '放行发言'}
                            title={
                              row.micAllowed
                                ? '点击收回发言：收回该成员的发言权限（他会被立刻闭麦）'
                                : '点击放行发言：放行后该成员可以自己开麦'
                            }
                            onClick={() =>
                              void setParticipantMicAllowed(row.target, !row.micAllowed)
                            }
                          >
                            {/* ★图标=当前状态，与演讲者布局一致（用户 2026-11-09：「图标静音与未静音用反了」）。 */}
                            {row.micAllowed ? <IconMicOn size={14} /> : <IconMicOff size={14} />}
                          </button>
                        ) : (
                          <button
                            type="button"
                            className={`call-person-op${muted ? '' : ' is-danger'}`}
                            aria-label={muted ? '取消静音' : '静音'}
                            title={muted ? '点击取消静音' : '点击静音'}
                            onClick={() => void muteParticipant(row.target, !muted)}
                          >
                            {/* ★已静音 → 斜杠麦；未静音 → 正常麦。icon 与副标题「已静音 / 麦克风开」必须一致。 */}
                            {muted ? <IconMicOff size={14} /> : <IconMicOn size={14} />}
                          </button>
                        )}
                        {/* ★图标按钮 + hover 提示，与演讲者布局的 renderPeerOps 保持一致 */}
                        <button
                          type="button"
                          className="call-person-op is-danger"
                          aria-label="移出会议"
                          title="移出会议"
                          onClick={() => askKick(row.target, row.name)}
                        >
                          <IconPhoneOff size={14} />
                        </button>
                      </div>
                    )}
                  </li>
                );
              })}
              {rows.length === 0 && (
                <li className="call-panel-empty">
                  {phase === 'active' ? '正在获取参会人…' : '正在进入会议…'}
                </li>
              )}
            </ul>

            {/* ★主持人不再挂说明文案（用户 2026-11-07：这些按钮就在眼前，不需要再解释
                一遍，还长期占着面板底部一行）。非主持人那句保留 —— 它说明的是
                "你现在为什么不能操作"，而不是重复按钮用途。 */}
            {!amHost && <div className="call-panel-foot">等待主持人管理会议。</div>}
          </aside>
        )}
        </div>

        {audioBlocked && (
          <div className="call-banner">
            浏览器拦截了自动播放，
            <button type="button" className="call-banner-btn" onClick={() => void retryAudio()}>
              点击开启声音
            </button>
          </div>
        )}
        {/* ★1v1 通话同样只留"要动手"的横幅，纯提示走 toast（3 秒后自动消失） */}
        {/* ★只说「录制已生成」，不暴露对象存储路径（用户 2026-11-07 要求）。 */}
        {recordingFile && (
          <div className="call-banner call-banner-file">
            <span className="call-banner-file-name">云端录制已生成</span>
            {recordingFile.url ? (
              <a className="call-banner-btn" href={recordingFile.url} target="_blank" rel="noreferrer">
                打开录制
              </a>
            ) : (
              <span className="call-banner-btn">录制已生成</span>
            )}
          </div>
        )}
        {toast && (
          <div className="meet-toast call-toast" role="status" aria-live="polite">
            {toast}
          </div>
        )}

        <div className="call-controls">
          <div className="call-control">
            <button
              type="button"
              className={`call-round${micOn ? '' : ' is-off'}`}
              title={micOn ? '静音' : '取消静音'}
              onClick={() => void toggleMic()}
            >
              {micOn ? <IconMicOn size={19} /> : <IconMicOff size={19} />}
            </button>
            <span className="call-control-label">{micOn ? '静音' : '已静音'}</span>
          </div>

          {/* ★摄像头按钮常驻：语音通话里任何一方都能随时开视频（飞书同款），
              不再由"发起时选的是语音还是视频"决定。 */}
          <div className="call-control">
            <button
              type="button"
              className={`call-round${cameraOn ? '' : ' is-off'}`}
              title={cameraOn ? '关闭摄像头' : '开启视频'}
              onClick={() => void toggleCamera()}
            >
              {cameraOn ? <IconVideo size={19} /> : <IconVideoOff size={19} />}
            </button>
            <span className="call-control-label">{cameraOn ? '关视频' : '开视频'}</span>
          </div>

          {/* ★播放音量：1v1 通话同样可调（用户 2026-11-07 的通用要求）。 */}
          {phase === 'active' && <MeetingVolumeControl />}

          {phase === 'active' && (
            <div className="call-control">
              <button
                type="button"
                className={`call-round${screenOn ? ' is-on' : ''}`}
                title={screenOn ? '停止共享' : '共享屏幕'}
                onClick={() => void toggleScreenShare()}
              >
                {screenOn ? <IconScreenShareOff size={19} /> : <IconScreenShare size={19} />}
              </button>
              <span className="call-control-label">共享</span>
            </div>
          )}

          {/* ★云端录制（LiveKit RoomCompositeEgress → S3）。
              ★服务端接口是 requireHost：会议里看服务端角色（主持人断线重进也还是主持人），
                1v1 通话里就是主叫。别人点了也只会收到"只有发起方可以开启云端录制"。 */}
          {phase === 'active' && (isRoom ? amHost : call.direction === 'out') && (
            <div className="call-control">
              <button
                type="button"
                className={`call-round${recording ? ' is-rec' : ''}`}
                title={
                  recordingBusy
                    ? '正在处理录制请求…'
                    : recording
                      ? '停止录制'
                      : '开始云端录制'
                }
                disabled={recordingBusy}
                onClick={() => void toggleRecording()}
              >
                {recording ? <IconStop size={19} /> : <IconRecord size={19} />}
              </button>
              <span className="call-control-label">
                {recordingBusy ? '处理中' : recording ? '停止录制' : '录制'}
              </span>
            </div>
          )}

          {/* ★参会人：点开即展开大窗口 + 右侧面板。
              会中"谁在、谁在说话"是最高频的信息，必须一键可达。 */}
          {isRoom && phase === 'active' && (
            <div className="call-control">
              <button
                type="button"
                className={`call-round${panelOpen ? ' is-on' : ''}`}
                title={panelOpen ? '收起参会人' : '查看参会人'}
                onClick={() => {
                  setPanelOpen((v) => !v);
                  // ★独立窗口里本来就是大窗布局，不需要（也没有）"放大"这一步
                  if (!standalone) setLarge(true);
                }}
              >
                <IconUsers size={19} />
              </button>
              <span className="call-control-label">
                参会人{rows.length > 0 ? ` ${rows.length}` : ''}
              </span>
            </div>
          )}

          {/* ★主持人专属：散会。★与"离开"用不同的按钮外观（白底红框 vs 实心红），
              两个都是红色的话，点错一次就把整场会散了。 */}
          {isRoom && amHost && (
            <div className="call-control">
              <button
                type="button"
                className="call-round call-round-end"
                title="结束会议（所有人退出，并停止云端录制）"
                onClick={() => setConfirm({ kind: 'leave' })}
              >
                <IconStop size={19} />
              </button>
              <span className="call-control-label">结束会议</span>
            </div>
          )}

          <div className="call-control">
            {/* ★房间会议里是"离开"而不是"挂断"：挂断会让用户以为把会散了 */}
            <button
              type="button"
              className="call-round call-round-decline"
              title={isRoom ? '离开会议' : '挂断'}
              onClick={requestLeave}
            >
              <IconPhoneOff size={20} />
            </button>
            <span className="call-control-label">{isRoom ? '离开' : '挂断'}</span>
          </div>
        </div>
      </div>
      </div>
    </>
  );
}

