/**
 * 内联 SVG 图标集（飞书风格重做 UI 用）。
 *
 * <p>★为什么不引 {@code @ant-design/icons}：本项目依赖里本来没有它，
 * 为一组图标新增一个包不值当；而这些图标形状固定、无主题诉求，
 * 内联 SVG 是最小依赖面（也与飞书的线性图标观感一致：1.5px 描边、圆角端点）。
 *
 * <p>★统一约定：{@code size} 控制宽高（默认 18），颜色继承 {@code currentColor}，
 * 由 CSS 的 color 决定（hover/active 态只改 color，不重渲染 SVG）。
 */
import type { SVGProps } from 'react';

type IconProps = SVGProps<SVGSVGElement> & { size?: number };

function base({ size = 18, ...rest }: IconProps): SVGProps<SVGSVGElement> {
  return {
    width: size,
    height: size,
    viewBox: '0 0 24 24',
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 1.7,
    strokeLinecap: 'round',
    strokeLinejoin: 'round',
    'aria-hidden': true,
    ...rest,
  };
}

/** 搜索（放大镜）。 */
