import type { CaptureBridge } from '../types/interfaces/hostBridge';

/** Optional desktop bridge. Browser-only IM keeps its existing display-media fallback. */
export type NativeCaptureAction = 'screenshot' | 'mp4' | 'gif';
export type NativeCaptureBridge = Pick<CaptureBridge,
  'screenshot' | 'record' | 'interactive' | 'readChunk' | 'release' | 'copy' | 'onShortcut'>;
export function getNativeCapture(): NativeCaptureBridge | undefined {
  if (typeof window === 'undefined') return undefined;
  const bridge = window.NuwaClawBridge?.capture;
  return bridge && ['screenshot', 'record', 'readChunk', 'release'].every(key => typeof bridge[key as keyof NativeCaptureBridge] === 'function') ? bridge : undefined;
}

const CHUNK_BYTES = 4 * 1024 * 1024;
const EXTENSIONS: Record<string, string> = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'video/mp4': 'mp4', 'video/webm': 'webm', 'image/gif': 'gif' };

/** Add a draft attachment only to the initiating conversation; never send a message. */
export async function captureIntoComposer(bridge: NativeCaptureBridge, action: NativeCaptureAction, target: {
  isCurrent(): boolean;
  maxBytes: number;
  addFiles(files: File[]): void;
  onCopied(): void;
}): Promise<void> {
  const result = bridge.interactive ? await bridge.interactive({ action }) : action === 'screenshot'
    ? await bridge.screenshot() : await bridge.record({ output: action });
  if (!result.success) {
    if (result.code === 'canceled') return;
    if (result.code === 'permission-denied') throw new Error('没有屏幕录制权限，请在系统设置里允许本应用');
    throw new Error(result.code === 'busy' ? '请先完成当前截图或录屏' : result.code === 'encoder-unavailable' ? '当前设备暂不支持该录屏格式' : '截图或录屏失败，请重试');
  }
  const copyInstead = async () => {
    if (await bridge.copy?.(result.resultId).then(value => value.success).catch(() => false)) target.onCopied();
    else throw new Error('原会话已切换，未插入附件；请重新截图或录屏');
  };
  try {
    if (!target.isCurrent()) { await copyInstead(); return; }
    if (!Number.isSafeInteger(result.bytes) || result.bytes < 1 || result.bytes > target.maxBytes || result.exceedsMaxBytes) {
      throw new Error('截图或录屏超过附件大小限制，请降低画质或缩短录制');
    }
    const ext = Object.prototype.hasOwnProperty.call(EXTENSIONS, result.mime) ? EXTENSIONS[result.mime] : undefined;
    if (!ext) throw new Error('截图或录屏格式不可用');
    const parts: ArrayBuffer[] = [];
    for (let offset = 0; offset < result.bytes;) {
      const length = Math.min(CHUNK_BYTES, result.bytes - offset);
      const bytes = await bridge.readChunk(result.resultId, offset, length);
      if (!bytes || bytes.byteLength !== length) throw new Error('截图或录屏结果已失效，请重试');
      parts.push(bytes); offset += bytes.byteLength;
    }
    if (!target.isCurrent()) { await copyInstead(); return; }
    const name = `${result.mime.startsWith('video/') || result.mime === 'image/gif' ? '录屏' : '截图'}-${Date.now()}.${ext}`;
    target.addFiles([new File(parts, name, { type: result.mime })]);
  } finally { await bridge.release(result.resultId).catch(() => undefined); }
}
