/**
 * ★★会议回放播放器 —— 主持端详情页与回放分享页<b>共用同一份</b>（两处都要求登录）。
 *
 * <h2>它解决什么</h2>
 *
 * <p>录制文件只是一段音视频，真正让人"看得懂"的是旁边的转写：
 * 点击一句话跳到那个位置、播到哪句就高亮哪句。这两件事必须由同一个组件负责，
 * 否则时间轴会对不上（转写的 {@code beginMs} 是<b>相对文件开头</b>的毫秒）。
 *
 * <h2>★为什么不用原生 {@code controls}</h2>
 *
 * <p>原生控制条在不同浏览器里长得完全不一样，而这里要的"±10 秒 / 倍速 / 时间轴"
 * 在移动端原生控件里并不齐（Safari 的倍速藏在两级菜单里）。自定义一套浅色控件
 * （{@code .rp-*}）能让匿名页与主持端看起来是同一个产品。
 *
 * <h2>★★地址永远现签</h2>
 *
 * <p>播放/下载地址由 {@code resolveUrl} / {@code resolveDownloadUrl} 在**用到时**向服务端现签
 * （详情页走 {@code /meetings/{id}/files/{id}/url}，分享页走
 * {@code /replays/{token}/files/{id}/url?download=…}）。
 * 组件自己<b>不缓存 token、不拼 URL</b> —— 它连会议 id 都不知道。
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import {
  bytesText,
  playKind,
  recordingDisplayName,
  speakerLabels,
  speakerNameOf,
  timelineText,
  transcriptEmptyText,
} from '../lib/meetingRecord';
import {
  REPLAY_RATES,
  REPLAY_STEP_MS,
  clampSeek,
  downloadCandidates,
  pickReplayFile,
  segmentIndexAt,
  segmentsForFile,
  stepRate,
  toSpeakerNameMap,
  transcriptsForFile,
  visibleReplayFiles,
} from '../lib/meetingReplay';
import type { ReplayFile, ReplayTranscript } from '../lib/meetingReplay';

interface Props {
  /** 全部可下载的文件（含派生音频）。播放列表由组件自己过滤掉派生音频。 */
  files: ReplayFile[];
  transcripts: ReplayTranscript[];
  /** 现签一个**播放**（inline）地址。同一文件重复调用应当能拿到新链接。 */
  resolveUrl: (fileId: string) => Promise<string>;
  /**
   * 现签一个**下载**（attachment）地址。
   *
   * <p>不传则不显示「下载」按钮（分享链接现在要求登录，两处调用方都会传）。
   */
  resolveDownloadUrl?: (fileId: string) => Promise<{ url: string; filename?: string | null }>;
  /** 没有可播文件时的文案。 */
  emptyText?: string;
}

export default function MeetingReplayView({
  files,
  transcripts,
  resolveUrl,
  resolveDownloadUrl,
  emptyText = '这场会议没有可回放的录制',
}: Props) {
  /**
   * ★播放列表去掉派生音频（{@code -音频.m4a}）：
   * 它与源录制是同一段声音，并排出现只会让人以为"录了两遍"。
   */
  const playFiles = useMemo(() => visibleReplayFiles(files), [files]);
  const picked = useMemo(() => pickReplayFile(playFiles, transcripts), [playFiles, transcripts]);
  const [selectedId, setSelectedId] = useState<string | null>(picked?.id ?? null);
  const [url, setUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);
  /** 换文件 / 重试计数：让"再签一次"成为一次显式的 effect 重跑。 */
  const [attempt, setAttempt] = useState(0);

  const [playing, setPlaying] = useState(false);
  const [currentMs, setCurrentMs] = useState(0);
  const [durationMs, setDurationMs] = useState(0);
  const [rate, setRate] = useState(1);
  /** ★自动跟随：用户自己滚过转写列表后停 5 秒，之后恢复，避免"手刚拖开就被抢回去"。 */
  const [follow, setFollow] = useState(true);

  const mediaRef = useRef<HTMLMediaElement | null>(null);
  const listRef = useRef<HTMLOListElement | null>(null);
  const itemRefs = useRef<Record<number, HTMLLIElement | null>>({});
  const followTimer = useRef<number | null>(null);

  const file = useMemo(
    () => playFiles.find((f) => f.id === selectedId) ?? null,
    [playFiles, selectedId],
  );
  const kind = file ? playKind(file.status ?? 2, file.contentType, file.filename) : null;
  /** ★只有"地址已签 + 文件可播 + 没报错"三件事同时成立，控制条才可点。 */
  const canPlay = url != null && kind != null && loadError == null;

  // ★文件列表变化（详情刷新 / 分享页首次加载）时，保证选中项仍然存在。
  useEffect(() => {
    if (playFiles.length === 0) {
      if (selectedId != null) setSelectedId(null);
      return;
    }
    if (selectedId != null && playFiles.some((f) => f.id === selectedId)) return;
    setSelectedId(picked?.id ?? playFiles[0].id);
  }, [playFiles, picked, selectedId]);

  // ★选中文件后现签地址。取消标记防止"快速切换文件时旧请求回来覆盖新地址"。
  useEffect(() => {
    if (!selectedId) {
      setUrl(null);
      return;
    }
    let cancelled = false;
    setLoading(true);
    setLoadError(null);
    setUrl(null);
    setCurrentMs(0);
    setPlaying(false);
    setDurationMs(
      file?.durationSec != null && file.durationSec > 0 ? Math.round(file.durationSec * 1000) : 0,
    );
    resolveUrl(selectedId)
      .then((next) => {
        if (cancelled) return;
        if (!next) {
          setLoadError('暂时无法播放这段录制，请稍后再试');
          return;
        }
        setUrl(next);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setLoadError(e instanceof Error ? e.message : '暂时无法播放这段录制，请稍后再试');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedId, attempt, resolveUrl]);

  const segments = useMemo(
    () => segmentsForFile(transcripts, selectedId),
    [transcripts, selectedId],
  );

  /**
   * ★没有句子时的说明：这段录音是"正在识别"还是"真的没有"。
   *
   * <p>用户 2026-11-10 反馈转写没跑完时界面读起来像已经完事 —— 原来这一格
   * 一律写「这段录制还没有可用的转写文字」，现在按转写状态给阶段文案。
   */
  const emptyHint = useMemo(
    () => transcriptEmptyText(transcriptsForFile(transcripts, selectedId).map((t) => t.status)),
    [transcripts, selectedId],
  );

  const speakerNames = useMemo(() => {
    const merged: Record<string, { name: string }> = {};
    for (const t of transcriptsForFile(transcripts, selectedId)) {
      const m = toSpeakerNameMap(t.speakerNames);
      if (m) Object.assign(merged, m);
    }
    return Object.keys(merged).length > 0 ? merged : null;
  }, [transcripts, selectedId]);

  const labels = useMemo(() => speakerLabels(segments, speakerNames), [segments, speakerNames]);
  const activeIndex = segmentIndexAt(segments, currentMs);

  // ---------------------------------------------------------------- 媒体控制

  const seekTo = useCallback(
    (ms: number) => {
      const target = clampSeek(ms, durationMs);
      setCurrentMs(target);
      const media = mediaRef.current;
      if (media) {
        try {
          media.currentTime = target / 1000;
        } catch {
          // 元数据还没到时个别浏览器会抛；忽略，进度条仍然停在目标位置。
        }
      }
    },
    [durationMs],
  );

  const togglePlay = useCallback(() => {
    const media = mediaRef.current;
    if (!media) return;
    if (media.paused) {
      void media.play().catch(() => setLoadError('浏览器阻止了自动播放，请再点一次播放'));
    } else {
      media.pause();
    }
  }, []);

  const changeRate = useCallback((next: number) => {
    setRate(next);
    if (mediaRef.current) mediaRef.current.playbackRate = next;
  }, []);

  // 切换文件时把倍速续上（新元素是默认 1x）
  useEffect(() => {
    if (mediaRef.current) mediaRef.current.playbackRate = rate;
  }, [rate, url]);

  // ---------------------------------------------------------------- 下载

  const [dlOpen, setDlOpen] = useState(false);
  const [dlBusy, setDlBusy] = useState(false);
  const [dlNote, setDlNote] = useState<string | null>(null);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const dlWrapRef = useRef<HTMLDivElement | null>(null);
  const dlNoteTimer = useRef<number | null>(null);

  /**
   * ★当前会议可下载的"视频 / 音频"各一条。
   *
   * <p>★两类都有时要让用户选：他要的可能是小体积的音频，也可能是带画面的视频，
   * 组件不该替他决定。只有一类时直接下 —— 多一次点击没有任何信息量。
   */
  const downloads = useMemo(() => downloadCandidates(files, selectedId), [files, selectedId]);

  const showDlNote = useCallback((text: string) => {
    setDlNote(text);
    if (dlNoteTimer.current != null) window.clearTimeout(dlNoteTimer.current);
    dlNoteTimer.current = window.setTimeout(() => setDlNote(null), 2600);
  }, []);

  useEffect(
    () => () => {
      if (dlNoteTimer.current != null) window.clearTimeout(dlNoteTimer.current);
    },
    [],
  );

  /** 点别处收起下载菜单（详情弹框与会中窗口都只在各自的 document 里监听）。 */
  useEffect(() => {
    if (!dlOpen) return;
    const onDown = (e: Event) => {
      const wrap = dlWrapRef.current;
      if (wrap && e.target instanceof Node && wrap.contains(e.target)) return;
      setDlOpen(false);
    };
    const doc = rootRef.current?.ownerDocument ?? document;
    doc.addEventListener('pointerdown', onDown);
    return () => doc.removeEventListener('pointerdown', onDown);
  }, [dlOpen]);

  const runDownload = useCallback(
    async (target: ReplayFile) => {
      if (!resolveDownloadUrl) return;
      setDlOpen(false);
      setDlBusy(true);
      try {
        const res = await resolveDownloadUrl(target.id);
        if (!res.url) {
          showDlNote('暂时无法下载这段录制，请稍后再试');
          return;
        }
        // ★锚点挂到组件所在的 document（会中窗口是另一份），与详情页的下载同一口径。
        const doc = rootRef.current?.ownerDocument ?? document;
        const a = doc.createElement('a');
        a.href = res.url;
        a.rel = 'noopener';
        a.download = res.filename || target.filename || '会议录制';
        doc.body.appendChild(a);
        a.click();
        a.remove();
      } catch (e) {
        showDlNote(e instanceof Error ? e.message : '下载失败，请稍后再试');
      } finally {
        setDlBusy(false);
      }
    },
    [resolveDownloadUrl, showDlNote],
  );

  const onDownloadClick = useCallback(() => {
    if (dlBusy) return;
    if (downloads.length === 0) {
      showDlNote('这场会议没有可下载的录制');
      return;
    }
    if (downloads.length === 1) {
      void runDownload(downloads[0].file);
      return;
    }
    setDlOpen((v) => !v);
  }, [dlBusy, downloads, runDownload, showDlNote]);

  // ---------------------------------------------------------------- 自动跟随

  const stopFollow = useCallback(() => {
    setFollow(false);
    if (followTimer.current != null) window.clearTimeout(followTimer.current);
    followTimer.current = window.setTimeout(() => setFollow(true), 5000);
  }, []);

  useEffect(
    () => () => {
      if (followTimer.current != null) window.clearTimeout(followTimer.current);
    },
    [],
  );

  /**
   * ★把当前句滚到可见处。
   *
   * <p>★手动算 {@code scrollTop} 而不是 {@code scrollIntoView}：后者会把
   * <b>外层弹框/整页</b>一起滚走，在会议详情弹框里表现为"播到一半页面跳一下"。
   */
  useEffect(() => {
    if (!follow || activeIndex < 0) return;
    const box = listRef.current;
    const el = itemRefs.current[activeIndex];
    if (!box || !el) return;
    const top = el.offsetTop;
    const bottom = top + el.offsetHeight;
    if (top < box.scrollTop + 4) {
      box.scrollTop = Math.max(0, top - 8);
    } else if (bottom > box.scrollTop + box.clientHeight - 4) {
      box.scrollTop = bottom - box.clientHeight + 8;
    }
  }, [activeIndex, follow]);

  // ---------------------------------------------------------------- 渲染

  if (playFiles.length === 0) {
    return <div className="rp-empty">{emptyText}</div>;
  }

  return (
    <div className="rp-root" ref={rootRef}>
      {playFiles.length > 1 && (
        <div className="rp-files" role="tablist" aria-label="录制分段">
          {playFiles.map((f, i) => (
            <button
              key={f.id}
              type="button"
              role="tab"
              aria-selected={f.id === selectedId}
              className={`rp-file-tab${f.id === selectedId ? ' is-on' : ''}`}
              onClick={() => setSelectedId(f.id)}
            >
              {recordingDisplayName(f.filename) || `第 ${i + 1} 段`}
            </button>
          ))}
        </div>
      )}

      {/* ★左右分栏：左=画面与控制，右=转写。宽屏并排，窄屏自动堆叠（见 styles.css）。
          ★把画面、控制条、进度条包成同一列，右边那列才有"与播放器等高"的参照。 */}
      <div className="rp-split">
        <div className="rp-left">
          {/* ★纯音频时给舞台一个 is-audio：里面没有任何画面，只放「录音回放中」。
              判据直接用上面算好的 kind，不再看文件名后缀。 */}
          <div className={`rp-stage${kind === 'audio' ? ' is-audio' : ''}`}>
            {loading && <div className="rp-stage-note">正在准备播放地址…</div>}
            {!loading && loadError != null && (
              <div className="rp-stage-note is-fail">
                {loadError}
                <button
                  type="button"
                  className="rp-btn"
                  onClick={() => {
                    setAttempt((n) => n + 1);
                  }}
                >
                  重试
                </button>
              </div>
            )}
            {!loading && loadError == null && url != null && kind != null && (
              kind === 'video' ? (
                <video
                  key={url}
                  ref={(el) => {
                    mediaRef.current = el;
                  }}
                  className="rp-media"
                  src={url}
                  playsInline
                  preload="metadata"
                  onPlay={() => setPlaying(true)}
                  onPause={() => setPlaying(false)}
                  onEnded={() => setPlaying(false)}
                  onTimeUpdate={(e) => setCurrentMs(Math.round(e.currentTarget.currentTime * 1000))}
                  onLoadedMetadata={(e) => {
                    const d = e.currentTarget.duration;
                    if (Number.isFinite(d) && d > 0) setDurationMs(Math.round(d * 1000));
                  }}
                  onError={() => setLoadError('这段录制的播放地址已失效，请点重试')}
                />
              ) : (
                <>
                  {/* ★纯音频没有画面，舞台里放一句「录音回放中」+ 播放中的波形动效。
                      波形只是"确实在播"的视觉反馈，不参与任何逻辑；暂停即停。 */}
                  <div className={`rp-audio-visual${playing ? ' is-playing' : ''}`}>
                    <div className="rp-audio-bars" aria-hidden="true">
                      <i />
                      <i />
                      <i />
                      <i />
                      <i />
                    </div>
                    <div className="rp-audio-title">录音回放中</div>
                    <div className="rp-audio-sub">本场会议只有录音，没有视频画面</div>
                  </div>
                  {/* ★<audio> 不开 controls（控制条是我们自己的），这里只负责出声。
                      CSS 里视觉隐藏但保留在文档流之外，避免多出一条白色空条。 */}
                  <audio
                    key={url}
                    ref={(el) => {
                      mediaRef.current = el;
                    }}
                    className="rp-media is-audio"
                    src={url}
                    preload="metadata"
                    onPlay={() => setPlaying(true)}
                    onPause={() => setPlaying(false)}
                    onEnded={() => setPlaying(false)}
                    onTimeUpdate={(e) => setCurrentMs(Math.round(e.currentTarget.currentTime * 1000))}
                    onLoadedMetadata={(e) => {
                      const d = e.currentTarget.duration;
                      if (Number.isFinite(d) && d > 0) setDurationMs(Math.round(d * 1000));
                    }}
                    onError={() => setLoadError('这段录制的播放地址已失效，请点重试')}
                  />
                </>
              )
            )}
            {!loading && loadError == null && url != null && kind == null && (
              <div className="rp-stage-note">这段文件不支持在页面内播放</div>
            )}
            {!loading && loadError == null && url == null && (
              <div className="rp-stage-note">正在准备播放器…</div>
            )}
          </div>

          <div className="rp-controls">
            <button
              type="button"
              className="rp-btn rp-btn-play"
              disabled={!canPlay}
              onClick={togglePlay}
              aria-label={playing ? '暂停' : '播放'}
            >
              {playing ? '暂停' : '播放'}
            </button>
            <button
              type="button"
              className="rp-btn"
              disabled={!canPlay}
              onClick={() => seekTo(currentMs - REPLAY_STEP_MS)}
              title="后退 10 秒"
            >
              −10s
            </button>
            <button
              type="button"
              className="rp-btn"
              disabled={!canPlay}
              onClick={() => seekTo(currentMs + REPLAY_STEP_MS)}
              title="前进 10 秒"
            >
              +10s
            </button>
            <span className="rp-time">
              {timelineText(currentMs)}
              <i>/</i>
              {timelineText(durationMs)}
            </span>
            <span className="rp-spacer" />
            <label className="rp-rate">
              <span>倍速</span>
              <select
                value={String(rate)}
                disabled={!canPlay}
                onChange={(e) => changeRate(Number(e.target.value))}
              >
                {REPLAY_RATES.map((r) => (
                  <option key={r} value={String(r)}>
                    {r}x
                  </option>
                ))}
              </select>
            </label>
            <button
              type="button"
              className="rp-btn"
              disabled={!canPlay || rate >= REPLAY_RATES[REPLAY_RATES.length - 1]}
              onClick={() => changeRate(stepRate(rate, 1))}
              title="加速"
            >
              加速
            </button>
            {resolveDownloadUrl && (
              <div className="rp-dl" ref={dlWrapRef}>
                <button
                  type="button"
                  className="rp-btn"
                  disabled={dlBusy}
                  onClick={onDownloadClick}
                  title="下载录制文件"
                  aria-haspopup={downloads.length > 1 ? 'menu' : undefined}
                  aria-expanded={downloads.length > 1 ? dlOpen : undefined}
                >
                  {dlBusy ? '准备中…' : '下载'}
                </button>
                {/* ★只有音视频都有时才出现：两类只有一类时上面那一下已经直下了。 */}
                {dlOpen && downloads.length > 1 && (
                  <div className="rp-dl-menu" role="menu" aria-label="选择下载内容">
                    {downloads.map((c) => (
                      <button
                        key={c.kind}
                        type="button"
                        role="menuitem"
                        className="rp-dl-item"
                        onClick={() => void runDownload(c.file)}
                      >
                        <span className="rp-dl-item-name">
                          {c.kind === 'video' ? '下载视频' : '下载音频'}
                        </span>
                        <span className="rp-dl-item-meta">
                          {[bytesText(c.file.sizeBytes), c.kind === 'video' ? '含画面' : '仅声音']
                            .filter(Boolean)
                            .join(' · ')}
                        </span>
                      </button>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>

          {dlNote && <div className="rp-dl-note">{dlNote}</div>}

          <input
            className="rp-progress"
            type="range"
            min={0}
            max={Math.max(1, durationMs)}
            step={500}
            value={Math.min(currentMs, Math.max(1, durationMs))}
            disabled={!canPlay || durationMs <= 0}
            aria-label="播放进度"
            onChange={(e) => seekTo(Number(e.target.value))}
          />
        </div>

        <div className="rp-right">
          <div className="rp-below">
            <div className="rp-segs-head">
              <span>转写</span>
              <span className="rp-segs-count">{segments.length > 0 ? `${segments.length} 句` : '暂无'}</span>
              {segments.length > 0 && (
                <button
                  type="button"
                  className={`rp-follow${follow ? ' is-on' : ''}`}
                  onClick={() => {
                    if (followTimer.current != null) window.clearTimeout(followTimer.current);
                    setFollow((v) => !v);
                  }}
                  title="播放时自动滚到当前这句"
                >
                  {follow ? '跟随中' : '已暂停跟随'}
                </button>
              )}
            </div>

            {segments.length === 0 ? (
              <div className="rp-empty-inline">{emptyHint}</div>
            ) : (
              <ol
                className="rp-segs"
                ref={listRef}
                onWheel={stopFollow}
                onTouchMove={stopFollow}
                onPointerDown={stopFollow}
              >
                {segments.map((s, i) => {
                  const name = speakerNameOf(labels, s.speakerId);
                  const prev = i > 0 ? speakerNameOf(labels, segments[i - 1].speakerId) : null;
                  const showName = name !== prev;
                  return (
                    <li
                      key={`${i}-${s.beginMs ?? 0}`}
                      ref={(el) => {
                        itemRefs.current[i] = el;
                      }}
                      className={`rp-seg${i === activeIndex ? ' is-on' : ''}`}
                      onClick={() => seekTo(s.beginMs == null ? 0 : s.beginMs)}
                      role="button"
                      tabIndex={0}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' || e.key === ' ') {
                          e.preventDefault();
                          seekTo(s.beginMs == null ? 0 : s.beginMs);
                        }
                      }}
                    >
                      <span className="rp-seg-time">{timelineText(s.beginMs)}</span>
                      <span className="rp-seg-main">
                        {showName && <span className="rp-seg-speaker">{name}</span>}
                        <span className="rp-seg-text">{s.text}</span>
                      </span>
                    </li>
                  );
                })}
              </ol>
            )}
          </div>
        </div>
      </div>

    </div>
  );
}
