/**
 * ★会中「参会人」面板的纯逻辑（无 React / 无网络，便于单测）。
 *
 * <h2>为什么要聚合，而不是直接渲染服务端列表</h2>
 *
 * <p>服务端的 {@code MeetingParticipantView} 是<b>席位</b>而不是<b>人</b>：
 * 同一账号在手机和网页同时入会，会返回两条 {@code userId} 相同的记录
 * （identity 第三段是平台）。飞书的参会人面板一行一个人，
 * 直接把席位摊平会出现"张三"两行、看起来像有两个人。
 *
 * <p>⇒ 这里按 {@code userId} 聚合成「人」，多端只显示一个平台数量角标；
 * 但<b>操作仍按 userId 扇出</b>（服务端不带 platform 时会踢/静音该用户全部席位），
 * 这正是"把这个人移出会议"的语义，不会出现"踢了手机、网页还在"。
 *
 * <h2>★麦克风状态怎么判</h2>
 *
 * <p>LiveKit 的 track {@code source} 是枚举名（大写）：{@code MICROPHONE / CAMERA /
 * SCREEN_SHARE}。一个席位<b>没有</b>麦克风轨 = 他还没开麦（或没有麦克风），
 * 面板上同样应该显示"静音"，否则会出现"看着有声、其实没人说话"的错觉。
 */
import type { MeetingParticipantView, MeetingTrackView } from '../api/types';

export interface MeetingParticipantRow {
  /** 聚合键：有 userId 用 {@code u:<userId>}，否则用 identity。 */
  key: string;
  /** ★IM 用户 id；游客（{@code guest-xxx}）与外部接入者为 null。 */
  userId: string | null;
  /**
   * ★主持人管理操作的<b>目标标识</b>：登录成员用 userId（服务端按人扇出全部平台席位），
   * 游客没有 userId，就用 identity（服务端只能作用于这一个席位）。
   *
   * <p>用户 2026-11-08：「主持人无法关闭某人的麦 / 看不到移除图标」——
   * 根因就是游客的 userId 是 null，旧逻辑直接不给按钮；其实游客同样需要被静音、
   * 被移出，否则开放游客入会的会议根本管不了。
   */
  target: string;
  identity: string;
  name: string;
  /** ★头像地址（LiveKit attribute {@code avatar}）；空串 ⇒ 界面用首字兜底。 */
  avatar: string;
  host: boolean;
  self: boolean;
  /** 该人所有席位都静音（或没有麦克风轨）时为 true。 */
  micMuted: boolean;
  /**
   * ★该人是否被允许发布麦克风（权限层面）。
   *
   * <p>「全员禁言」不是把 track 静音就完事，而是把 {@code MICROPHONE} 从
   * {@code canPublishSources} 里摘掉 —— 所以判断"能不能发言"必须看权限，
   * 不能看 {@link micMuted}：被放行的人如果自己没开麦，{@code micMuted} 仍然是 true，
   * 主持人会误以为"没放行成功"，再点一次只是重复放行，永远收不回来。
   */
  micAllowed: boolean;
  /** ★是否举手（LiveKit attributes 的 {@code handRaised}）。举手的人排在面板最前。 */
  handRaised: boolean;
  cameraOn: boolean;
  screenSharing: boolean;
  /** 在线端类型（去重）：web/ios/android/... */
  platforms: string[];
  /** 席位数量（>1 表示同一个人多端在会）。 */
  seatCount: number;
  joinedAt?: string;
}

function upper(v: string | null | undefined): string {
  return (v ?? '').toUpperCase();
}

/** ★字符串化 userId：服务端是 19 位雪花 id，界面里一律当字符串用。 */
export function userIdOf(p: Pick<MeetingParticipantView, 'userId'> | { userId?: unknown }): string | null {
  const v = p.userId;
  if (v == null || v === '') return null;
  const s = String(v).trim();
  return s === '' ? null : s;
}

function isMicTrack(t: MeetingTrackView): boolean {
  if (upper(t.type) === 'AUDIO') return upper(t.source) === 'MICROPHONE' || upper(t.source) === '';
  return upper(t.source) === 'MICROPHONE';
}

/** 该席位是否说不出话：没有麦克风轨，或麦克风轨全 muted。 */
export function seatMicMuted(p: Pick<MeetingParticipantView, 'tracks'>): boolean {
  const mics = (p.tracks ?? []).filter(isMicTrack);
  if (mics.length === 0) return true;
  return mics.every((t) => t.muted !== false);
}

/**
 * 该席位是否被允许发布麦克风。
 *
 * <p>LiveKit 的 {@code canPublishSources} 空列表表示<b>不限制</b>；非空则必须显式
 * 含 {@code MICROPHONE} 才算允许。老服务端不返回 permission 时按允许处理。
 */
export function seatMicAllowed(p: Pick<MeetingParticipantView, 'permission'>): boolean {
  const sources = p.permission?.canPublishSources;
  if (!Array.isArray(sources) || sources.length === 0) return true;
  return sources.some((s) => upper(s) === 'MICROPHONE');
}

export function seatCameraOn(p: Pick<MeetingParticipantView, 'tracks'>): boolean {
  return (p.tracks ?? []).some(
    (t) => (upper(t.type) === 'VIDEO' || upper(t.source) === 'CAMERA') && t.muted === false,
  );
}

export function seatScreenSharing(p: Pick<MeetingParticipantView, 'tracks'>): boolean {
  return (p.tracks ?? []).some((t) => upper(t.source) === 'SCREEN_SHARE' && t.muted === false);
}

/** ★该席位是否举手：LiveKit attribute {@code handRaised} 约定成 '1' / ''。 */
export function seatHandRaised(p: Pick<MeetingParticipantView, 'attributes'>): boolean {
  return ((p.attributes?.handRaised ?? '') !== '');
}

function nameOf(p: MeetingParticipantView): string {
  const name = (p.name ?? '').trim();
  if (name) return name;
  const uid = userIdOf(p);
  return uid ? `用户 ${uid}` : (p.identity || '访客');
}

export interface SelfRef {
  userId?: string | null;
  identity?: string | null;
}

/**
 * ★席位 ⇒ 人。返回顺序：主持人 → 我 → 其他（按入会时间，再按名字）。
 *
 * @param self 用来标出"我"（userId 优先；identity 兜住还没拿到 userId 的极端情况）
 */
export function aggregateParticipants(
  list: readonly MeetingParticipantView[],
  self: SelfRef = {},
): MeetingParticipantRow[] {
  const selfId = self.userId == null || self.userId === '' ? null : String(self.userId);
  const selfIdentity = self.identity == null || self.identity === '' ? null : String(self.identity);

  const map = new Map<string, MeetingParticipantRow>();
  for (const p of list) {
    if (!p || !p.identity) continue;
    // ★★服务端录制（Egress）在 LiveKit 里也是一个参与者，identity 形如 {@code EG_xxxx}，
    //   权限里带 {@code hidden + recorder}。它不是人：不滤掉的话参会人面板会多出
    //   一个陌生成员、人数也多 1，用户会以为会里有人在偷听。
    if (p.permission?.hidden === true || p.permission?.recorder === true) continue;
    const uid = userIdOf(p);
    const key = uid ? `u:${uid}` : `i:${p.identity}`;
    const micMuted = seatMicMuted(p);
    const micAllowed = seatMicAllowed(p);
    const handRaised = seatHandRaised(p);
    const cameraOn = seatCameraOn(p);
    const screenSharing = seatScreenSharing(p);
    const existing = map.get(key);
    if (!existing) {
      map.set(key, {
        key,
        userId: uid,
        target: uid ?? p.identity,
        identity: p.identity,
        name: nameOf(p),
        avatar: (p.attributes?.avatar ?? '').trim(),
        host: p.host === true,
        self: (uid != null && selfId != null && uid === selfId) || p.identity === selfIdentity,
        micMuted,
        micAllowed,
        handRaised,
        cameraOn,
        screenSharing,
        platforms: p.platform ? [p.platform] : [],
        seatCount: 1,
        joinedAt: p.joinedAt,
      });
      continue;
    }
    // ★同一个人多端：只要有一端在说话就不算静音；只要有一端开了摄像头就算开着。
    existing.micMuted = existing.micMuted && micMuted;
    // ★多端：任意一端被允许就算允许（管理员按 userId 扇出，最终所有席位一致）
    existing.micAllowed = existing.micAllowed || micAllowed;
    // ★多端：任意一端举手，这个人就算举手（与"任一端开麦就不算静音"同口径）
    existing.handRaised = existing.handRaised || handRaised;
    existing.cameraOn = existing.cameraOn || cameraOn;
    existing.screenSharing = existing.screenSharing || screenSharing;
    existing.host = existing.host || p.host === true;
    existing.self = existing.self || p.identity === selfIdentity;
    existing.seatCount += 1;
    if (p.platform && !existing.platforms.includes(p.platform)) existing.platforms.push(p.platform);
    // 主持人席位的名字更可信（普通席位可能是"我"之类的占位名）
    if (p.host === true) existing.name = nameOf(p);
    // ★同一账号多端：任意一端带了头像就够用（头像跟着账号，不跟着设备）
    if (!existing.avatar) existing.avatar = (p.attributes?.avatar ?? '').trim();
    if (existing.joinedAt == null && p.joinedAt != null) existing.joinedAt = p.joinedAt;
  }

  return [...map.values()].sort((a, b) => {
    // ★举手的人排最前（用户 2026-11-08：「举手的自动到最前面」）。
    //   主持人/自己的次序只在举手状态相同时生效 —— 否则有人举手，主持人还得往下翻。
    if (a.handRaised !== b.handRaised) return a.handRaised ? -1 : 1;
    if (a.host !== b.host) return a.host ? -1 : 1;
    if (a.self !== b.self) return a.self ? -1 : 1;
    const at = a.joinedAt ? Date.parse(a.joinedAt) : Number.MAX_SAFE_INTEGER;
    const bt = b.joinedAt ? Date.parse(b.joinedAt) : Number.MAX_SAFE_INTEGER;
    if (Number.isFinite(at) && Number.isFinite(bt) && at !== bt) return at - bt;
    return a.name.localeCompare(b.name, 'zh-Hans-CN');
  });
}

/**
 * ★「全员静音」的目标：还在说话的人，不含自己。
 *
 * <p>★为什么排除自己：主持人点了全员静音之后通常还要继续讲，
 * 把自己也静音等于"按钮生效了、但我说不出话"，他还得再手动开一次麦。
 * 飞书同样是保留主持人。
 */
export function muteAllTargets(rows: readonly MeetingParticipantRow[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const row of rows) {
    if (row.self || row.micMuted || row.userId == null) continue;
    if (seen.has(row.userId)) continue;
    seen.add(row.userId);
    out.push(row.userId);
  }
  return out;
}

/** 面板标题上的人数：按"人"算，不是按席位算。 */
export function participantCount(rows: readonly MeetingParticipantRow[]): number {
  return rows.length;
}

/**
 * 还能被静音的人数（用于按钮文案与是否可用）。
 *
 * <p>★必须和 {@link muteAllTargets} 用同一口径：按钮上写"全员静音(2)"、
 * 点下去只静音 1 个，用户会以为漏人了。所以外部接入的参与者（没有 userId，
 * 接口不接受）不计入。
 */
export function unmutedCount(rows: readonly MeetingParticipantRow[]): number {
  return rows.filter((r) => !r.self && !r.micMuted && r.userId != null).length;
}

/**
 * 能否对这个人执行管理动作：主持人 + 不是自己。
 *
 * <p>★不再要求 {@code userId != null}：游客（{@code guest-xxx}）同样可能捣乱，
 * 主持人必须能静音/移出他们。操作目标改由 {@link MeetingParticipantRow.target}
 * 提供（登录成员 = userId，游客 = identity），服务端两种标识都接受。
 */
export function canManageParticipant(amHost: boolean, row: MeetingParticipantRow): boolean {
  return amHost && !row.self && row.target !== '';
}

/** 头像里的首字（中文取首字，英文名取首字母大写）。 */
export function participantInitial(name: string): string {
  const s = (name ?? '').trim();
  if (!s) return '?';
  return s.slice(0, 1).toUpperCase();
}

/** 端类型的中文标签（面板里只在多端时展示）。 */
export function platformLabel(platform: string): string {
  const map: Record<string, string> = {
    web: '网页',
    ios: 'iOS',
    android: '安卓',
    harmonyos: '鸿蒙',
    desktop: '桌面端',
    miniapp: '小程序',
    // ★免登录入会的访客（identity = guest-{uuid}）：有个中文标签，
    //   否则多端角标会直接显示英文 "guest"。
    guest: '访客',
  };
  return map[platform] ?? platform;
}
