import { unavailableTasksProvider } from './api/conversationTasks';
import {
  createTasksMockProvider,
  tasksMockScenario,
} from './dev/conversationTasksMock';
import { tasksMockEnabled } from './lib/conversationTasks';

/** URL 只在显式开启的开发 fixture 内选场景；正式 bundle 不接受运行期启用 mock。 */
export const conversationTasksProvider =
  import.meta.env.DEV &&
  tasksMockEnabled(true, import.meta.env.VITE_IM_TASKS_MOCK)
    ? createTasksMockProvider(
        tasksMockScenario(
          new URLSearchParams(window.location.search).get('tasksScenario'),
        ),
      )
    : unavailableTasksProvider;
