/**
 * ★★「会议详情」弹框里的内容 —— 用户 2026-11-07 的最终口径：
 *
 * <blockquote>
 * 「会议详情的弹框不是新浏览器窗口弹框，页面内弹框」
 * </blockquote>
 *
 * <p>宿主在 {@code lib/meetingDetailDialog.tsx}（模块级单例 + 遮罩），本文件只管内容。
 *
 * <h2>★★为什么这个文件里一个 antd 组件都没有</h2>
 *
 * <p>它要能在**任何 document** 里长对：会中界面会被渲染进独立窗口
 * （见 {@code lib/meetingWindow.ts}），那边没有 antd v5 的 cssinjs 样式
 * （样式只在主文档 head 里注入）——{@code <Button>} 会是一颗裸按钮，
 * {@code App.useApp()} 更是直接拿不到上下文。
 *
 * <p>所以这里只用项目自己的类 + 原生 {@code <button>}，删除也用行内二次确认，
 * 不弹 {@code Modal}。好处是同一份内容可以同时服务页面内弹框与会中窗口。
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { contactApi, convApi, meetingRecordApi } from '../api';
import type {
  MeetingRecordDetailView,
  MeetingRecordMemberView,
  MeetingReplayShareView,
} from '../api/types';
import { copyText } from '../lib/clipboard';
import { isGroupConv } from '../lib/convType';
import { buildReplayUrl, formatMeetingId, meetingDisplayTitle } from '../lib/meetingLink';
import type { ReplayFile, ReplayTranscript } from '../lib/meetingReplay';
import { notifyMeetingRecordDeleted } from '../lib/meetingRecordEvents';
import {
  deleteActionLabel,
  deleteConfirmText,
  detailNeedsPolling,
  meetingDurationText,
  meetingMetaText,
  meetingTimeText,
  recordingBadge,
  transcriptIsDone,
} from '../lib/meetingRecord';
import MeetingReplayView from './MeetingReplayView';
import { IconCallEntry, IconMaximize, IconMinimize, IconPhone, IconRefresh, IconTrash } from './icons';

/** 服务端 404（会议模块未启用）要给一句人话，而不是把 HTTP 状态甩给用户。 */
function humanError(e: unknown): string {
  const msg = e instanceof Error ? e.message : typeof e === 'string' ? e : '网络异常';
  if (/404|not found/i.test(msg)) return '会议功能未开启';
  return msg;
}

interface Props {
  meetingId: string;
  /** 标题栏在详情加载出来之前先显示的会议名（可省）。 */
  title?: string;
  /** 关闭弹框（右上角 ×）。 */
  onClose?: () => void;
  /** 删除成功：记录已经没了，弹框里也没有"列表"可回，直接关掉。 */
  onDeleted?: () => void;
  /**
   * 是否处于全屏（撑满视口）。
   *
   * <p>★状态放在宿主 {@code lib/meetingDetailDialog} 里：宽度在 {@code .mtg-dialog}、
   * 高度在 {@code .mtg-window}，两者都在本组件之外，组件自己改不到。
   */
  fullscreen?: boolean;
  /** 切换全屏。不传则不显示全屏按钮（宿主以外的用法不该凭空多一个死按钮）。 */
  onToggleFullscreen?: () => void;
}

export default function MeetingDetailDialog({
  meetingId,
  title,
  onClose,
  onDeleted,
  fullscreen = false,
  onToggleFullscreen,
}: Props) {
  const [detail, setDetail] = useState<MeetingRecordDetailView | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [removing, setRemoving] = useState(false);
  /** ★删除是行内二次确认：第一次点击只是把按钮换成「确认删除 / 取消」。 */
  const [confirming, setConfirming] = useState(false);
  const [flash, setFlash] = useState<{ text: string; fail?: boolean } | null>(null);
  const flashTimer = useRef<number | null>(null);
  /** 后台刷新是否在途（防 5 秒定时器把请求叠起来）。 */
  const silentBusy = useRef(false);

  const showFlash = useCallback((text: string, fail = false) => {
    setFlash({ text, fail });
    if (flashTimer.current != null) window.clearTimeout(flashTimer.current);
    flashTimer.current = window.setTimeout(() => setFlash(null), 2200);
  }, []);

  useEffect(
    () => () => {
      if (flashTimer.current != null) window.clearTimeout(flashTimer.current);
    },
    [],
  );

  /**
   * ★{@code silent} = 后台刷新：不置 loading、不动播放器，只把最新详情换进来。
   *
   * <p>转写是异步流水线，状态会自己往前走（准备 → 提取 → 提交 → 识别 → 完成）。
   * 以前这个弹框只在挂载时拉一次，用户看到的就是打开那一刻的旧状态，
   * 一直停在「准备识别」，只能手动点刷新才知道早就识别完了。
   */
  const load = useCallback(async (silent = false) => {
    // ★上一轮还没回来就别再发：后台刷新每 5 秒一次，网络一慢请求会叠起来。
    if (silent && silentBusy.current) return;
    if (silent) silentBusy.current = true;
    if (!silent) {
      setLoading(true);
      setError(null);
    }
    try {
      const d = await meetingRecordApi.detail(meetingId);
      setDetail(d);
    } catch (e) {
      // 后台刷新失败不打扰用户：下一轮还会再试，别把已经展示好的详情打回错误页。
      if (!silent) setError(humanError(e));
    } finally {
      if (silent) silentBusy.current = false;
      else setLoading(false);
    }
  }, [meetingId]);

  useEffect(() => {
    void load();
  }, [load]);

  /**
   * ★还有东西没跑完 → 每 5 秒静默拉一次详情，跑到终态自动停。
   *
   * <p>覆盖两类"会自己变"的状态：转写 1/2/3/4（准备、提取、提交、识别）和录制文件
   * status=1（Egress 还在写文件）。收藏到布尔值再进依赖，避免每轮详情换新对象就把
   * 定时器重建一遍；页面在后台标签页时跳过，不白烧请求。
   */
  const stillProcessing = detailNeedsPolling(detail);

  useEffect(() => {
    if (!stillProcessing) return;
    const timer = window.setInterval(() => {
      if (document.visibilityState === 'hidden') return;
      void load(true);
    }, 5000);
    return () => window.clearInterval(timer);
  }, [stillProcessing, load]);

  const meeting = detail?.meeting;
  /**
   * ★是不是主持人 —— 决定删除的影响范围（服务端只认 `hostUserId`，这里只是把
   * 它的口径如实展示出来，别让参会人以为自己能删掉别人的记录）。
   */
  const isHost = meeting?.host === true;
  // ★详情没回来之前先用调用方传进来的会议名，弹框标题不会先闪一下「会议详情」。
  const displayTitle = meeting
    ? meetingDisplayTitle(meeting.title, meeting.roomName ?? detail?.roomName)
    : title || '会议详情';

  // ---------------------------------------------------------------- 回放

  /** 可回放的文件：只有 READY（生成中/失败的文件签不出地址）。 */
  const replayFiles: ReplayFile[] = (detail?.files ?? [])
    .filter((f) => (f.status ?? 2) === 2)
    .map((f) => ({
      id: f.id,
      filename: f.filename,
      contentType: f.contentType,
      durationSec: f.durationSec,
      sizeBytes: f.sizeBytes,
      status: f.status,
    }));

  /**
   * 回放用的转写：只保留「识别完成 + 有句子」的，且归属的文件必须可播。
   *
   * <p>★转写的 {@code beginMs} 是<b>相对所属文件开头</b>的毫秒 —— 文件不可播时
   * 把它的句子混进来，点击跳转会全部落到别的文件上，表现为"点哪句都不对"。
   */
  const replayTranscripts: ReplayTranscript[] = (detail?.transcripts ?? [])
    .filter((t) => !t.sourceFileId || replayFiles.some((f) => f.id === t.sourceFileId))
    .map((t) => ({
      sourceFileId: t.sourceFileId,
      // ★状态必须带下去：右栏空态要靠它区分「正在识别」和「没有转写」。
      status: t.status,
      // ★句子只认「已完成」的：重试中的记录可能还挂着上一轮的旧分段，
      //   拼进时间轴会让点击跳到错的地方。空态文案由 status 负责解释。
      segments: transcriptIsDone(t.status) ? t.segments : [],
      // 详情页的 speakerNames 带 userId/source，这里只留名字（与播放器的口径一致）。
      speakerNames: Object.fromEntries(
        Object.entries(t.speakerNames ?? {}).map(([k, v]) => [k, v?.name ?? null]),
      ),
    }));

  const resolveReplayUrl = useCallback(
    async (fileId: string) => {
      const res = await meetingRecordApi.fileUrl(meetingId, fileId);
      return res.playUrl || res.url || '';
    },
    [meetingId],
  );

  /**
   * 分享区只给主持人、且会议已结束、且确实有可播录制时显示。
   *
   * <p>★进行中不给：Egress 还在往同一个对象追加写，这时签出去的链接播到一半就断，
   * 用户会以为"回放坏了"。服务端也会拒（{@code status != 2}）。
   */
  const canShareReplay = isHost && meeting?.status === 2 && replayFiles.length > 0;

  /**
   * ★非主持人、且服务端明确判定"看不到回放"。
   *
   * <p>{@code replayVisible} 缺省（旧服务端 / 字段未下发）时按<b>可见</b>处理：
   * 字段缺失不是"没权限"的证据，凭它锁掉播放器会误伤。
   * {@code replayShared} 只用来区分文案：是"还没分享"还是"分享了但没带你"。
   */
  const replayLocked = !isHost && detail?.replayVisible === false;

  /**
   * ★下载 = 向服务端现签一个 attachment 地址（同一个对象，只换响应头）。
   *
   * <p>播放用的 inline 地址与下载用的 attachment 地址必须分开签：把 inline 地址
   * 塞进 {@code <a download>} 在跨域对象存储上会被忽略，浏览器直接打开视频页。
   */
  const resolveReplayDownloadUrl = useCallback(
    async (fileId: string) => {
      const res = await meetingRecordApi.fileUrl(meetingId, fileId);
      return { url: res.downloadUrl || res.url || '', filename: res.filename ?? null };
    },
    [meetingId],
  );

  const doRemove = useCallback(async () => {
    setRemoving(true);
    try {
      await meetingRecordApi.remove(meetingId);
      /**
       * ★先广播再关框：会议栏的历史记录可能不是本次打开的入口（系统消息里也能打开
       * 这个弹框），靠回调只能覆盖一条路径 —— 广播才能让所有在看的列表都消失掉。
       */
      notifyMeetingRecordDeleted(meetingId);
      onDeleted?.();
    } catch (e) {
      showFlash(humanError(e), true);
      setConfirming(false);
    } finally {
      setRemoving(false);
    }
  }, [meetingId, onDeleted, showFlash]);

  /**
   * ★删除入口挪到窗口标题栏：信息卡里那一整行「虚线 + 右对齐红按钮」在 1080 宽的
   * 弹框里显得又空又吵，而删除是一次性的低频操作，配不上固定占一行。
   * 这里只负责"开始删除"：进行中的会议先拦下，真正删除还要在卡片底部再确认一次。
   */
  const startRemove = useCallback(() => {
    if (!meeting) return;
    if (meeting.status === 1) {
      showFlash('会议还在进行中，请先「结束会议」再删除', true);
      return;
    }
    setConfirming(true);
  }, [meeting, showFlash]);

  return (
    // ★is-replay：外层 .mtg-dialog 靠它用 :has() 放宽宽度（内容是左右分栏的回放）
    <div className="mtg-window is-replay">
      <header className="mtg-window-head">
        <span className="mtg-window-title" title={displayTitle}>
          {displayTitle}
        </span>
        {meeting && !confirming && (
          <button
            type="button"
            className="mtg-window-icon is-danger"
            title={deleteActionLabel(isHost)}
            aria-label={deleteActionLabel(isHost)}
            onClick={startRemove}
          >
            <IconTrash size={15} />
          </button>
        )}
        {/* ★标题栏动作区统一成 28×28 图标按钮（与右侧「×」同一套描边）：
            文字「刷新」在 1080 宽的标题栏里比图标更抢眼，而它是个低频动作。 */}
        <button
          type="button"
          className="mtg-window-btn mtg-window-icon-btn"
          title="刷新"
          aria-label="刷新"
          onClick={() => void load()}
        >
          <IconRefresh size={15} />
        </button>
        {onToggleFullscreen && (
          <button
            type="button"
            className="mtg-window-btn mtg-window-icon-btn"
            title={fullscreen ? '退出全屏' : '全屏'}
            aria-label={fullscreen ? '退出全屏' : '全屏'}
            aria-pressed={fullscreen}
            onClick={onToggleFullscreen}
          >
            {fullscreen ? <IconMinimize size={15} /> : <IconMaximize size={15} />}
          </button>
        )}
        <button type="button" className="mtg-window-x" title="关闭" aria-label="关闭" onClick={() => onClose?.()}>
          ×
        </button>
      </header>

      <div className="mtg-window-body">
        {loading && <div className="mtg-center mtg-empty-inline">正在加载会议详情…</div>}
        {!loading && error != null && (
          <div className="mtg-error">
            {error}
            <button type="button" className="mtg-btn" onClick={() => void load()}>
              重试
            </button>
          </div>
        )}
        {!loading && error == null && !meeting && (
          <div className="mtg-center mtg-empty-inline">这条会议记录已不存在</div>
        )}

        {!loading && error == null && meeting && (
          <>
            <div className="mtg-card">
              {/* ★标题只留窗口头一处：卡片里再写一遍"会议 938 465 462"，
                  等于同一句话在同一屏出现两次，也是这个弹框"看着乱"的主要来源。
                  卡片只负责事实（类型 / 时长 / 人数 / 会议号 / 时间），不再当第二个标题。 */}
              <div className="mtg-detail-head">
                <span className="mtg-icon">
                  {meeting.origin === 2 ? <IconPhone size={18} /> : <IconCallEntry size={18} />}
                </span>
                <div className="mtg-detail-head-main">
                  <div className="mtg-meta">
                    {meetingMetaText({ ...meeting, memberCount: undefined })}
                  </div>
                </div>
                {/* ★录制已保存、转写还在跑时显示「录制转写中」——
                    只看 recordStatus 会让人以为这单活已经彻底干完了。 */}
                <Badge
                  b={recordingBadge(
                    meeting.recordStatus,
                    (detail?.transcripts ?? []).map((t) => t.status),
                  )}
                />
              </div>

              <dl className="mtg-kv">
                <div>
                  <dt>会议号</dt>
                  <dd>{meetingDisplayRoom(meeting.roomName ?? detail?.roomName)}</dd>
                </div>
                <div>
                  <dt>状态</dt>
                  <dd>{meeting.statusText || statusFallback(meeting.status)}</dd>
                </div>
                <div>
                  <dt>开始时间</dt>
                  <dd>{meetingTimeText(meeting.startTime) || '—'}</dd>
                </div>
                <div>
                  <dt>结束时间</dt>
                  <dd>{meetingTimeText(meeting.endTime) || '—'}</dd>
                </div>
                <div>
                  <dt>时长</dt>
                  <dd>{meetingDurationText(meeting) || '—'}</dd>
                </div>
              </dl>

              {/* ★参会人并进信息卡：它本来就是这个会议的属性，单开一个小节标题
                  只会让"参会人 / 回放 / 分享回放"三行灰字挤在一起。 */}
              <div className="mtg-members-row">
                <span className="mtg-members-label">
                  参会人 {detail?.members?.length ?? meeting.memberCount ?? 0}
                </span>
                <div className="mtg-members">
                  {(detail?.members ?? []).map((m: MeetingRecordMemberView, i: number) => (
                    <span className="mtg-member" key={`${m.userId ?? 'u'}-${i}`}>
                      {m.displayName || '未命名'}
                      {m.role === 2 && <em>主持人</em>}
                    </span>
                  ))}
                  {(detail?.members?.length ?? 0) === 0 && (
                    <span className="mtg-empty-inline">无参会人记录</span>
                  )}
                </div>
              </div>

              {/* ★确认条只在待确认时出现：常态下这里不再固定占一行。 */}
              {confirming && (
                <div className="mtg-detail-actions">
                  <span className="mtg-confirm-text">{deleteConfirmText(isHost)}</span>
                  <button
                    type="button"
                    className="mtg-btn"
                    onClick={() => setConfirming(false)}
                    disabled={removing}
                  >
                    取消
                  </button>
                  <button
                    type="button"
                    className="mtg-btn is-danger"
                    onClick={() => void doRemove()}
                    disabled={removing}
                  >
                    <IconTrash size={13} />
                    {removing ? '删除中…' : isHost ? '确认删除会议' : '确认删除'}
                  </button>
                </div>
              )}
            </div>

            {/* ★只保留回放一块：这块在宽屏下会被拉伸吃掉剩余高度
                （见 styles.css 的 is-replay 规则），让播放控制留在首屏。 */}
            <div className="mtg-replay">
              {replayLocked ? (
                <ReplayLocked shared={detail?.replayShared === true} />
              ) : (
                <MeetingReplayView
                  files={replayFiles}
                  transcripts={replayTranscripts}
                  resolveUrl={resolveReplayUrl}
                  resolveDownloadUrl={resolveReplayDownloadUrl}
                  emptyText="这场会议没有可回放的录制"
                />
              )}
            </div>

            {canShareReplay && (
              <div className="mtg-share">
                <div className="mtg-share-head">分享回放</div>
                <ReplaySharePanel
                  meetingId={meetingId}
                  members={detail?.members ?? []}
                  showFlash={showFlash}
                />
              </div>
            )}

          </>
        )}
      </div>

      {flash && <div className={`mtg-window-flash${flash.fail ? ' is-fail' : ''}`}>{flash.text}</div>}
    </div>
  );
}

// ---------------------------------------------------------------- 小组件

function Badge({ b }: { b: { text: string; tone: string } }) {
  return <span className={`mtg-badge mtg-badge-${b.tone}`}>{b.text}</span>;
}

function statusFallback(status?: number): string {
  switch (status) {
    case 0:
      return '未开始';
    case 1:
      return '进行中';
    case 2:
      return '已结束';
    case 3:
      return '已取消';
    default:
      return '—';
  }
}

/** 会议号：9 位按 3-3-3 分组展示（与列表/会中口径一致）。 */
function meetingDisplayRoom(room?: string | null): string {
  return formatMeetingId(room ?? '') || '—';
}

/**
 * ★非主持人的「看不到回放」占位。
 *
 * <p>★不能只显示"没有录制"：本场确实录了、只是没分享给他 ——
 * 那种文案会让人以为录像坏了。服务端通过 {@code replayShared} 给出事实，
 * 这里据此分两句话讲，并告诉用户下一步找谁。
 */
function ReplayLocked({ shared }: { shared: boolean }) {
  return (
    <div className="rp-locked">
      <span className="rp-locked-icon" aria-hidden="true">
        <svg
          viewBox="0 0 24 24"
          width="22"
          height="22"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.6"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <rect x="4.5" y="10.5" width="15" height="10" rx="2.5" />
          <path d="M8 10.5V8a4 4 0 0 1 8 0v2.5" />
        </svg>
      </span>
      <p className="rp-locked-title">
        {shared ? '主持人已分享回放，但可见范围里没有你' : '主持人暂未分享本场回放'}
      </p>
      <p className="rp-locked-hint">
        {shared
          ? '回放只对主持人指定的人开放。需要观看的话，请联系主持人把你加进分享范围。'
          : '在主持人分享之前，只有他自己可以看到本场的录像与转写。'}
      </p>
    </div>
  );
}

/** 分享范围取值（与服务端 {@code MeetingReplayScope} 一一对应，不能随便改）。 */
const REPLAY_SCOPE_EVERYONE = 0;
const REPLAY_SCOPE_MEMBERS = 1;
const REPLAY_SCOPE_SPECIFIED = 2;
/**
 * ★历史取值「指定联系人」。2026-11-09 用户明确「指定联系人好像没什么必要」，
 * 界面不再提供这一档；这里只在读取旧分享时把 3 归并到「指定人员」，
 * 否则老数据回填到没有对应 option 的 select 里会显示成空白。
 */
const REPLAY_SCOPE_LEGACY_CONTACTS = 3;
/** 与服务端 {@code REPLAY_SCOPE_USERS_MAX} 一致，前端先拦一道，省一次失败往返。 */
const REPLAY_SCOPE_MAX_USERS = 200;
/** 与服务端 {@code REPLAY_SCOPE_GROUPS_MAX} 一致（判权要逐个群查成员，必须封顶）。 */
const REPLAY_SCOPE_MAX_GROUPS = 20;

/**
 * ★三档，不再有「指定联系人」：用户 2026-11-09 判定这一档没必要 ——
 * 「指定人员或群聊」本来就能挑联系人，独立一档只多一个入口、少一种能力。
 */
const REPLAY_SCOPE_OPTIONS = [
  { value: REPLAY_SCOPE_MEMBERS, label: '参会人员', hint: '本场会议的全体参会人（默认）' },
  {
    value: REPLAY_SCOPE_SPECIFIED,
    label: '指定人员或群聊',
    hint: '从参会人、联系人或群聊里单独挑选',
  },
  { value: REPLAY_SCOPE_EVERYONE, label: '所有人', hint: '任何登录用户拿到链接都能看' },
] as const;

interface PeerOption {
  /** ★IM subject id（真人 = 平台 userId），只当不透明标识用。 */
  userId: string;
  name: string;
}

/** 可分享的群：选中 = 该群全部活跃成员都能看（服务端判权时现查成员关系）。 */
interface GroupOption {
  convId: string;
  name: string;
  memberCount?: number;
}

/**
 * ★★「分享回放」面板（仅主持人可见，宿主已判过会议状态与文件可用性）。
 *
 * <h2>★★没分享 = 只有主持人能看</h2>
 *
 * <p>回放默认不对外：未分享时除主持人外谁也看不到（服务端 {@code detail} 会直接
 * 把文件与转写过滤成空数组）。所以这里第一件事不是"生成链接"，而是选<b>给谁看</b>。
 *
 * <h2>为什么把链接当成"凭证"来对待</h2>
 *
 * <p>服务端签出去的是一条 {@code ?replay=<token>} 的链接：拿到它的人<b>登录后</b>、
 * 且<b>落在分享范围内</b>才能看整场录像。所以文案仍要说清"别转发到公开场合"，
 * 并且<b>随时可撤销</b>——撤销后旧链接立刻失效（服务端清 token，不是靠前端藏按钮）。
 *
 * <h2>★「保存」与「重新生成」是两个不同的动作</h2>
 *
 * <p>已有链接时调整范围 / 有效期走「保存设置」：<b>token 不变</b>，刚发到群里的那条
 * 还能用；要换链接必须显式点「重新生成」，旧链接随即失效。
 */
function ReplaySharePanel({
  meetingId,
  members,
  showFlash,
}: {
  meetingId: string;
  members: MeetingRecordMemberView[];
  showFlash: (text: string, fail?: boolean) => void;
}) {
  const [share, setShare] = useState<MeetingReplayShareView | null>(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  /** 新链接的有效期（天）：7 = 默认；0 = 永久。 */
  const [days, setDays] = useState(7);
  /** 分享范围，默认「参会人员」——新建时取最小可用范围，避免误分享给全场。 */
  const [scope, setScope] = useState<number>(REPLAY_SCOPE_MEMBERS);
  /** 指定人员时的已选 userId。 */
  const [picked, setPicked] = useState<string[]>([]);
  /** ★已选群（会话 id），只有「指定人员」范围才有意义。 */
  const [pickedGroups, setPickedGroups] = useState<string[]>([]);
  const [contacts, setContacts] = useState<PeerOption[]>([]);
  const [contactsLoading, setContactsLoading] = useState(false);
  const [contactsError, setContactsError] = useState<string | null>(null);
  const [groups, setGroups] = useState<GroupOption[]>([]);
  const [groupsLoading, setGroupsLoading] = useState(false);
  const [groupsError, setGroupsError] = useState<string | null>(null);
  /** ★群太多没取全时要说出来：静默截断会让人以为"某个群不在我的群列表里"。 */
  const [groupsTruncated, setGroupsTruncated] = useState(false);
  /** 选人下拉是否展开 + 搜索词（下拉里才占地方，收起时只留一行）。 */
  const [pickerOpen, setPickerOpen] = useState(false);
  const [query, setQuery] = useState('');
  const pickerRef = useRef<HTMLDivElement | null>(null);
  const [error, setError] = useState<string | null>(null);
  /**
   * ★权限设置弹框（用户 2026-11-09：「分享有点占位置了，加个权限设置按钮点击弹出框」）。
   * 范围 / 选人 / 有效期全部搬进弹框，面板上只留一行摘要 + 一个入口。
   */
  const [settingsOpen, setSettingsOpen] = useState(false);
  /** ★Esc 要挂弹框自己的 document —— 会中那扇独立窗口是另一个 document。 */
  const settingsRef = useRef<HTMLDivElement | null>(null);

  // 当前分享状态
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    meetingRecordApi
      .getReplayShare(meetingId)
      .then((v) => {
        if (cancelled) return;
        setShare(v);
        if (v.active) {
          // 老数据里的「指定联系人」（3）归并到「指定人员」，否则下拉显示空白
          setScope(
            v.scope === REPLAY_SCOPE_LEGACY_CONTACTS
              ? REPLAY_SCOPE_SPECIFIED
              : (v.scope ?? REPLAY_SCOPE_MEMBERS),
          );
          setPicked(v.scopeUserIds ?? []);
          setPickedGroups(v.scopeGroupIds ?? []);
          // ★永久链接要回填成「永久」，否则一保存就悄悄变成 7 天。
          if (!v.expiresAt) setDays(0);
        }
      })
      .catch((e: unknown) => {
        if (!cancelled) setError(humanError(e));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [meetingId]);

  // 联系人候选（只取「已接受」的真人和非智能体；智能体的 id 是虚拟身份，不能选）
  useEffect(() => {
    let cancelled = false;
    setContactsLoading(true);
    contactApi
      .list()
      .then((res) => {
        if (cancelled) return;
        setContacts(
          (res.items ?? [])
            .filter((c) => c.status === 1 && c.subjectType !== 2 && !!c.userId)
            .map((c) => ({
              userId: String(c.userId),
              name: c.displayName || c.remark || c.nickName || c.userName || String(c.userId),
            })),
        );
      })
      .catch(() => {
        if (!cancelled) setContactsError('通讯录读取失败，暂时只能选参会人');
      })
      .finally(() => {
        if (!cancelled) setContactsLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  // ★群聊候选：只有"我还在里面"的群能选（服务端同样按这条校验）。
  //   在挂载时就取一次，保证"已分享的群"能在收起状态下显示出群名而不是一串 id。
  useEffect(() => {
    let cancelled = false;
    setGroupsLoading(true);
    convApi
      .myGroups(undefined, 100)
      .then((res) => {
        if (cancelled) return;
        const out: GroupOption[] = [];
        for (const c of res.records ?? []) {
          if (!isGroupConv(c.convType) || c.convId == null) continue;
          out.push({
            convId: String(c.convId),
            name: c.name || '群聊',
            memberCount: c.memberCount,
          });
        }
        setGroups(out);
        setGroupsTruncated(res.hasMore === true);
      })
      .catch(() => {
        if (!cancelled) setGroupsError('群聊列表读取失败，暂时只能选人');
      })
      .finally(() => {
        if (!cancelled) setGroupsLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  // ★点空白处收起选人下拉（原生 details 的收起行为不够稳，自己判一次）。
  //   用元素自己的 ownerDocument：本面板会被渲染进会中那扇独立窗口。
  useEffect(() => {
    if (!pickerOpen) return;
    const el = pickerRef.current;
    if (!el) return;
    const doc = el.ownerDocument;
    const onDown = (e: Event) => {
      if (!el.contains(e.target as Node)) setPickerOpen(false);
    };
    doc.addEventListener('mousedown', onDown);
    return () => doc.removeEventListener('mousedown', onDown);
  }, [pickerOpen]);

  /**
   * ★参会人候选：排除主持人自己（他永远能看，列出来只是噪音），按 userId 去重。
   */
  const memberOptions = useMemo<PeerOption[]>(() => {
    const seen = new Set<string>();
    const out: PeerOption[] = [];
    for (const m of members) {
      if (!m.userId || m.role === 2) continue;
      const id = String(m.userId);
      if (seen.has(id)) continue;
      seen.add(id);
      out.push({ userId: id, name: m.displayName || '参会人' });
    }
    return out;
  }, [members]);

  const memberIdSet = useMemo(
    () => new Set(memberOptions.map((o) => o.userId)),
    [memberOptions],
  );
  /** 同时也在本场参会人里的联系人不在「联系人」组重复出现（参会人组已经有一位）。 */
  const contactOptions = useMemo(
    () => contacts.filter((c) => !memberIdSet.has(c.userId)),
    [contacts, memberIdSet],
  );
  const active = share?.active === true && !!share.token;
  /** ★「指定人员或群聊」是唯一需要挑名单的范围。 */
  const needUsers = scope === REPLAY_SCOPE_SPECIFIED;
  /** 群和个人在同一个范围里挑，所以两者同开同关。 */
  const canPickGroups = needUsers;

  const q = query.trim().toLowerCase();
  const matches = useCallback(
    (name: string) => !q || name.toLowerCase().includes(q),
    [q],
  );
  const shownMembers = useMemo(
    () => memberOptions.filter((o) => matches(o.name)),
    [memberOptions, matches],
  );
  const shownContacts = useMemo(
    () => contactOptions.filter((o) => matches(o.name)),
    [contactOptions, matches],
  );
  const shownGroups = useMemo(
    () => groups.filter((g) => matches(g.name)),
    [groups, matches],
  );

  /** 已选里的人 / 群在收起状态下要显示名字：未知 id 直接显示 id，不假装"没有选择"。 */
  const pickedLabel = useMemo(() => {
    const names = new Map<string, string>();
    for (const o of memberOptions) names.set(o.userId, o.name);
    for (const o of contacts) names.set(o.userId, o.name);
    for (const g of groups) names.set(`g:${g.convId}`, g.name);
    const parts: string[] = [];
    if (picked.length > 0) {
      const first = picked.slice(0, 2).map((id) => names.get(id) || id).join('、');
      parts.push(picked.length > 2 ? `${first} 等 ${picked.length} 人` : first);
    }
    if (canPickGroups && pickedGroups.length > 0) {
      const first = pickedGroups.slice(0, 1).map((id) => names.get(`g:${id}`) || id).join('、');
      parts.push(pickedGroups.length > 1 ? `${first} 等 ${pickedGroups.length} 个群` : first);
    }
    return parts.join(' · ');
  }, [canPickGroups, contacts, groups, memberOptions, picked, pickedGroups]);

  /**
   * ★链接用<b>主页面</b>的地址拼。会中窗口是 {@code about:blank}（见
   * {@code lib/meetingWindow.ts}），拿那个 document 的 location 会拼出
   * {@code about:blank/?replay=…} —— 一条谁都打不开的链接。
   */
  const link = active ? buildReplayUrl(window.location.href, share?.token ?? '') : '';

  /** 切换范围时不清空已选名单：切过去再切回来，选的人还在。 */
  const changeScope = useCallback((next: number) => {
    setScope(next);
    setError(null);
  }, []);

  /**
   * 打开权限设置：把草稿重置成"当前已保存的设置"。
   * 不重置的话，上次点了取消留下的改动会在下次打开时继续显示，像已经生效了。
   */
  const openSettings = useCallback(() => {
    if (share?.active) {
      setScope(
        share.scope === REPLAY_SCOPE_LEGACY_CONTACTS
          ? REPLAY_SCOPE_SPECIFIED
          : (share.scope ?? REPLAY_SCOPE_MEMBERS),
      );
      setPicked(share.scopeUserIds ?? []);
      setPickedGroups(share.scopeGroupIds ?? []);
    } else {
      setScope(REPLAY_SCOPE_MEMBERS);
      setPicked([]);
      setPickedGroups([]);
      setDays(7);
    }
    setQuery('');
    setPickerOpen(false);
    setError(null);
    setSettingsOpen(true);
  }, [share]);

  const closeSettings = useCallback(() => {
    setPickerOpen(false);
    setSettingsOpen(false);
  }, []);

  const togglePick = useCallback((id: string) => {
    setPicked((prev) => {
      if (prev.includes(id)) return prev.filter((x) => x !== id);
      if (prev.length >= REPLAY_SCOPE_MAX_USERS) return prev;
      return [...prev, id];
    });
  }, []);

  const toggleGroup = useCallback((convId: string) => {
    setPickedGroups((prev) => {
      if (prev.includes(convId)) return prev.filter((x) => x !== convId);
      if (prev.length >= REPLAY_SCOPE_MAX_GROUPS) return prev;
      return [...prev, convId];
    });
  }, []);

  /** @returns 是否真的写成功了（权限设置弹框据此决定关不关）。 */
  const submit = useCallback(
    async (regenerate: boolean): Promise<boolean> => {
      // ★只选群不选人是合法配置：整群人可见；两个都空才拦。
      const groupsForSubmit = canPickGroups ? pickedGroups : [];
      if (needUsers && picked.length === 0 && groupsForSubmit.length === 0) {
        const text = '请至少选择一位参会人、联系人或群聊';
        setError(text);
        showFlash(text, true);
        return false;
      }
      setBusy(true);
      setError(null);
      try {
        const v = await meetingRecordApi.createReplayShare(meetingId, {
          expiresInDays: days,
          scope,
          userIds: needUsers ? picked : null,
          groupIds: groupsForSubmit.length > 0 ? groupsForSubmit : null,
          regenerate,
        });
        setShare(v);
        setScope(v.scope ?? scope);
        setPicked(v.scopeUserIds ?? []);
        setPickedGroups(v.scopeGroupIds ?? []);
        showFlash(
          regenerate
            ? '已生成新链接，旧链接立即失效'
            : active
              ? '分享设置已保存，链接不变'
              : '回放已分享',
        );
        return true;
      } catch (e) {
        const text = humanError(e);
        setError(text);
        showFlash(text, true);
        return false;
      } finally {
        setBusy(false);
      }
    },
    [active, canPickGroups, days, meetingId, needUsers, picked, pickedGroups, scope, showFlash],
  );

  /** 弹框里的「保存」：写成功才关，失败留在弹框里显示错误，别让用户以为存上了。 */
  const saveSettings = useCallback(async () => {
    const ok = await submit(false);
    if (ok) {
      setPickerOpen(false);
      setSettingsOpen(false);
    }
  }, [submit]);

  // 权限设置弹框开着时，Esc 只关弹框：捕获阶段先拦下，别让下层的会议详情面板一起关掉。
  useEffect(() => {
    if (!settingsOpen) return;
    const doc = settingsRef.current?.ownerDocument ?? document;
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== 'Escape') return;
      e.stopPropagation();
      setPickerOpen(false);
      setSettingsOpen(false);
    };
    doc.addEventListener('keydown', onKey, true);
    return () => doc.removeEventListener('keydown', onKey, true);
  }, [settingsOpen]);

  const revoke = useCallback(async () => {
    setBusy(true);
    setError(null);
    try {
      await meetingRecordApi.revokeReplayShare(meetingId);
      setShare({ meetingId, token: null, active: false, expiresAt: null, createdAt: null });
      showFlash('回放分享已撤销，旧链接立即失效');
    } catch (e) {
      const text = humanError(e);
      setError(text);
      showFlash(text, true);
    } finally {
      setBusy(false);
    }
  }, [meetingId, showFlash]);

  const copy = useCallback(async () => {
    if (!link) return;
    // ★复制目标可能是会中窗口（另一份 document），与详情里其它复制走同一份实现。
    const ok = await copyText(link);
    showFlash(ok ? '回放链接已复制' : '复制失败，请手动选中复制', !ok);
  }, [link, showFlash]);

  if (loading) {
    return <div className="mtg-empty-inline">正在读取分享设置…</div>;
  }

  return (
    <div className="rp-share">
      {active && (
        <>
          {/* ★链接与三个动作按钮：PC 同一行，窄屏整组换到下一行（用户 2026-11-09 截图反馈）。
              按钮先包一层 .rp-share-actions 再放进这一行，而不是直接丢进 .rp-share-row：
              那样 flex-wrap 会按剩余宽度把「复制链接」单独挤下去，按钮被拆成 2+1；
              包一层后按钮组是整体，只在断点处一起换行。 */}
          <div className="rp-share-line">
            <input
              className="rp-share-link"
              readOnly
              value={link}
              aria-label="回放链接"
              onFocus={(e) => e.currentTarget.select()}
            />
            <div className="rp-share-actions">
              <button type="button" className="mtg-btn" onClick={() => void copy()}>
                复制链接
              </button>
              <button
                type="button"
                className="mtg-btn"
                disabled={busy}
                onClick={() => void submit(true)}
              >
                {busy ? '处理中…' : '重新生成'}
              </button>
              <button
                type="button"
                className="mtg-btn is-danger"
                disabled={busy}
                onClick={() => void revoke()}
              >
                撤销分享
              </button>
            </div>
          </div>
        </>
      )}

      {/* ★面板上只留一行：谁可以看（摘要）+ 权限设置入口。
          范围 / 选人 / 有效期全搬进弹框 —— 用户 2026-11-09：「分享有点占位置了」。 */}
      <div className="rp-share-meta">
        <span className="rp-share-note">
          {active
            ? `${share?.scopeText || '参会人员'} · ${
                share?.expiresAt ? `有效期至 ${meetingTimeText(share.expiresAt)}` : '永久有效'
              } · 需登录后观看，请勿转发`
            : '未分享，只有你能看回放'}
        </span>
        <div className="rp-share-actions">
          <button type="button" className="mtg-btn" disabled={busy} onClick={openSettings}>
            权限设置
          </button>
          {!active && (
            <button
              type="button"
              className="mtg-btn is-primary"
              disabled={busy}
              onClick={() => void submit(false)}
            >
              {busy ? '处理中…' : '生成分享链接'}
            </button>
          )}
        </div>
      </div>

      {settingsOpen && (
        <div
          className="rp-modal-mask"
          ref={settingsRef}
          onMouseDown={(e) => {
            // 只有点在遮罩本身才关：弹框内部按下鼠标不该被当成"点外面"
            if (e.target === e.currentTarget) closeSettings();
          }}
        >
          <div className="rp-modal" role="dialog" aria-modal="true" aria-label="回放权限设置">
            <div className="rp-modal-head">
              <span className="rp-modal-title">回放权限设置</span>
              <button
                type="button"
                className="rp-modal-x"
                aria-label="关闭"
                onClick={closeSettings}
              >
                ×
              </button>
            </div>

            <div className="rp-modal-body">
              <div className="rp-field">
                <label className="rp-field-label" htmlFor={`replay-scope-${meetingId}`}>
                  谁可以看回放
                </label>
                <div className="rp-select-wrap">
                  <select
                    id={`replay-scope-${meetingId}`}
                    className="rp-select"
                    value={scope}
                    disabled={busy}
                    onChange={(e) => changeScope(Number(e.target.value))}
                  >
                    {REPLAY_SCOPE_OPTIONS.map((o) => (
                      <option key={o.value} value={o.value}>
                        {o.label}
                      </option>
                    ))}
                  </select>
                </div>
                <span className="rp-field-hint">
                  {REPLAY_SCOPE_OPTIONS.find((o) => o.value === scope)?.hint}
                </span>
              </div>

              {needUsers && (
                <div className="rp-field" ref={pickerRef}>
                  <span className="rp-field-label">选择人员或群聊</span>
                  <button
                    type="button"
                    className={`rp-picker-trigger${pickerOpen ? ' is-open' : ''}`}
                    disabled={busy}
                    aria-expanded={pickerOpen}
                    onClick={() => setPickerOpen((v) => !v)}
                  >
                    <span
                      className={`rp-picker-value${pickedLabel ? '' : ' is-empty'}`}
                      title={pickedLabel}
                    >
                      {pickedLabel || '未选择'}
                    </span>
                    <span className="rp-picker-caret" aria-hidden="true">
                      ▾
                    </span>
                  </button>

                  {pickerOpen && (
                    <div className="rp-picker-pop">
                      <input
                        className="rp-picker-search"
                        type="search"
                        placeholder="搜索姓名或群名"
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                      />
                      <div className="rp-picker-list">
                        <PickerGroup
                          title="参会人"
                          items={shownMembers.map((o) => ({ key: o.userId, name: o.name }))}
                          picked={picked}
                          max={REPLAY_SCOPE_MAX_USERS}
                          onToggle={togglePick}
                          emptyText={q ? '没有匹配的参会人' : '本场没有其他参会人'}
                        />
                        <PickerGroup
                          title="联系人"
                          items={shownContacts.map((o) => ({ key: o.userId, name: o.name }))}
                          picked={picked}
                          max={REPLAY_SCOPE_MAX_USERS}
                          onToggle={togglePick}
                          emptyText={
                            q
                              ? '没有匹配的联系人'
                              : contactsLoading
                                ? '正在读取通讯录…'
                                : contactsError || '通讯录里还没有可分享的联系人'
                          }
                        />
                        <PickerGroup
                          title="群聊"
                          items={shownGroups.map((g) => ({
                            key: g.convId,
                            name: g.name,
                            meta: g.memberCount ? `${g.memberCount} 人` : undefined,
                          }))}
                          picked={pickedGroups}
                          max={REPLAY_SCOPE_MAX_GROUPS}
                          onToggle={toggleGroup}
                          emptyText={
                            q
                              ? '没有匹配的群聊'
                              : groupsLoading
                                ? '正在读取群聊…'
                                : groupsError || '你还没有加入任何群聊'
                          }
                        />
                      </div>
                      {groupsTruncated && (
                        <div className="rp-picker-hint">群聊较多，仅列出最近 100 个</div>
                      )}
                      <div className="rp-picker-foot">
                        <span className="rp-picker-count">
                          已选 {picked.length} 人
                          {pickedGroups.length > 0 ? ` · ${pickedGroups.length} 个群` : ''}
                        </span>
                        <button
                          type="button"
                          className="mtg-btn"
                          onClick={() => setPickerOpen(false)}
                        >
                          完成
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              )}

              <div className="rp-field">
                <label className="rp-field-label" htmlFor={`replay-expiry-${meetingId}`}>
                  链接有效期
                </label>
                <div className="rp-select-wrap">
                  <select
                    id={`replay-expiry-${meetingId}`}
                    className="rp-select"
                    value={days}
                    disabled={busy}
                    onChange={(e) => setDays(Number(e.target.value))}
                  >
                    <option value={7}>7 天（默认）</option>
                    <option value={0}>永久有效</option>
                  </select>
                </div>
              </div>

              {error && <div className="rp-share-err">{error}</div>}
            </div>

            <div className="rp-modal-foot">
              <span className="rp-share-note">
                {active ? '保存后已发出的链接不变' : '保存后立即生成链接'}
              </span>
              <button type="button" className="mtg-btn" onClick={closeSettings}>
                取消
              </button>
              <button
                type="button"
                className="mtg-btn is-primary"
                disabled={busy}
                onClick={() => void saveSettings()}
              >
                {busy ? '处理中…' : '保存'}
              </button>
            </div>
          </div>
        </div>
      )}

      {error && !settingsOpen && <div className="rp-share-err">{error}</div>}
    </div>
  );
}

interface PickerItem {
  key: string;
  name: string;
  /** 右侧的次要信息（群聊显示人数）。 */
  meta?: string;
}

/**
 * 下拉里的一组可选项（参会人 / 联系人 / 群聊）。
 *
 * <p>★分组而不是混排：用户明确要求「默认参会人排在前面、联系人排在后面」，
 * 现在再加一档「群聊」——分组标题比一条分隔线更能让人一眼看出"这几拨不一样"，
 * 也避免群和个人混在一列里分不清。
 */
function PickerGroup({
  title,
  items,
  picked,
  max,
  onToggle,
  emptyText,
}: {
  title: string;
  items: PickerItem[];
  picked: string[];
  max: number;
  onToggle: (key: string) => void;
  emptyText: string;
}) {
  return (
    <div className="rp-peer-group">
      <div className="rp-peer-title">
        {title}
        <span className="rp-peer-count">{items.length}</span>
      </div>
      {items.length === 0 ? (
        <div className="rp-peer-empty">{emptyText}</div>
      ) : (
        <div className="rp-peer-list">
          {items.map((o) => {
            const on = picked.includes(o.key);
            const full = !on && picked.length >= max;
            return (
              <label className={`rp-peer${on ? ' is-on' : ''}${full ? ' is-full' : ''}`} key={o.key}>
                <input
                  type="checkbox"
                  checked={on}
                  disabled={full}
                  onChange={() => onToggle(o.key)}
                />
                <span className="rp-peer-name" title={o.name}>
                  {o.name}
                </span>
                {o.meta && <span className="rp-peer-meta">{o.meta}</span>}
              </label>
            );
          })}
        </div>
      )}
    </div>
  );
}
