import { useEffect, useState } from 'react';
import { Button, Input, Modal, Typography } from 'antd';
import { isImeConfirm } from '../lib/ime';
import {
  MAX_CUSTOM_TAB_ICON,
  MAX_CUSTOM_TAB_NAME,
  normalizeCustomTabIcon,
  validateCustomTabInput,
  type CustomTab,
} from '../lib/customTabs';
import { IconLink } from './icons';

/**
 * ★常用图标（2026-10-30 用户原话：「帮我增加 icon 字段，如果为空则展示当前的链接图标」）。
 *
 * <p>★只放"一眼能认出用途"的几个：文档 / 表格 / 目录 / 网页 / 智能体 / 星标 / 公告 / 对话 / 书。
 * ★不接整套 emoji picker：标签行只有 24px 高，用户在这里要的是"换个能区分的记号"，
 * 不是发一条表情。输入框仍然接受任意 emoji / 短字符。
 */
const ICON_PRESETS = ['📄', '📊', '📁', '🌐', '🤖', '⭐', '📌', '💬', '📚'];

/**
 * 「添加 / 编辑自定义链接」弹窗（用户 2026-10-27 原话：「添加标签页支持自定义链接」）。
 *
 * <h2>它只做三件事</h2>
 *
 * <ol>
 *   <li>收三个输入：名称（选填）+ 图标（选填，空 = 默认链接图标）+ 网址（必填）；</li>
 *   <li>把校验**整段委托**给 {@code lib/customTabs} 的 {@code validateCustomTabInput}
 *       —— 上限 / 协议 / 重复 / 长度都在那边，且由单测钉着。
 *       本组件里再写一份判断的话，两处迟早分叉，而分叉的表现是
 *       "弹窗说没问题、存进去却不对"（或者反过来：明明能存，弹窗拦着）；</li>
 *   <li>把归一后的 {@code name / url} 交给调用方（由它调接口），成功才关掉自己。</li>
 * </ol>
 *
 * <h2>★★为什么要等调用方（2026-10-30 会话级改造）</h2>
 *
 * <p>链接现在存在服务端，添加/修改都可能失败（无权限 {@code IM_30001}、
 * 上限 {@code IM_20110}、URL 被占用 {@code IM_20112}、网络不可达……）。
 * 以前是"先写本地 localStorage，永远成功"，现在必须在弹窗里等结果：
 * 提交期间按钮 loading，失败把服务端/网络的**原话**显示在输入框下面。
 *
 * <h2>★错误显示在弹窗里，不用 toast</h2>
 *
 * <p>toast 会在几秒后消失，而用户此刻正盯着输入框要改。错误必须留在原地看着。
 *
 * <h2>★重开时必须复位</h2>
 *
 * <p>弹窗是常挂载的（`open` 只是控制显隐）⇒ 组件不会卸载 ⇒ 上次输错的内容会留下来。
 * 这与 DEV-432「搜索框第二次打开还留着上次的关键词」是同一个坑，所以这里用
 * {@code useEffect(..., [open, ...])} 在每次打开时复位。
 * ★编辑模式下复位成"当前这条链接的值"（同一个弹窗承载两种模式，少一套组件就少一处分叉）。
 */
export default function AddLinkTabModal({
  open,
  existing,
  initial,
  onSubmit,
  onClose,
}: {
  open: boolean;
  /**
   * 判重 / 判上限的范围。
   * ★编辑模式下调用方必须传**去掉被编辑那一条**的列表 ——
   * 否则"什么都不改直接保存"会被自己的 URL 判成重复。
   */
  existing: readonly CustomTab[];
  /** 编辑模式下要回填的值；{@code null} / 不传 = 添加模式。 */
  initial?: { name: string; icon: string; url: string } | null;
  /** 校验通过后回调；调用方负责调接口。抛异常 = 失败（异常 message 会显示在弹窗里）。 */
  onSubmit: (input: { name: string; icon: string; url: string }) => Promise<void>;
  onClose: () => void;
}) {
  const editing = initial != null;
  const [name, setName] = useState('');
  const [icon, setIcon] = useState('');
  const [url, setUrl] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // ★每次打开都复位：理由见类注释「重开时必须复位」。
  //   依赖用 initial 的**原始值**而不是对象本身：调用方每次渲染都可能新建一个对象，
  //   拿对象做依赖会在输入过程中反复重置。
  useEffect(() => {
    if (!open) return;
    setName(initial?.name ?? '');
    setIcon(initial?.icon ?? '');
    setUrl(initial?.url ?? '');
    setError(null);
    setSubmitting(false);
  }, [open, initial?.name, initial?.icon, initial?.url]);

  // ★高亮判据用归一后的值：用户可能粘进来一个带空格的 emoji，
  //   不归一的话预设按钮会一个都不亮，看起来像"我没选中任何图标"。
  const currentIcon = normalizeCustomTabIcon(icon);

  const submit = async () => {
    if (submitting) return;
    const r = validateCustomTabInput(existing, name, url, icon);
    if (!r.ok) {
      setError(r.error);
      return;
    }
    setSubmitting(true);
    setError(null);
    try {
      await onSubmit({ name: r.name, icon: r.icon, url: r.url });
      onClose();
    } catch (e) {
      // ★服务端的 displayMessage 就是给用户看的；网络错误也有可读文案。
      setError((e as Error)?.message || '操作失败，请稍后重试');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Modal
      title={editing ? '编辑自定义链接' : '添加自定义链接'}
      open={open}
      onCancel={onClose}
      width={460}
      destroyOnClose={false}
      // ★★2026-10-30：必须**显式**高于「管理标签页」，否则从管理弹窗里点「编辑」时，
      //   本弹窗会被压在下面（用户原话「我点编辑，编辑框跑到后面去了」）。
      //   原因不是层叠写错，而是 antd 的默认 z-index（1000+100）对**所有** Modal 相同：
      //   两个弹窗谁在上，取决于它们的 portal 在 body 里的**插入顺序**，而这个顺序是
      //   各自**第一次打开**时定下的、之后不再变。本弹窗若先被「添加」路径打开过，
      //   它的 portal 就永远排在管理弹窗前面 ⇒ 后开的管理弹窗反而盖住它。
      //   ⇒ 两个弹窗都给固定值（管理 1000 / 本弹窗 1100），与打开先后无关。
      zIndex={1100}
      footer={[
        <Button key="cancel" onClick={onClose} disabled={submitting}>
          取消
        </Button>,
        <Button key="ok" type="primary" onClick={submit} loading={submitting}>
          {editing ? '保存' : '添加'}
        </Button>,
      ]}
    >
      <div className="add-link-form">
        <label className="add-link-label" htmlFor="add-link-name">
          名称
        </label>
        <Input
          id="add-link-name"
          value={name}
          maxLength={MAX_CUSTOM_TAB_NAME}
          placeholder="不填则使用网站域名"
          onChange={(e) => {
            setName(e.target.value);
            setError(null);
          }}
          // ★★DEV-254 纪律：输入法组合中（候选词浮框还在）按回车是**确认候选词**，
          //   不是提交。用户 2026-10-30 原话：「编辑框里输入文字时，输入法上有字母时
          //   回车直接就保存了」—— 这里漏掉了 {@link isImeConfirm}，与其它 5 处输入框
          //   用的不是同一套判据。判据见 lib/ime.ts（isComposing / keyCode=229 /
          //   compositionend 紧邻的裸 Enter 三种形态）。
          onPressEnter={(e) => {
            if (isImeConfirm(e)) return;
            submit();
          }}
        />
        <label className="add-link-label" htmlFor="add-link-icon">
          图标
        </label>
        {/* ★图标可选：「默认」= 空串，标签上显示链条图标（与加这个字段之前一模一样）。
            ★预设按钮 + 一个可粘贴的输入框：既省得用户去找 emoji，也不限制只能用预设。
            ★归一化（剥控制字符、去空白）在提交时由 validateCustomTabInput 统一做，
              这里只负责高亮 —— 组件里不写第二份规则。 */}
        <div className="add-link-icon-row" role="group" aria-label="选择标签图标">
          <button
            type="button"
            className={`add-link-icon-btn${currentIcon === '' ? ' active' : ''}`}
            title="默认链接图标"
            aria-label="默认链接图标"
            aria-pressed={currentIcon === ''}
            onClick={() => {
              setIcon('');
              setError(null);
            }}
          >
            <IconLink size={14} />
          </button>
          {ICON_PRESETS.map((preset) => (
            <button
              key={preset}
              type="button"
              className={`add-link-icon-btn${currentIcon === preset ? ' active' : ''}`}
              aria-label={`图标 ${preset}`}
              aria-pressed={currentIcon === preset}
              onClick={() => {
                setIcon(preset);
                setError(null);
              }}
            >
              {preset}
            </button>
          ))}
          <Input
            id="add-link-icon"
            className="add-link-icon-input"
            value={icon}
            maxLength={MAX_CUSTOM_TAB_ICON}
            placeholder="或粘贴 emoji"
            onChange={(e) => {
              setIcon(e.target.value);
              setError(null);
            }}
            // ★同上：输入法组词中的回车是确认候选词，不是提交。
            onPressEnter={(e) => {
              if (isImeConfirm(e)) return;
              submit();
            }}
          />
        </div>
        <label className="add-link-label" htmlFor="add-link-url">
          网址
        </label>
        <Input
          id="add-link-url"
          value={url}
          placeholder="https://example.com"
          onChange={(e) => {
            setUrl(e.target.value);
            setError(null);
          }}
          // ★同上：网址框也会被输入法组词（拼音/日文），回车同样不能直接提交。
          onPressEnter={(e) => {
            if (isImeConfirm(e)) return;
            submit();
          }}
        />
        {/* ★名字能留空（回落域名），所以这句必须写出来 —— 否则用户会以为"名称"也是必填，
            在明明只想看一个页面时被迫先起个名字。
            ★★2026-10-30：文案从"所有会话"改成"当前会话"，口径必须与数据模型一致 ——
            标签是会话成员共享的，不是跟着这台浏览器/这个账号走的。 */}
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          名称可以不填，默认用网站域名。链接保存在当前会话里，会话成员都能看到。
        </Typography.Text>
        {error && (
          <Typography.Text type="danger" style={{ fontSize: 12 }}>
            {error}
          </Typography.Text>
        )}
      </div>
    </Modal>
  );
}
