import { Button, Checkbox, Modal, Popconfirm, Typography } from 'antd';
// ★★DEV-265：`TOP_TABS` 换成了 `manageableTabDefs` —— 本组件**不再**直接枚举全量定义。
import { manageableTabDefs, normalizeTabKeys, type TopTabDef, type TopTabKey } from '../lib/topTabs';
import type { CustomTab, CustomTabKey } from '../lib/customTabs';
import { IconLink, IconMoveDown, IconMoveUp, IconTrash } from './icons';

/**
 * ★「管理标签页」（照飞书会话窗口顶部 {@code +} 菜单里的第二项）。
 *
 * <p>只做一件事：勾选会话窗口顶部显示哪些标签页。★<b>纯前端</b>——
 * 偏好存在这台浏览器的 localStorage 里（见 {@code lib/topTabs.ts}），
 * 与服务端无关，也不跨设备同步。这一点写在界面上（下面那行小字），
 * 免得用户换台电脑发现"我配的标签页没了"而以为是 bug。
 *
 * <p>★{@code removable=false} 的有<b>三类</b>（都渲染成 {@code disabled}，
 * 用"勾不动"说明白，而不是"勾了没反应"）：
 * <ul>
 *   <li><b>「消息」</b>：它是会话本体，去掉之后这个窗口里就没有看消息的地方了；</li>
 *   <li><b>「设置」/「搜索」</b>（★★DEV-256 起）：它们是<b>固定工具位</b>（{@code docked}），
 *       已经渲染到标签行右侧、不靠偏好存活（理由见 {@code TopTabDef.docked}）；</li>
 *   <li><b>「成员」</b>（★★DEV-257 起）：它也是固定位，但<b>右侧没有图标</b> ——
 *       入口搬到了群名称旁那个成员数按钮上（{@code TopTabDef.dockIcon} 为 false）。</li>
 * </ul>
 * ★★三类的<b>原因各不相同</b> ⇒ 标注的文案也必须各不相同，见 {@link nonRemovableNote}。
 *
 * <p>★★DEV-265：列出哪些项<b>不再是"全量"</b> —— 改由 {@link manageableTabDefs} 按
 * 会话类型投影（用户原话：「管理标签页，私聊不展示群公告、入群申请、设置、成员」）。
 * ★在此之前本组件是全项目唯一直接枚举 {@code TOP_TABS} 的地方，于是单聊里点开它，
 * 那四项照样列着 —— 那是本组件**自己一个人**的界面，标签行里早就没有了。
 */

/**
 * ★★DEV-257：{@code removable=false} 的项该标注哪句话。
 *
 * <p>判据是<b>"它为什么不可移除"</b>（{@code docked} / {@code dockIcon}），
 * <b>不是</b>"它叫什么" —— 按 label 分支的话，下一个被固定住的标签页会自动套上一个
 * 说错对象的句子，而那种错的表现只是"这句话怎么念都不对"，没有任何报错。
 *
 * <p>★DEV-256 的成例：当时把写死的「会话本体，不可移除」加上 {@code docked} 分支，
 * 正是为了让「搜索」不顶着"搜索是会话本体"这半句假话。DEV-257 又多了「成员」这一类
 * （固定位，但入口在群名称旁）—— 所以这里必须是三段，不是两段。
 */
function nonRemovableNote(t: TopTabDef): string {
  if (!t.docked) return '（会话本体，不可移除）';
  if (t.dockIcon === false) return '（从群名称旁的成员数进入，不可移除）';
  return '（固定显示在右侧，不可移除）';
}
export default function ManageTabsModal({
  open,
  keys,
  onChange,
  onClose,
  isGroup = false,
  links = [],
  canEditLinks = true,
  onRemoveLink,
  onEditLink,
  onMoveLink,
  tasksAvailable = false,
}: {
  open: boolean;
  keys: readonly TopTabKey[];
  onChange: (next: TopTabKey[]) => void;
  onClose: () => void;
  /**
   * ★自定义链接（用户 2026-10-27 需求）。它们**不是** {@link TopTabKey}，
   * 因此不参与上面的复选框组，而是在下面单独列出、单独删除。
   *
   * <p>★为什么管理入口放在这里，而不是在标签上右键：这个弹窗本来就是
   * "管理顶部标签页"的地方，用户要删一个自定义标签时会先想到这里；
   * 而右键菜单在触摸屏/投屏上没有入口。
   *
   * <p>★为什么"删除"不在标签行上直接做：标签行只有 24px 高，
   * 塞一个叉号会把点击热区切碎（点到叉 vs 切标签），而删错了要重新输网址。
   */
  links?: readonly CustomTab[];
  /**
   * ★我能不能改这些自定义链接（2026-10-30 会话级口径）。
   *
   * <p>单聊恒为 true（双方都可增删改）；群聊只有群主 / 管理员为 true，
   * 普通成员<b>只读</b>。★这里只控制"按钮显不显示"，
   * 真正的权限判定在服务端（{@code IM_30001}）。
   */
  canEditLinks?: boolean;
  /** 删除一个自定义链接。★不传则只展示、不提供删除按钮（其它调用方零改动）。 */
  onRemoveLink?: (key: CustomTabKey) => void | Promise<void>;
  /** 编辑一个自定义链接（打开预填的弹窗）。★与删除同口径：不传 / 无权限则不显示。 */
  onEditLink?: (key: CustomTabKey) => void;
  /**
   * ★★上移 / 下移一个自定义链接（用户 2026-10-27 原话「多个标签支持排序调整，上移下移」）。
   *
   * <p>★它改的是<b>会话级共享顺序</b>（`sortOrder`），同会话所有成员看到的标签栏
   * 一起变 ⇒ 与编辑/删除同口径，只有 {@code canEditLinks} 时显示。
   * <p>★按钮在首/末行<b>禁用</b>而不是隐藏：位置固定的两个按钮比"时有时无"更容易点准，
   * 也把"已经到头了"这个信息显示出来。
   * <p>★不传回调则不显示（其它调用方零改动）。
   */
  onMoveLink?: (key: CustomTabKey, direction: 'up' | 'down') => void | Promise<void>;
  /**
   * ★DEV-193 引入，★★DEV-265 改口径：当前会话是不是群聊。
   *
   * <p>DEV-193 时它<b>只影响标注</b>（群专属项照样列出来，后面挂一句「（仅群聊显示）」），
   * 理由是"别禁止用户在单聊里预先配好群聊要用的标签"。★★DEV-265 把这条取舍<b>推翻了</b> ——
   * 用户原话「<b>管理标签页，私聊不展示群公告、入群申请、设置、成员</b>」要的是<b>看不见</b>。
   * 现在它<b>决定列出哪些项</b>（见 {@link manageableTabDefs}），是**投影**而不是标注。
   *
   * <p>★为什么要传它：偏好是<b>全局</b>的（一份 localStorage 管所有会话），
   * 而单聊里那四项本来就不显示（{@code lib/topTabs} 的 {@code groupOnly} + {@code visibleTabKeys}）
   * ⇒ 单聊里列出它们，等于让用户去勾一个"勾完什么都不会发生"的东西。
   */
  isGroup?: boolean;
  tasksAvailable?: boolean;
}) {
  const listable = manageableTabDefs(isGroup, tasksAvailable);
  // ★★DEV-265：**这次没渲染出来**的那些项（单聊里就是群公告 / 入群申请 / 设置 / 成员）。
  //   它们必须在下一次 onChange 时被**原样补回**偏好里 —— 理由见下面那段（实测得来）。
  const listableKeys = new Set(listable.map((t) => t.key));
  const hidden = keys.filter((k) => !listableKeys.has(k));
  return (
    <Modal
      title="管理标签页"
      open={open}
      onCancel={onClose}
      footer={null}
      width={420}
      // ★★2026-10-30：与 {@code AddLinkTabModal} 配对固定层级（管理 1000 / 编辑 1100）。
      //   不写死的话两者都用 antd 默认值，谁盖住谁由 portal 首次插入顺序决定 ——
      //   表现就是「点编辑，编辑框跑到后面去了」。见 AddLinkTabModal 里那段说明。
      zIndex={1000}
    >
      <Typography.Paragraph type="secondary" style={{ fontSize: 12 }}>
        勾选会话窗口顶部要显示的标签页。★设置对所有会话生效，并记在<b>这台浏览器</b>上（不跨设备同步）。
      </Typography.Paragraph>
      <Checkbox.Group
        value={[...keys]}
        // ★回传的顺序跟着 DOM 走（用户随手一勾就可能把「消息」排到第二位），
        //   所以写路径也必须过一遍 normalizeTabKeys —— 与读路径同一套规则。
        // ★★DEV-265：`hidden` 必须跟着一起交回去。antd 的 `Checkbox.Group` 只回传
        //   **这次真的渲染出来的**那些框 —— `v` 里根本不会出现被投影挡掉的项，
        //   于是光写 `normalizeTabKeys(v)` 就等于：用户在单聊里随手勾一下，
        //   那四项就被<b>从偏好里静默删掉</b>了，切回群聊「群公告」「入群申请」不见了。
        //   ★★这条是**实测**出来的，而且推翻了我自己的一个假设（完整经过记在
        //   docs/05 · DEV-265，量具 `verify-chat-tabs.mjs` 的 A/B 段注释里也有）：
        //   我先据 antd/rc-checkbox 的行为推断"受控 value 不会丢"，又跑了个探针
        //   "确认"了它 —— ★但那个探针是在<b>改动前</b>的产物上跑的，那时这四项
        //   **还渲染着**，所以它量的根本不是"未渲染"这个条件，给的是一个假绿。
        //   改成只做投影之后，量具里"切回群聊这两项照旧勾着"那条当场变红，
        //   才把真结论逼出来 —— 这段代码就是它的产物。
        onChange={(v) => onChange(normalizeTabKeys([...(v as unknown[]), ...hidden]))}
      >
        <div className="manage-tabs-list">
          {/* ★★DEV-265：`TOP_TABS.map` → `manageableTabDefs(isGroup).map`。
              单聊里那四项（群公告 / 入群申请 / 设置 / 成员）**连复选框都不再渲染**。
              ★★这是本组件唯一一处"看得到"的改动，也是本需求的全部分量。 */}
          {listable.map((t) => (
            <Checkbox key={t.key} value={t.key} disabled={!t.removable}>
              {t.label}
              {/* ★★DEV-265 删掉了这里原本那条 `t.groupOnly && !isGroup` 的
                  「（仅群聊显示）」标注（DEV-193 加的）—— 上面过滤之后它**恒不触发**：
                  留下来的话，是一段读起来像还活着的死代码，而且它的注释在解释一个
                  **已经被用户推翻**的取舍（DEV-193 的口径是"标注但不禁止"，理由见旧注释
                  「别禁止用户在单聊里预先配好群聊要用的标签」；DEV-265 的用户原话
                  「私聊不展示…」把口径改成了**不列**）。
                  ★下面这条 `!t.ready` 的标注**留着**：它与会话类型无关，是"这个标签页
                    还没做出来"这个**正交**维度 —— 只是现在恰好没有未接入的项。 */}
              {!t.ready && (
                <Typography.Text type="secondary" style={{ fontSize: 12 }}>
                  （尚未接入）
                </Typography.Text>
              )}
              {/* ★★DEV-256：这几句**必须分开**。原来是写死的一句「会话本体，不可移除」，
                  它是为「消息」写的；DEV-256 把「搜索」也变成 `removable:false`
                  （固定工具位，见 `TopTabDef.docked`）之后，同一句话会贴到搜索上 ⇒
                  <b>界面上出现一句假话</b>："搜索是会话本体"。
                  ★症状很轻、很难被发现：文字确实渲染出来了，只是说错了对象；
                    而用户能看到的唯一破绽是"这句话怎么念都不对"。
                  ⇒ 判据用 `docked`（"它为什么不可移除"），不用"它叫什么"。
                  ★★DEV-257：分支涨到三段（多了「成员」：固定位但入口在群名称旁），
                    已经挪进 `nonRemovableNote` —— 留在这儿的嵌套三元会变成
                    「读的人得自己在脑子里跑一遍」的那种代码。 */}
              {!t.removable && (
                <Typography.Text type="secondary" style={{ fontSize: 12 }}>
                  {nonRemovableNote(t)}
                </Typography.Text>
              )}
            </Checkbox>
          ))}
        </div>
      </Checkbox.Group>

      {/* ★★自定义链接单独一段：它们不是 TopTabKey，复选框组管不到它们。
          只有真的加过才渲染 —— 空着的时候多一个"自定义链接（0）"的标题，
          对没加过的用户（绝大多数）只是噪音。 */}
      {links.length > 0 && (
        <div className="manage-links">
          <Typography.Paragraph type="secondary" style={{ fontSize: 12, marginBottom: 6 }}>
            自定义链接（{links.length}）
          </Typography.Paragraph>
          <div className="manage-links-list">
            {links.map((t, i) => (
              <div key={t.key} className="manage-link-row">
                {/* ★图标（2026-10-30）：与标签栏同一套口径 —— 有 icon 显示它，
                    没有则回落链条图标。这里必须和 ChatWindow 的 LinkTabIcon 一致，
                    否则用户在管理弹窗里看到的记号跟标签上的对不上。 */}
                {t.icon ? (
                  <span className="manage-link-emoji" aria-hidden="true">
                    {t.icon}
                  </span>
                ) : (
                  <IconLink size={14} />
                )}
                <span className="manage-link-name" title={t.name}>
                  {t.name}
                </span>
                <span className="manage-link-url" title={t.url}>
                  {t.url}
                </span>
                {/* ★★上移 / 下移：改的是会话级共享顺序（sortOrder），
                    同会话所有人看到的标签栏一起变 —— 与编辑/删除同一道权限闸门。
                    首行/末行的按钮 disabled（位置固定、点得准，也比"消失"更说明问题）。 */}
                {canEditLinks && onMoveLink && (
                  <>
                    <Button
                      type="text"
                      size="small"
                      className="manage-link-move-up"
                      aria-label={`上移${t.name}`}
                      title="上移"
                      disabled={i === 0}
                      onClick={() => onMoveLink(t.key, 'up')}
                      icon={<IconMoveUp size={14} />}
                    />
                    <Button
                      type="text"
                      size="small"
                      className="manage-link-move-down"
                      aria-label={`下移${t.name}`}
                      title="下移"
                      disabled={i === links.length - 1}
                      onClick={() => onMoveLink(t.key, 'down')}
                      icon={<IconMoveDown size={14} />}
                    />
                  </>
                )}
                {canEditLinks && onEditLink && (
                  <Button
                    type="text"
                    size="small"
                    className="manage-link-edit"
                    aria-label={`编辑${t.name}`}
                    onClick={() => onEditLink(t.key)}
                  >
                    编辑
                  </Button>
                )}
                {canEditLinks && onRemoveLink && (
                  // ★二次确认是必须的：删掉之后要重新手输网址（会话里不保留任何历史），
                  //   而且这是**会话级共享数据** —— 删掉之后其他成员也看不到了。
                  //   直接用图标按钮的话，误点一次的代价不对称。
                  <Popconfirm
                    title="删除这个链接标签页？"
                    description={t.name}
                    okText="删除"
                    cancelText="取消"
                    okButtonProps={{ danger: true }}
                    // ★返回 Promise：服务端删除成功后才关掉气泡（失败留在原地并提示）。
                    onConfirm={() => onRemoveLink(t.key)}
                  >
                    <Button
                      type="text"
                      size="small"
                      danger
                      className="manage-link-remove"
                      aria-label={`删除${t.name}`}
                      icon={<IconTrash size={14} />}
                    />
                  </Popconfirm>
                )}
              </div>
            ))}
          </div>
          <Typography.Text type="secondary" style={{ fontSize: 12 }}>
            {canEditLinks
              ? '上移 / 下移调整标签栏顺序，会话成员共享；删除后顶部标签立即消失，需要时可从「添加标签页 → 自定义链接…」重新添加。'
              : '这些链接由会话成员共享；群聊里只有群主 / 管理员可以添加、修改、排序或删除。'}
          </Typography.Text>
        </div>
      )}
    </Modal>
  );
}
