/**
 * ★★群会话里「发起语音 / 视频通话」的选人弹窗。
 *
 * <h2>它做三件事，顺序不能反</h2>
 * <ol>
 *   <li><b>建会并进入</b>：会议号现场生成，{@code convId} 一并带给服务端
 *       ⇒ 会议记录挂在这个群上，散会后的系统消息也会回到群里；</li>
 *   <li><b>往群里发一张静默卡片</b>：群里所有人都能看到、随时点进来；</li>
 *   <li><b>给勾选的人发单聊邀请</b>：那条才会真的响铃（60 秒来电浮层）。</li>
 * </ol>
 *
 * <h2>★★为什么"群卡片"和"响铃邀请"要分开</h2>
 *
 * <p>一条群消息会扇出给所有在线成员。如果它自带响铃，用户只勾了 3 个人，结果
 * 整个群（可能几十号人）全被弹起来电浮层 —— 这不是"拉人"，是骚扰。
 * 所以群卡片带 {@code silent:true}（客户端只画卡片、不响铃），
 * 而被勾选的人另外收到一条单聊 {@code meeting_invite}（照常响铃）。
 *
 * <h2>★人数上限 19</h2>
 *
 * <p>房间的 {@code maxParticipants=20}（见 {@code store/call} 的 {@code enterRoom}），
 * 其中一个是自己 ⇒ 最多再拉 19 个。超出的成员仍能从群卡片点进来，
 * 只是不会收到"响铃"这一层强提醒。
 */
import { useEffect, useMemo, useRef, useState } from 'react';
import { App as AntApp, Avatar, Checkbox, Modal } from 'antd';

import type { ConversationSummaryDto } from '../api/types';
import { groupCallTitle, makeInviteId } from '../lib/meetingInvite';
import { makeMeetingNo } from '../lib/meetingSchedule';
import { primeMeetingWindow } from '../lib/meetingWindow';
import type { VoipMediaType } from '../lib/voip';
import { useCallStore } from '../store/call';
import { useChatStore } from '../store/chat';
import { inviteContactsToMeeting, sendGroupCallCard } from '../store/meetingInvite';

/** 房间上限 20，减去自己。 */
export const MAX_GROUP_CALL_INVITEES = 19;

function memberName(m: { name?: string; nickName?: string }, fallback: string): string {
  return (m.nickName || m.name || '').trim() || fallback;
}

export default function GroupCallDialog({
  open,
  conv,
  groupTitle,
  mediaType,
  onClose,
}: {
  open: boolean;
  /** ★必须是群/团队群会话；没有会话时弹窗什么都不做。 */
  conv: ConversationSummaryDto | null;
  /** 顶栏显示的那个群名（与聊天标题同源，不在这里再取一次）。 */
  groupTitle: string;
  mediaType: VoipMediaType;
  onClose: () => void;
}) {
  const { message: toast } = AntApp.useApp();
  const userId = useChatStore((s) => s.userId);
  const members = useChatStore((s) => (conv ? s.membersByConv[String(conv.convId)] : undefined));
  const loadMembers = useChatStore((s) => s.loadMembers);
  const startRoomMeeting = useCallStore((s) => s.startRoomMeeting);
  const setPopout = useCallStore((s) => s.setPopout);

  const [selected, setSelected] = useState<string[]>([]);
  /** ★只在"这一轮打开 + 成员首次到达"时全选一次；之后用户的勾选不被重渲染冲掉。 */
  const initializedRef = useRef<string | null>(null);

  useEffect(() => {
    if (!open || !conv) {
      initializedRef.current = null;
      return;
    }
    void loadMembers(conv.convId).catch(() => undefined);
  }, [open, conv, loadMembers]);

  /** 真人成员（智能体不会接电话，排除；自己不在候选里）。 */
  const eligible = useMemo(() => {
    const list = members ?? [];
    return list.filter((m) => {
      if (m.self === true) return false;
      if (userId != null && String(m.userId) === String(userId)) return false;
      return m.agentMode == null;
    });
  }, [members, userId]);

  const memberKey = eligible.map((m) => String(m.userId)).join(',');

  useEffect(() => {
    if (!open || !conv) return;
    // ★成员还没加载出来时先不等：等第一页到达后再做默认全选。
    if (eligible.length === 0) return;
    const key = `${conv.convId}:${mediaType}`;
    if (initializedRef.current === key) return;
    initializedRef.current = key;
    setSelected(eligible.slice(0, MAX_GROUP_CALL_INVITEES).map((m) => String(m.userId)));
  }, [open, conv, mediaType, eligible, memberKey]);

  const toggle = (id: string) => {
    if (selected.includes(id)) {
      setSelected((prev) => prev.filter((x) => x !== id));
      return;
    }
    if (selected.length >= MAX_GROUP_CALL_INVITEES) {
      toast.warning(`最多邀请 ${MAX_GROUP_CALL_INVITEES} 人，其余成员可以在群里点通话卡片加入`);
      return;
    }
    setSelected((prev) => [...prev, id]);
  };

  const confirm = () => {
    if (!conv) return;
    if (useCallStore.getState().phase !== 'idle') {
      toast.warning('你正在通话或会议中，请先结束后再发起');
      return;
    }

    const roomName = makeMeetingNo(Math.floor(Math.random() * 10 ** 9));
    const callTitle = groupCallTitle(groupTitle, mediaType);
    const chosen = eligible
      .filter((m) => selected.includes(String(m.userId)))
      .map((m) => ({ userId: String(m.userId), name: memberName(m, '群成员') }));

    onClose();

    // ★★必须紧跟在这一下点击里：异步之后 window.open 会丢用户手势、被弹窗拦截
    const started = startRoomMeeting(mediaType, roomName, callTitle, false, undefined, String(conv.convId));
    if (useCallStore.getState().phase === 'connecting' && primeMeetingWindow(callTitle)) {
      setPopout(true);
    }

    void (async () => {
      try {
        await started;
      } catch {
        return;
      }
      // ★建房/入会失败（号非法、服务未开启…）就不发邀请了：邀请一个不存在的会议是假承诺
      if (useCallStore.getState().phase !== 'active') return;

      let cardSent = false;
      try {
        await sendGroupCallCard({
          convId: String(conv.convId),
          invite: {
            inviteId: makeInviteId(Date.now(), String(Math.floor(Math.random() * 1e6))),
            roomName,
            title: callTitle,
            mediaType,
          },
        });
        cardSent = true;
      } catch {
        // ★卡片失败不影响通话本身：至少自己已经进会，选中的成员还会收到响铃邀请
      }

      let ok = 0;
      const failed: string[] = [];
      if (chosen.length > 0) {
        const outcome = await inviteContactsToMeeting({
          roomName,
          title: callTitle,
          mediaType,
          groupCall: true,
          contacts: chosen,
        });
        ok = outcome.ok;
        failed.push(...outcome.failed);
      }

      if (!cardSent && ok === 0) {
        toast.warning('通话已开始，但邀请没有发出去');
      } else if (!cardSent) {
        toast.warning(`通话已开始，已通知 ${ok} 人，但群里的通话卡片没发出去`);
      } else if (failed.length > 0) {
        toast.warning(`已通知 ${ok} 人，${failed.length} 人没发出去（${failed.slice(0, 3).join('、')}）`);
      } else if (ok > 0) {
        toast.success(`已通知 ${ok} 人，通话卡片已发到群里`);
      } else {
        toast.success('通话已开始，通话卡片已发到群里');
      }
    })();
  };

  const title = mediaType === 'video' ? '发起群视频通话' : '发起群语音通话';

  return (
    <Modal
      open={open}
      title={title}
      onCancel={onClose}
      onOk={confirm}
      okText="发起通话"
      cancelText="取消"
      width={420}
      destroyOnClose
      className="group-call-modal"
    >
      <p className="group-call-tip">
        选择要通知的群成员（最多 {MAX_GROUP_CALL_INVITEES} 人）。没选中的人也能在群里看到通话卡片，随时点进来。
      </p>
      <div className="group-call-toolbar">
        <span className="group-call-count">
          已选 {selected.length} / {Math.min(eligible.length, MAX_GROUP_CALL_INVITEES)} 人
        </span>
        <button
          type="button"
          className="group-call-link"
          onClick={() => setSelected(eligible.slice(0, MAX_GROUP_CALL_INVITEES).map((m) => String(m.userId)))}
        >
          全选
        </button>
        <button type="button" className="group-call-link" onClick={() => setSelected([])}>
          清空
        </button>
      </div>
      <div className="group-call-list">
        {eligible.length === 0 ? (
          <div className="group-call-empty">
            {members == null ? '正在加载群成员…' : '这个群里还没有其他成员，通话卡片仍会发到群里'}
          </div>
        ) : (
          eligible.map((m) => {
            const id = String(m.userId);
            const name = memberName(m, '群成员');
            return (
              <label key={id} className="group-call-row">
                <Checkbox checked={selected.includes(id)} onChange={() => toggle(id)} />
                <Avatar size={28} src={m.avatar || undefined} className="group-call-avatar">
                  {name.slice(0, 1)}
                </Avatar>
                <span className="group-call-name">{name}</span>
              </label>
            );
          })
        )}
      </div>
    </Modal>
  );
}
