/**
 * 消息正文里的资料库文档链接 → **飞书式文档卡片**。
 *
 * <h2>触发条件</h2>
 * <p>整条正文**只由** {@code /repo/doc/{slugId}} 链接与空白组成时才替换成卡片；
 * 链接混在普通句子里时仍按原文渲染（用户在句子里提一句文档，不该整段话被卡片吞掉）。
 * 这个判据由 {@code lib/repoDocLink.ts} 的 {@code scanRepoDocLinks} 给出，
 * 与发送后的自动授权**共用同一份识别口径**。
 *
 * <h2>★★失败必须退回普通链接</h2>
 * <p>{@code /api/repo/s/{slug}} 失败（文档被删、无权限、未登录、网络抖动）时
 * **不画卡片**，把原文里的链接原样还回去。卡片是增强，不是新的失败面 ——
 * 一条消息不能因为增强请求失败就变空白，更不能变成"点了没反应"的死卡片。
 *
 * <h2>★懒加载</h2>
 * <p>元数据只在卡片接近视口时才请求（{@link IntersectionObserver}，preload 240px）。
 * 历史消息里有很多文档链接时，不能因为"滚动列表挂载了 200 条消息"就同时打 200 个接口。
 * 模块级缓存与 in-flight 合并在 {@code lib/repoDocCard.ts}。
 */

import { App as AntApp } from 'antd'
import { useEffect, useMemo, useRef, useState } from 'react'

import { copyText } from '../lib/clipboard'
import { scanRepoDocLinks, type RepoDocLinkRef } from '../lib/repoDocLink'
import RichText, { PlainText } from '../lib/markdown'
import {
  cachedRepoDocMeta,
  cachedRepoDocPreview,
  loadRepoDocMeta,
  loadRepoDocPreview,
  repoDocIconKind,
  repoDocPath,
  repoDocPermissionLabel,
  sameRepoDocMeta,
  shouldRefreshRepoDocMeta,
  shouldRefreshRepoDocPreview,
  type RepoDocMeta,
} from '../lib/repoDocCard'
import {
  IconCopy,
  IconDatatableSolid,
  IconDocSolid,
  IconFolderSolid,
  IconPdfSolid,
  IconSheetSolid,
  IconSlidesSolid,
} from './icons'

/** 与资料库同域的登录 cookie —— 预览导出接口同样靠它。 */
const REPO_DOC_CARD_PRELOAD = '240px 0px'

/**
 * 元数据查询失败后的自动重试次数 / 间隔。
 *
 * <p>★失败可能是瞬时的（后端重启、网关 502、网络抖动）。失败结果会被内存缓存住，
 * 若不做重试，接收方这一整段会话都只能看到普通链接，必须刷新页面才会变成卡片。
 * 重试保持静默：失败期间仍显示链接，成功后再换成卡片，不来回闪骨架。
 */
const REPO_DOC_FAILURE_RETRIES = 2
const REPO_DOC_FAILURE_RETRY_MS = 5000

interface DocLinkBodyProps {
  text: string
  names?: string[]
  /** 正文是不是用户没做格式化的纯文本（决定普通文档链接用哪条渲染路）。 */
  plain?: boolean
}

/** 正文渲染入口：文档链接独占整条消息时换成卡片，否则逐字沿用原渲染。 */
export function DocLinkBody({ text, names, plain }: DocLinkBodyProps) {
  const scan = useMemo(() => scanRepoDocLinks(text), [text])
  if (!scan.docOnly || scan.links.length === 0) {
    return plain ? <PlainText text={text} names={names} /> : <RichText text={text} names={names} />
  }
  return (
    <div className="doc-card-list">
      {scan.links.map((link) => (
        <RepoDocCardSlot key={link.slug} link={link} plain={plain === true} />
      ))}
    </div>
  )
}

function RepoDocCardSlot({ link, plain }: { link: RepoDocLinkRef; plain: boolean }) {
  // undefined = 还没查；null = 查过但失败（保持普通链接）；对象 = 可以画卡片。
  const [meta, setMeta] = useState<RepoDocMeta | null | undefined>(() => cachedRepoDocMeta(link.slug))
  const [active, setActive] = useState(() => cachedRepoDocMeta(link.slug) !== undefined)
  const [retries, setRetries] = useState(0)
  const slotRef = useRef<HTMLDivElement>(null)

  // 进入预加载范围再发请求。没有 IntersectionObserver 的宿主直接查（退化）。
  useEffect(() => {
    if (active) return
    const el = slotRef.current
    if (!el || typeof IntersectionObserver === 'undefined') {
      setActive(true)
      return
    }
    const io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          setActive(true)
          io.disconnect()
        }
      },
      { rootMargin: REPO_DOC_CARD_PRELOAD },
    )
    io.observe(el)
    return () => io.disconnect()
  }, [active])

  useEffect(() => {
    if (!active || meta !== undefined) return
    let cancelled = false
    void loadRepoDocMeta(link.slug).then((next) => {
      if (!cancelled) setMeta(next)
    })
    return () => {
      cancelled = true
    }
  }, [active, link.slug, meta])

  /**
   * ★失败自动重试：后端重启/网关 502 这类瞬时错误不该让卡片永久退化成链接。
   * 最多补两次，成功即停；重试期间保留当前的链接/卡片形态，不闪骨架。
   */
  useEffect(() => {
    if (!active || meta !== null || retries >= REPO_DOC_FAILURE_RETRIES) return
    const timer = setTimeout(() => {
      setRetries((n) => n + 1)
      void loadRepoDocMeta(link.slug, fetch, { force: true }).then((next) => {
        if (next) setMeta(next)
      })
    }, REPO_DOC_FAILURE_RETRY_MS)
    return () => clearTimeout(timer)
  }, [active, meta, retries, link.slug])

  /**
   * ★静默刷新：上次会话缓存下来的卡片先照原样显示，超过 5 分钟才在后台重新拉一次。
   * 不进入 loading 分支（{@code meta} 始终有值），所以标题/预览不会闪成骨架或裸链接；
   * 内容确实变化时才 setState。失败时 load 会保留旧值。
   */
  useEffect(() => {
    if (!active || !meta || !shouldRefreshRepoDocMeta(link.slug)) return
    let cancelled = false
    void loadRepoDocMeta(link.slug, fetch, { force: true }).then((next) => {
      if (cancelled || !next) return
      setMeta((prev) => (sameRepoDocMeta(prev ?? null, next) ? prev : next))
    })
    return () => {
      cancelled = true
    }
  }, [active, link.slug, meta])

  if (meta === undefined) {
    // ★加载态直接画卡片骨架，而不是先退回原链接再"展开"：
    // 接收方没有本地缓存，接口往返期间如果显示裸链接，视觉上就是
    // 「一条链接 → 整块卡片」的跳变，还会带着气泡宽度一起变。
    return (
      <div className="doc-card-slot" ref={slotRef}>
        <RepoDocCardSkeleton />
      </div>
    )
  }

  if (meta === null) {
    // 查不到（文档被删/无权限/网络异常）才退回原链接。
    // ★外面仍包一层有底色的壳：同一条消息里若另一张卡片成功，气泡 padding 已被撤掉，
    // 这段文字需要自己的呼吸空间。
    return (
      <div className="doc-card-slot" ref={slotRef}>
        <div className="doc-card-fallback" data-doc-card-state="failed">
          {plain ? <PlainText text={link.raw} /> : <RichText text={link.raw} />}
        </div>
      </div>
    )
  }

  return (
    <div className="doc-card-slot" ref={slotRef}>
      <RepoDocCardView meta={meta} slug={link.slug} />
    </div>
  )
}

/** 首次查询元数据时的占位卡：尺寸与真卡片一致，避免接口回来后整块撑开。 */
function RepoDocCardSkeleton() {
  return (
    <div className="doc-card doc-card-skeleton" aria-hidden="true">
      <div className="doc-card-head">
        <span className="doc-card-icon-skeleton" />
        <span className="doc-card-skeleton-line doc-card-title-skeleton" />
      </div>
      <div className="doc-card-preview is-loading">
        <span className="doc-card-skeleton-line w92" />
        <span className="doc-card-skeleton-line w100" />
        <span className="doc-card-skeleton-line w64" />
      </div>
      <div className="doc-card-foot">
        <span className="doc-card-skeleton-line doc-card-foot-skeleton" />
      </div>
    </div>
  )
}

/** 按文档类型换图标：富文本 / 幻灯片 / 表格 / 多维表格 / PDF / 文件夹。 */
function RepoDocTypeIcon({ meta }: { meta: RepoDocMeta }) {
  const size = 22
  switch (repoDocIconKind(meta.pageType, meta.sourceExt)) {
    case 'slides':
      return <IconSlidesSolid size={size} />
    case 'sheet':
      return <IconSheetSolid size={size} />
    case 'datatable':
      return <IconDatatableSolid size={size} />
    case 'pdf':
      return <IconPdfSolid size={size} />
    case 'folder':
      return <IconFolderSolid size={size} />
    default:
      return <IconDocSolid size={size} />
  }
}

function RepoDocCardView({ meta, slug }: { meta: RepoDocMeta; slug: string }) {
  const { message: toast } = AntApp.useApp()
  const href = repoDocPath(slug)

  const copyLink = async () => {
    const absolute = typeof window !== 'undefined'
      ? new URL(href, window.location.origin).href
      : href
    const ok = await copyText(absolute)
    if (ok) toast.success('文档链接已复制')
    else toast.error('复制失败，请手动复制')
  }

  return (
    <div className="doc-card">
      <a
        className="doc-card-link"
        href={href}
        target="_blank"
        rel="noopener noreferrer"
        title="打开文档"
      >
        <div className="doc-card-head">
          <span className="doc-card-icon"><RepoDocTypeIcon meta={meta} /></span>
          <span className="doc-card-title">{meta.title || '未命名文档'}</span>
        </div>
        <RepoDocPreview meta={meta} />
      </a>
      <div className="doc-card-foot">
        <span className="doc-card-owner">{meta.creatorName || '资料库文档'}</span>
        <span className="doc-card-perm">{repoDocPermissionLabel(meta.myAccess)}</span>
        <button
          type="button"
          className="doc-card-copy"
          title="复制文档链接"
          aria-label="复制文档链接"
          onClick={() => { void copyLink() }}
        >
          <IconCopy size={15} />
        </button>
      </div>
    </div>
  )
}

function RepoDocPreview({ meta }: { meta: RepoDocMeta }) {
  const initial = cachedRepoDocPreview(meta.id)
  const [preview, setPreview] = useState<string | null | undefined>(initial)

  useEffect(() => {
    const stale = preview !== undefined && shouldRefreshRepoDocPreview(meta.id)
    if (preview !== undefined && !stale) return
    let cancelled = false
    // 有缓存但过期 ⇒ 先照旧显示，再后台静默刷新（不出现骨架）。
    void loadRepoDocPreview(meta, fetch, { force: stale }).then((text) => {
      if (cancelled) return
      setPreview((prev) => {
        if (text == null) return prev ?? null
        return text === prev ? prev : text
      })
    })
    return () => {
      cancelled = true
    }
  }, [meta, preview])

  if (preview === undefined) {
    return (
      <div className="doc-card-preview is-loading" aria-hidden="true">
        <span className="doc-card-skeleton-line w92" />
        <span className="doc-card-skeleton-line w100" />
        <span className="doc-card-skeleton-line w64" />
      </div>
    )
  }
  if (!preview) {
    return <div className="doc-card-preview is-empty">打开文档查看全文</div>
  }
  return <div className="doc-card-preview">{preview}</div>
}
