import { useState } from 'react';
import { App as AntApp, Modal, Segmented, Space, Tabs, Typography } from 'antd';
import { convApi } from '../api';
import type { AddMembersResult, Id } from '../api/types';
import { AGENT_MODE_HINT, AGENT_MODE_OPTIONS, DEFAULT_AGENT_MODE, type AgentMode } from '../lib/agentMode';
import { ADD_MEMBER_JOIN_RULE } from '../lib/groupJoinRule';
import { addMembersOutcome } from '../lib/memberAdd';
import { useChatStore } from '../store/chat';
import AgentSearchSelect from './AgentSearchSelect';
import UserSearchSelect from './UserSearchSelect';

/**
 * ★★DEV-256：「添加群员」弹窗 —— <b>用户 / 智能体</b> 两个 Tab，一次提交。
 * <p>★DEV-258：第一个 Tab 的文案由「人」改成「用户」（与「添加伙伴」同批改）。
 *
 * <h2>★它为什么是一个独立组件，而不是各自内联一份</h2>
 *
 * <p>本组件出现之前，「添加群成员」的弹窗内联在 {@link MemberPanelBody} 里。
 * DEV-256 要在<b>对话顶栏右侧</b>再加一个同样的入口（用户原话「右边增加添加群员的图标」）
 * —— 于是同一个动作有了两个入口。
 *
 * <p>★★两个入口各写一份是<b>必然分叉</b>的写法：权限判据、提交端点、
 * 结果文案里任何一处以后只改一边，另一个入口就静默地还是老行为。
 * 本仓在 {@link UserSearchSelect} 的类注释里已经为同一件事付过一次代价
 * （三个选人入口三套逻辑）。⇒ 抽成一个组件，两个入口都只是"打开它"。
 *
 * <h2>★★三条分流规则（用户 2026-09-20 拍板）—— 弹窗里<b>必须说清楚</b></h2>
 *
 * <table border="1">
 *   <tr><th>加什么</th><th>与我同 Team</th><th>结果</th></tr>
 *   <tr><td rowspan="2">真人</td><td>是</td><td><b>直接入群</b>，对方不需要同意</td></tr>
 *   <tr><td>否</td><td>发一条系统消息给对方，<b>对方点「同意」才入群</b></td></tr>
 *   <tr><td>智能体</td><td>—（不适用）</td><td><b>直接入群</b>（它不会点同意）</td></tr>
 * </table>
 *
 * <p>★「与我同 Team」服务端的判据是<b>平台 Team 空间有交集</b>
 * （我的 Team 空间 ∩ 他的 Team 空间 ≠ 空）。
 *
 * <p>★★<b>为什么这句说明是必须的、而不是可有可无的客套</b>：
 * 加了人之后服务端返回的可能是「3 人等待对方同意」而不是「已加入 3 人」。
 * 操作者若不知道有这条分流，看到自己的动作"没把人加进去"只会做两件事：
 * 再点一遍（发第二条卡片），或者以为自己没权限。**两种都很糟**。
 *
 * <h2>★★两个 Tab 的已选是<b>并集一起提交</b>的</h2>
 *
 * <p>用户可以先在「用户」里选两个、再切到「智能体」选一个，然后一次提交 ——
 * 切换 Tab <b>不会</b>清掉另一个 Tab 的选择。理由是它更符合"加群员"这件事的心智
 * （一次动作把要拉的人都拉进来），而且服务端的 {@code POST /members} 本来就
 * 收一批 subjectId、自己按类型分流（{@code addMembersWithTeamSplit}）。
 *
 * <p>★代价是"选中的东西分散在两个看不见彼此的 Tab 里"⇒ 必须把计数<b>挂到 Tab 标题上</b>
 * （见下面 {@code tabLabel}），否则用户切回来才发现多选了人，而那时已经点过提交了。
 *
 * <h2>★两个搜索框的形态不一样，这是刻意的</h2>
 *
 * <p>{@link UserSearchSelect} 是 {@code mode="multiple"}（选中交出 id 数组）；
 * {@link AgentSearchSelect} 平时是单选、这次用 {@code multiple} 形态
 * —— 它多选时<b>同样只交 id</b>（{@code onChangeIds}，不给整条 item）。
 * ★理由写在 {@code AgentSearchSelect} 的类注释里：选项是"按关键字搜出来的"，
 * 选了 A 再搜 B 之后 A 已经不在列表里了，用 items 去还原会让 A <b>静默消失</b>。
 *
 * <h2>★★DEV-271：智能体 Tab 下的「衔接模式」（拍板③的<b>添加时</b>那一半）</h2>
 *
 * <p>需求原话是「加到群里的智能体<b>添加者</b>可以配置模式：① 监听模式（群里每条消息都发给智能体）
 * ② 唤起模式（有用户 @ 智能体时才发）」。拍板③要求<b>两个入口</b>：本弹窗（添加时选）
 * 与群成员面板（之后还能改，见 {@code lib/agentMode.canSetAgentMode}）。
 *
 * <p>本弹窗承担的那一半有三条硬约束：
 * <ol>
 *   <li><b>默认唤起</b>（拍板④，省成本）；</li>
 *   <li><b>只作用于本次选中的智能体</b> —— 服务端对同批的真人成员忽略这个值，
 *       所以"纯加人"的请求<b>连这个键都不发</b>（字节面不变，见 {@code onSubmit} 的注释）；</li>
 *   <li><b>待提交值必须在切会话/关弹窗时复位</b> —— 监听是花钱开关，
 *       让下一个智能体静默继承监听是这个功能能出的最坏的一种错。</li>
 * </ol>
 *
 * <p>★<b>别与 {@code AddPartnerModal} 里那个同名的局部变量 {@code agentMode} 混淆</b>：
 * 那里的 {@code agentMode = tab === 'agent' || targetIsAgent}，意思是"这次加的是不是智能体"
 * （一个布尔），与本批的"衔接模式"（1/2）<b>同名不同义</b>。两处都在改的话尤其容易看串。
 */
export default function AddMemberModal({
  open,
  convId,
  onClose,
  onDone,
}: {
  open: boolean;
  /** ★要往哪个会话里加人。{@code null} 时提交按钮不做任何事（不该发生，兜底）。 */
  convId: Id | null;
  onClose: () => void;
  /**
   * ★提交**成功**后回调（无论人是不是真的进群了 —— 待对方同意也算提交成功）。
   *
   * <p>★★把服务端的原始结果 {@code r} 一并交出去：外层要判断"这次到底有没有改动
   * 成员名单"（决定重不重拉成员表）。判据是纯函数
   * {@code lib/memberAdd.addMembersChangedRoster}，<b>不要在调用点另写一套</b>
   * —— 那个函数的注释里写了为什么它与结果文案必须是同一个判断。
   */
  onDone?: (r: AddMembersResult) => void;
}) {
  const userId = useChatStore((s) => s.userId);
  /** ★群成员要排除掉：把已经在群里的人列出来，用户点了会得到"已在群 1"这种像报错的提示。 */
  const members = useChatStore((s) => (convId != null ? s.membersByConv[String(convId)] : undefined));
  const { message: toast } = AntApp.useApp();

  const [tab, setTab] = useState<'user' | 'agent'>('user');
  /**
   * ★两个 Tab 各存一份已选（提交时取并集，见类注释）。
   * ★都是<b>字符串 id</b>：{@code UserSearchSelect} 交出来的就是 id 数组，
   * {@code AgentSearchSelect} 的多选形态也一样 —— 两个来源同一种值，
   * 所以下面提交时不需要任何"按类型分叉"的代码。
   */
  const [uids, setUids] = useState<string[]>([]);
  const [agentIds, setAgentIds] = useState<string[]>([]);
  const [submitting, setSubmitting] = useState(false);
  /**
   * ★★DEV-271：本批智能体的<b>衔接模式</b>（1=唤起 / 2=监听，见 {@code lib/agentMode.ts}）。
   *
   * <p>★默认<b>唤起</b>（拍板④，省成本）。它<b>只作用于本次选中的智能体</b>：
   * 服务端对同一批里的<b>真人</b>成员忽略这个值（给真人设"监听"没有意义），
   * 所以纯加人的路径一行都不用改（提交那里甚至<b>连这个键都不发</b>）。
   *
   * <p>★★<b>它是"待提交值"，不是"已生效值"</b> ⇒ 下面 {@code reset} 与"切会话重置"
   * 两处都必须把它复位成默认：监听会让群里的<b>每一条</b>消息都触发一次真实计费的模型调用，
   * 让下一个智能体<b>静默继承</b>监听是这个功能能出的最坏的一种错。
   */
  const [agentMode, setAgentMode] = useState<AgentMode>(DEFAULT_AGENT_MODE);

  /**
   * ★★切会话时清空已选 —— 照 {@code MemberPanelBody} 里那条成例的写法
   * （"渲染期发现变了就重置"，而不是 {@code useEffect}）。
   *
   * <p>要防的事故很具体：弹窗开着时用户切了会话（顶栏那个图标就在会话里，
   * 顺手切一下太容易了），在 A 群选好的人会被当成"要拉进 <b>B</b> 群"
   * —— 点下去是在<b>拉错群</b>，而界面上完全看不出来（列的还是那几个人名）。
   *
   * <p>★用 effect 的话要等一帧，那一帧里旧选择仍然挂在提交按钮上；
   * 而且 effect 的清理时机与 Modal 的卸载时机交错，很容易漏掉一次。
   */
  const [lastConvId, setLastConvId] = useState(convId);
  if (String(lastConvId) !== String(convId)) {
    setLastConvId(convId);
    setUids([]);
    setAgentIds([]);
    // ★Tab 也回到「用户」：留在「智能体」上没有错，但用户对新会话的第一眼
    //   应该是那个 Tab（绝大多数加人动作加的是人）。
    setTab('user');
    // ★★DEV-271：模式也复位（理由见 agentMode 那条 state 注释 —— 监听是花钱开关）。
    //   在 A 群选了监听、切到 B 群再加智能体：控件会**直接停在监听上**，
    //   而用户看到的是"我刚打开的弹窗"，不会意识到那是上一个群留下的选择。
    setAgentMode(DEFAULT_AGENT_MODE);
  }

  const reset = () => {
    setUids([]);
    setAgentIds([]);
    setTab('user');
    setSubmitting(false);
    setAgentMode(DEFAULT_AGENT_MODE); // ★DEV-271：同上，复位成默认唤起
  };

  const close = () => {
    reset();
    onClose();
  };

  const total = uids.length + agentIds.length;

  const onSubmit = async () => {
    if (convId == null) return;
    if (total === 0) {
      toast.warning('请先选择要添加的成员');
      return;
    }
    let r: AddMembersResult | null = null;
    setSubmitting(true);
    try {
      // ★两个 Tab 的并集，**用户在前**（顺序只影响"哪一批先处理"的直觉，不影响语义）。
      //   ★去重：同一个人正常不可能同时出现在两个 Tab 里（智能体的 subjectId 是编码过的
      //   独立号段），但去一次只要一行，而重复 id 会让服务端的计数多报一个。
      const all = Array.from(new Set([...uids, ...agentIds]));
      /**
       * ★★DEV-271：衔接模式<b>只在真的选了智能体时</b>才随请求发出去。
       *
       * <p>服务端对同一批里的<b>真人</b>成员忽略它，所以传过去也不算错；不传的理由是
       * <b>字节面</b>：{@code api} 层用条件展开保证"纯加人"的请求体与本批之前
       * <b>逐字节相同</b> —— 一次"只加了个可选参数"的改动不该改变所有加人请求的样子
       * （那是本批唯一不该碰的面，而抓包/桩上是看得出来的）。
       */
      r = await convApi.addMembers(convId, all, agentIds.length > 0 ? agentMode : undefined);
      // ★★结果文案全部来自纯函数 lib/memberAdd.ts（判据是 applied > 0，**不是** inserted === 0）。
      //   ★本批给它加了第三条结局：pendingConfirm（卡片已发给对方本人、等他点同意）
      //   —— 它与 inserted 可以同时非零（服务端逐个被邀请人分流），文案里两句都要说。
      const outcome = addMembersOutcome(r);
      // ★不写 toast[outcome.level](...)：动态取方法名依赖实例方法的 this 绑定，
      //   显式分支只多一行，却不会在 antd 换实现时静默变成 no-op。
      if (outcome.level === 'warning') toast.warning(outcome.text);
      else toast.success(outcome.text);
    } catch (e) {
      toast.error((e as Error).message || '添加失败');
      // ★★失败时【直接返回】：弹窗不关、已选不清 —— 用户原地就能重试。
      //   关掉的话他得把那几个人重新搜一遍（而搜索是远程的，可能已经搜不到了）。
      return;
    } finally {
      setSubmitting(false);
    }

    /**
     * ★★以下三行在 {@code try} <b>之外</b> —— 这不是风格问题，是一个真实的行为差别：
     * 提交此刻已经成功了，下面做的只是"让界面跟上"。混进 try 的后果是
     * {@code onDone} 里任何一步（比如重拉会话列表时网络抖了一下）失败，
     * 都会被 catch 成"添加失败"再弹一句 —— <b>而人其实已经加进去了</b>。
     */
    reset();
    onClose();
    if (r) onDone?.(r);
  };

  /**
   * ★Tab 标题带上<b>已选计数</b>。
   * ★只在非零时显示数字：`人（0）` 每一眼都在提醒用户"你还没选"，
   * 而绝大多数时候他正在选 —— 零值不显示，界面安静，非零才跳出来提醒。
   */
  const tabLabel = (text: string, n: number) => (n > 0 ? `${text}（${n}）` : text);

  return (
    <Modal
      title="添加群员"
      open={open}
      onCancel={close}
      destroyOnClose
      /**
       * ★不用 antd 默认的 onOk/okText：提交按钮要按状态变字（提交中…），
       * 且要在没人选时给一条 warning 而不是静默无反应。
       * ★左「取消」右「确定」的主次与 {@code AddPartnerModal} 一致。
       */
      footer={
        <Space>
          <button className="contact-btn" onClick={close} disabled={submitting}>
            取消
          </button>
          {/* ★★按钮文字刻意【不】是「加入群聊」—— 照搬 MemberPanelBody 里那条既有判断：
              你点下去的结果可能只是"给对方发了一张等待同意的卡片"，人并没有进群。
              按钮上承诺一个做不到的结果、事后靠 toast 再改口，读起来就更像故障了；
              一个中性的「确定」配一句准确的 toast 才是诚实的。
              ★弹窗里那三行分流说明已经把"什么时候不是直接加入"讲清楚了，
                不需要靠按钮文字再承诺一次。 */}
          <button className="contact-btn primary" onClick={onSubmit} disabled={submitting || total === 0}>
            {submitting ? '添加中…' : '确定'}
          </button>
        </Space>
      }
    >
      <Space direction="vertical" style={{ width: '100%' }}>
        <Tabs
          activeKey={tab}
          onChange={(k) => setTab(k === 'agent' ? 'agent' : 'user')}
          items={[
            {
              key: 'user',
              // ★DEV-258：文案「人」→「用户」（用户原话「添加伙伴和添加群员弹框上的
              //   "人"文案改为"用户"」）。★与 AddPartnerModal 那处必须同批改：
              //   两个弹窗的 Tab 是同一套叫法，只改一个会让"用户/人"变成两种口径。
              label: tabLabel('用户', uids.length),
              children: (
                <>
                  {/* ★这句提示是从 MemberPanelBody 原样搬过来的（用户看得见的话，
                      不要在这个搬迁里被"顺手改好一点"而丢掉）。 */}
                  <div className="member-add-hint">
                    只能拉入平台上的「可联系人」（服务端按与创建单聊同一条规则校验）；
                    你和已在群里的人不会出现在候选里。
                  </div>
                  {/* ★排除自己 + 群里已有的人（见 UserSearchSelect 类注释：
                      这是**显示层**优化，不替代服务端的 alreadyIn 幂等）。
                      ★★DEV-355：showMyContacts = 打开弹窗就先列出「我的联系人」
                      （拍板①）。★排除项对**本地**候选同样生效 —— 它走的是同一个
                      excludeKey（见那个组件里的 localPick）。 */}
                  <UserSearchSelect
                    multiple
                    showMyContacts
                    excludeUserIds={[userId, ...(members ?? []).map((m) => m.userId)]}
                    value={uids}
                    onChange={setUids}
                    placeholder="输入用户名或手机号搜索"
                  />
                </>
              ),
            },
            {
              key: 'agent',
              label: tabLabel('智能体', agentIds.length),
              children: (
                <>
                  <Typography.Text type="secondary">搜索已发布的智能体（当前租户内你能用到的）</Typography.Text>
                  {/* ★多选形态：只交 id（onChangeIds），理由见类注释与 AgentSearchSelect。
                      ★★DEV-355：showMyContacts = 空关键字先列出「我的智能体联系人」
                      （拍板③：这个 Tab 只列 subjectType=AGENT 的联系人）。 */}
                  <AgentSearchSelect multiple showMyContacts value={agentIds} onChangeIds={setAgentIds} />
                  {/* ★★DEV-271：选了智能体才出现「衔接模式」。
                      ★为什么是条件渲染而不是一直显示：这个值对**真人**成员没有意义
                      （服务端忽略它），一直挂着会让人以为它也作用于「用户」Tab 里选的那些人 ——
                      而两个 Tab 的已选是**并集一起提交**的，误解会直接落到提交结果上。 */}
                  {agentIds.length > 0 && (
                    <>
                      <Space size={8} align="center" className="member-add-hint">
                        <span>衔接模式</span>
                        {/* ★展开一份：AGENT_MODE_OPTIONS 是 readonly 常量，别让控件拿到它本身。 */}
                        <Segmented
                          size="small"
                          value={agentMode}
                          onChange={(v) => setAgentMode(v as AgentMode)}
                          options={[...AGENT_MODE_OPTIONS]}
                        />
                      </Space>
                      <div className="member-add-hint">
                        {AGENT_MODE_HINT}
                        <br />
                        监听会让群里<b>每条</b>消息都调一次模型（<b>真实费用</b>）；
                        本次添加的智能体都用这个模式，之后可在群成员面板里单独改。
                      </div>
                    </>
                  )}
                </>
              ),
            },
          ]}
        />

        {/* ★★这一段是本弹窗与「添加伙伴」最大的不同：**加人这件事的结果不由你决定**。
            不说清楚的话，操作者看到"3 人等待对方同意"会以为失败了、再点一遍。 */}
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          与你在<b>同一团队</b>的用户：<b>直接加入</b>，无需对方同意。
          <br />
          其他用户：会收到一条系统消息，<b>对方点「同意」后</b>才加入群聊。
          <br />
          智能体：<b>直接加入</b>（智能体不会点「同意」）。
        </Typography.Text>
        {/* ★★DEV-315 需求①（★DEV-336 起内容已翻转）：上面那三行讲的是"**谁能**直接进"，
            这里两行讲的是"与建群入口的关系"—— 旧时代解释"为什么会不一样"，
            现在宣告"同一套规则、结果一致"（服务端建群已改走同一分流，
            再解释差别就是撒谎；旧口径由 groupJoinRule.test.ts 的负断言挡回潮）。
            ★与「创建群聊」那边的文案成对，收在同一个常量里（见 lib/groupJoinRule.ts）。 */}
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          {ADD_MEMBER_JOIN_RULE.here}
          <br />
          {ADD_MEMBER_JOIN_RULE.elsewhere}
        </Typography.Text>
      </Space>
    </Modal>
  );
}
