/**
 * ★★会议邀请消息在气泡里的样子。
 *
 * <h2>★它是"补点入口"，不是"来电页"</h2>
 *
 * <p>来电页（{@code MeetingInviteOverlay}）只在<b>实时到达</b>且用户空闲时弹一次；
 * 用户当时在开会、关掉了页面、或者干脆错过了铃声，这条消息必须还能在会话里点进去。
 * 所以卡片上直接给「加入会议」，不显示"回拨"之类会让人误解的措辞。
 *
 * <h2>★"会议已结束"从哪来（2026-11-09 修正 DEV-251 的口径）</h2>
 *
 * <p>服务端的会议邀请消息只记录邀请本身，<b>不持久化</b>"这场会还在不在"。
 * 曾经的结论是"不知道就不编"，代价是：群里那场通话结束之后，卡片仍然写着
 * 「视频通话 · 点击加入」，点进去才失败 —— 用户 2026-11-09 报的正是这个。
 *
 * <p>现在有一条<b>不引入猜测</b>的路：{@code GET /meetings/public/rooms/{room}}
 * 是匿名端点，能稳定给出 {@code status}（0 未开始 / 1 进行中 / 2 已结束 / 3 已取消）。
 * 于是：
 *
 * <ul>
 *   <li>{@code status === 2} ⇒ 副标题「会议已结束」，禁用点击；</li>
 *   <li>{@code status === 3} ⇒ 副标题「会议已取消」，禁用点击；</li>
 *   <li>其余（0 / 1 / 查询中 / 查询失败 / 查不到记录）⇒ <b>保持原样</b>，仍然可点。</li>
 * </ul>
 *
 * <p>★查询失败<b>绝不当成结束</b>：网络抖一下就把"能进的会"标成已结束，
 * 比"要多点一次才知道结束"糟得多。也正因如此，这个探测用
 * {@code meetingPublicApi.roomInfoSafe}（401 不广播 {@code im:auth-expired}）——
 * 纯展示层的一次查询不该把正在聊天的人踢去登录。
 */
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';

import { meetingPublicApi } from '../api';
import type { MessageDto } from '../api/types';
import { meetingInviteTitle, parseMeetingInvite } from '../lib/meetingInvite';
import { useCallStore } from '../store/call';
import { useMeetingInviteStore } from '../store/meetingInvite';
import { IconPhone, IconUsers, IconVideo } from './icons';

interface Props {
  message: MessageDto;
}

export default function MeetingInviteCard({ message }: Props) {
  const invite = parseMeetingInvite(message.body);
  const phase = useCallStore((s) => s.phase);
  const [hint, setHint] = useState<string | null>(null);

  const busy = phase !== 'idle';
  const title = invite ? meetingInviteTitle(invite) : '会议邀请';

  /**
   * ★查一次这场会还在不在（匿名端点，失败不影响任何东西）。
   *
   * <p>★{@code staleTime} 比全局 30s 略短、并在窗口重新获得焦点时重查：
   * 用户常见路径是"开会时把 IM 切到后台，散会后切回来"——
   * 那一刻卡片必须立刻变成「会议已结束」，不能还挂着「点击加入」。
   */
  const roomQ = useQuery({
    queryKey: ['meeting-room-state', invite?.roomName ?? ''],
    queryFn: () => meetingPublicApi.roomInfoSafe(invite?.roomName ?? ''),
    enabled: !!invite?.roomName,
    staleTime: 20_000,
    retry: 1,
    refetchOnWindowFocus: true,
  });

  /**
   * ★只认服务端明确给出的 2 / 3，其余一律当"不知道"。
   *
   * <p>★{@code status} 为 null 的两种常见情况（会议模块未开启、记录已被删除）
   * 都不能解释成已结束 —— 删了记录的会可能还在开，访客路径那边也是同样的判断。
   */
  const roomStatus = roomQ.data?.status ?? null;
  const ended = roomStatus === 2;
  const canceled = roomStatus === 3;
  const inactive = ended || canceled;
  /** 副标题里"能不能点"的那半句。★busy 优先，与改造前一致。 */
  const actionText = busy
    ? '结束后可加入'
    : ended
      ? '会议已结束'
      : canceled
        ? '会议已取消'
        : '点击加入';

  /**
   * ★★群通话卡片（{@code groupCall:true}，只会出现在群里那条静默卡片上）。
   *
   * <p>为什么不是"会议"口径：用户发起的是语音/视频通话，卡片说「会议」会让人以为
   * 点进去是一个会要开很久。图标也跟着媒体类型走 —— 语音卡片画话筒、视频卡片画摄像机，
   * 扫一眼就知道点进去要不要开摄像头。
   *
   * <p>★普通会议邀请（{@code groupCall} 缺省）保持原样：`IconUsers` + 会议号。
   */
  const isGroupCall = invite?.groupCall === true;
  const mediaLabel = invite?.mediaType === 'video' ? '视频通话' : '语音通话';

  const join = () => {
    if (!invite) return;
    // ★带上消息坐标：加入后要让同账号的其它端停掉这条邀请的铃声（3007 同步）
    const r = useMeetingInviteStore.getState().joinInvite(invite, {
      convId: String(message.convId),
      msgId: message.msgId == null ? undefined : String(message.msgId),
    });
    if (r === 'busy') setHint('你正在通话或会议中，请先结束后再加入');
    else setHint(r === 'none' ? '暂时无法加入，请稍后重试' : null);
  };

  return (
    <button
      type="button"
      className={`meet-invite-card${busy ? ' is-busy' : ''}${inactive ? ' is-ended' : ''}`}
      title={
        busy
          ? '你正在通话或会议中'
          : ended
            ? '这场会议已经结束'
            : canceled
              ? '这场会议已经取消'
              : isGroupCall
                ? `加入${mediaLabel} ${invite?.roomName ?? ''}`
                : `加入会议 ${invite?.roomName ?? ''}`
      }
      // ★已结束/已取消：禁用点击，而不是"点了再报错"。
      disabled={!invite || inactive}
      onClick={invite && !inactive ? join : undefined}
    >
      <span className="meet-invite-card-icon">
        {isGroupCall ? (
          invite?.mediaType === 'video' ? (
            <IconVideo size={18} />
          ) : (
            <IconPhone size={18} />
          )
        ) : (
          <IconUsers size={18} />
        )}
      </span>
      <span className="meet-invite-card-text">
        <span className="meet-invite-card-title">{title}</span>
        <span className="meet-invite-card-sub">
          {invite
            ? isGroupCall
              ? `${mediaLabel} · ${actionText}`
              : `会议号 ${invite.roomName} · ${actionText}`
            : '邀请信息不完整'}
        </span>
        {hint && <span className="meet-invite-card-hint">{hint}</span>}
      </span>
    </button>
  );
}
